  std::any nonce() override {
    return subtract(this->milliseconds(),
                    ::getValue(this->options, std::string("timeDifference")));
  }

  /**
   * @method
   * @name kucoin#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/market-data/get-server-time
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/market-data/get-server-time
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<std::any>
  fetchTime(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchTime"), std::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(isTrue((!isEqual(type, std::string("spot")))) &&
                            isTrue((!isEqual(type, std::string("margin")))))) {
                   //
                   //    {
                   //        "code": "200000",
                   //        "data": 1637385119302,
                   //    }
                   //
                   response =
                       awaitValue(this->futuresPublicGetTimestamp(params));
                 } else {
                   //
                   //     {
                   //         "code":"200000",
                   //         "msg":"success",
                   //         "data":1546837113087
                   //     }
                   //
                   response = awaitValue(this->publicGetTimestamp(params));
                 }
                 return this->safeInteger(response, std::string("data"));
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/market-data/get-service-status
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/market-data/get-service-status
   * @see https://www.kucoin.com/docs-new/rest/ua/get-service-status
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] spot or swap
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {string} [params.tradeType] *uta only* set to SPOT or FUTURES
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<std::any>
  fetchStatus(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any uta = false;
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchStatus"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchStatus"), std::any{}, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(uta)) {
                   std::any defaultType = this->safeString(
                       this->options, std::string("defaultType"),
                       std::string("spot"));
                   std::any defaultTradeType =
                       (isTrue((isEqual(defaultType, std::string("spot"))))
                            ? std::any(std::string("SPOT"))
                            : std::any(std::string("FUTURES")));
                   std::any tradeType = this->safeStringUpper(
                       params, std::string("tradeType"), defaultTradeType);
                   std::any request = ccxt::dict{
                       {std::string("tradeType"), tradeType},
                   };
                   response = awaitValue(
                       this->utaGetServerStatus(this->extend(request, params)));
                 } else if (isTrue(
                                isTrue((!isEqual(type, std::string("spot")))) &&
                                isTrue(
                                    (!isEqual(type, std::string("margin")))))) {
                   response = awaitValue(this->futuresPublicGetStatus(params));
                 } else {
                   response = awaitValue(this->publicGetStatus(params));
                 }
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any status = this->safeString2(
                     data, std::string("status"), std::string("serverStatus"));
                 return ccxt::dict{
                     {std::string("status"),
                      (isTrue((isEqual(status, std::string("open"))))
                           ? std::any(std::string("ok"))
                           : std::any(std::string("maintenance")))},
                     {std::string("updated"), std::any{}},
                     {std::string("eta"), std::any{}},
                     {std::string("url"), std::any{}},
                     {std::string("info"), response},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchMarkets
   * @description retrieves data on all markets for kucoin
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/market-data/get-all-symbols
   * @see https://www.kucoin.com/docs-new/rest/ua/get-symbol
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/market-data/get-all-symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<std::any>
  fetchMarkets(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any fetchTickersFees = std::any{};
                 std::any fetchTickersFeesparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchMarkets"),
                         std::string("fetchTickersFees"), true);
                 fetchTickersFees =
                     ::getValue(fetchTickersFeesparamsVariable, 0);
                 params = ::getValue(fetchTickersFeesparamsVariable, 1);
                 std::any uta = false;
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMarkets"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(uta)) {
                   return awaitValue(this->fetchUTAMarkets(params));
                 }
                 std::any defaultTypes =
                     ccxt::list{std::string("spot"), std::string("swap"),
                                std::string("future"), std::string("contract")};
                 std::any fetchMarketsOptions =
                     this->safeDict(this->options, std::string("fetchMarkets"));
                 std::any types = this->safeList(
                     fetchMarketsOptions, std::string("types"), defaultTypes);
                 std::any credentialsSet =
                     this->checkRequiredCredentials(false);
                 std::any requestMarginables =
                     isTrue(credentialsSet) &&
                     isTrue(this->safeBool(params, std::string("marginables"),
                                           true));
                 params = this->omit(params, std::string("marginables"));
                 std::any fetchContractMarkets = false;
                 if (isTrue(isTrue(isTrue(this->inArray(std::string("swap"),
                                                        types)) ||
                                   isTrue(this->inArray(std::string("future"),
                                                        types))) ||
                            isTrue(this->inArray(std::string("contract"),
                                                 types)))) {
                   fetchContractMarkets = true;
                 }
                 std::any fetchSpotMarkets =
                     this->inArray(std::string("spot"), types);
                 fetchTickersFees =
                     isTrue(fetchTickersFees) &&
                     isTrue(fetchSpotMarkets); // tickers and fees are only
                                               // fetched for spot markets
                 std::any promises = ccxt::list{};
                 if (isTrue(fetchSpotMarkets)) {
                   arrayPush(promises, this->publicGetSymbols(params));
                 }
                 if (isTrue(isEqual(requestMarginables, true))) {
                   arrayPush(promises, this->privateGetMarginSymbols(
                                           params)); // cross margin symbols
                   //
                   //    {
                   //        "code": "200000",
                   //        "data": {
                   //            "timestamp": 1719393213421,
                   //            "items": [
                   //                {
                   //                    // same object as in market, with one
                   //                    additional field: "minFunds": "0.1"
                   //                },
                   //
                   arrayPush(promises, this->privateGetIsolatedSymbols(
                                           params)); // isolated margin symbols
                 }
                 if (isTrue(fetchTickersFees)) {
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": {
                   //             "time":1602832092060,
                   //             "ticker":[
                   //                 {
                   //                     "symbol": "BTC-USDT",   // symbol
                   //                     "symbolName":"BTC-USDT", // Name of
                   //                     trading pairs, it would change after
                   //                     renaming "buy": "11328.9",   //
                   //                     bestAsk "sell": "11329",    // bestBid
                   //                     "changeRate": "-0.0055",    // 24h
                   //                     change rate "changePrice": "-63.6", //
                   //                     24h change price "high": "11610", //
                   //                     24h highest price "low": "11200", //
                   //                     24h lowest price "vol":
                   //                     "2282.70993217", // 24h volume，the
                   //                     aggregated trading volume in BTC
                   //                     "volValue": "25984946.157790431",   //
                   //                     24h total, the trading volume in quote
                   //                     currency of last 24 hours "last":
                   //                     "11328.9",  // last price
                   //                     "averagePrice": "11360.66065903",   //
                   //                     24h average transaction price
                   //                     yesterday "takerFeeRate": "0.001", //
                   //                     Basic Taker Fee "makerFeeRate":
                   //                     "0.001",    // Basic Maker Fee
                   //                     "takerCoefficient": "1",    // Taker
                   //                     Fee Coefficient "makerCoefficient":
                   //                     "1" // Maker Fee Coefficient
                   //                 }
                   //
                   arrayPush(promises, this->publicGetMarketAllTickers(params));
                 }
                 if (isTrue(fetchContractMarkets)) {
                   arrayPush(promises, this->fetchContractMarkets(params));
                 }
                 if (isTrue(credentialsSet)) {
                   // load migration status for account
                   arrayPush(promises, this->loadMigrationStatus());
                 }
                 std::any responses = awaitValue(promiseAll(promises));
                 std::any symbolsData =
                     (isTrue(fetchSpotMarkets)
                          ? std::any(this->safeList(::getValue(responses, 0),
                                                    std::string("data"),
                                                    ccxt::list{}))
                          : std::any(ccxt::list{}));
                 std::any crossIndex = 0;
                 std::any isolatedIndex = 0;
                 std::any tickersIndex = 0;
                 std::any contractIndex = 0;
                 std::any nextIndex = 0;
                 if (isTrue(fetchSpotMarkets)) {
                   nextIndex = 1;
                 }
                 if (isTrue(isEqual(requestMarginables, true))) {
                   crossIndex = nextIndex;
                   nextIndex = this->sum(nextIndex, 2);
                   isolatedIndex = this->sum(crossIndex, 1);
                 }
                 if (isTrue(fetchTickersFees)) {
                   tickersIndex = nextIndex;
                   nextIndex = this->sum(nextIndex, 1);
                 }
                 if (isTrue(fetchContractMarkets)) {
                   contractIndex = nextIndex;
                 }
                 std::any crossData =
                     (isTrue((isEqual(requestMarginables, true)))
                          ? std::any(this->safeDict(
                                ::getValue(responses, crossIndex),
                                std::string("data"), ccxt::dict{}))
                          : std::any(ccxt::dict{}));
                 std::any crossItems = this->safeList(
                     crossData, std::string("items"), ccxt::list{});
                 std::any crossById =
                     this->indexBy(crossItems, std::string("symbol"));
                 std::any isolatedData =
                     (isTrue((isEqual(requestMarginables, true)))
                          ? std::any(::getValue(responses, isolatedIndex))
                          : std::any(ccxt::dict{}));
                 std::any isolatedItems = this->safeList(
                     isolatedData, std::string("data"), ccxt::list{});
                 std::any isolatedById =
                     this->indexBy(isolatedItems, std::string("symbol"));
                 std::any tickersResponse =
                     (isTrue(fetchTickersFees)
                          ? std::any(this->safeDict(responses, tickersIndex,
                                                    ccxt::dict{}))
                          : std::any(ccxt::dict{}));
                 std::any tickerItems = this->safeList(
                     this->safeDict(tickersResponse, std::string("data"),
                                    ccxt::dict{}),
                     std::string("ticker"), ccxt::list{});
                 std::any tickersById =
                     this->indexBy(tickerItems, std::string("symbol"));
                 std::any result = ccxt::list{};
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(symbolsData));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(symbolsData, i);
                   std::any id =
                       this->safeString(market, std::string("symbol"));
                   if (isTrue(isEqual(id, std::any{}))) {
                     continue;
                   }
                   std::any baseIdquoteIdVariable = split(id, std::string("-"));
                   std::any baseId = ::getValue(baseIdquoteIdVariable, 0);
                   std::any quoteId = ::getValue(baseIdquoteIdVariable, 1);
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   // const quoteIncrement = this.safeNumber (market,
                   // 'quoteIncrement');
                   std::any ticker =
                       this->safeDict(tickersById, id, ccxt::dict{});
                   std::any makerFeeRate =
                       this->safeString(ticker, std::string("makerFeeRate"));
                   std::any takerFeeRate =
                       this->safeString(ticker, std::string("takerFeeRate"));
                   std::any makerCoefficient = this->safeString(
                       ticker, std::string("makerCoefficient"));
                   std::any takerCoefficient = this->safeString(
                       ticker, std::string("takerCoefficient"));
                   std::any hasCrossMargin = (inOp(crossById, id));
                   std::any hasIsolatedMargin = (inOp(isolatedById, id));
                   std::any isMarginable =
                       isTrue(isTrue(this->safeBool(
                                  market, std::string("isMarginEnabled"),
                                  false)) ||
                              isTrue(hasCrossMargin)) ||
                       isTrue(hasIsolatedMargin);
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("symbol"),
                            add(add(base, std::string("/")), quote)},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), std::any{}},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), std::any{}},
                           {std::string("type"), std::string("spot")},
                           {std::string("spot"), true},
                           {std::string("margin"), isMarginable},
                           {std::string("marginModes"),
                            ccxt::dict{
                                {std::string("cross"), hasCrossMargin},
                                {std::string("isolated"), hasIsolatedMargin},
                            }},
                           {std::string("swap"), false},
                           {std::string("future"), false},
                           {std::string("option"), false},
                           {std::string("active"),
                            this->safeBool(market,
                                           std::string("enableTrading"))},
                           {std::string("contract"), false},
                           {std::string("linear"), std::any{}},
                           {std::string("inverse"), std::any{}},
                           {std::string("taker"),
                            this->parseNumber(ccxt::Precise::stringMul(
                                takerFeeRate, takerCoefficient))},
                           {std::string("maker"),
                            this->parseNumber(ccxt::Precise::stringMul(
                                makerFeeRate, makerCoefficient))},
                           {std::string("contractSize"), std::any{}},
                           {std::string("expiry"), std::any{}},
                           {std::string("expiryDatetime"), std::any{}},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->safeNumber(
                                     market, std::string("baseIncrement"))},
                                {std::string("price"),
                                 this->safeNumber(
                                     market, std::string("priceIncrement"))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("baseMinSize"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market, std::string("baseMaxSize"))},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"), std::any{}},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("quoteMinSize"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market, std::string("quoteMaxSize"))},
                                 }},
                            }},
                           {std::string("created"), std::any{}},
                           {std::string("info"), market},
                       });
                 }
                 if (isTrue(fetchContractMarkets)) {
                   std::any contractMarkets =
                       this->safeList(responses, contractIndex, ccxt::list{});
                   result = this->arrayConcat(result, contractMarkets);
                 }
                 if (isTrue(isEqual(
                         ::getValue(this->options,
                                    std::string("adjustForTimeDifference")),
                         true))) {
                   awaitValue(this->loadTimeDifference());
                 }
                 return result;
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchContractMarkets(std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response =
                     awaitValue(this->futuresPublicGetContractsActive(params));
                 //
                 //    {
                 //        "code": "200000",
                 //        "data": {
                 //            "symbol": "ETHUSDTM",
                 //            "rootSymbol": "USDT",
                 //            "type": "FFWCSX",
                 //            "firstOpenDate": 1591086000000,
                 //            "expireDate": null,
                 //            "settleDate": null,
                 //            "baseCurrency": "ETH",
                 //            "quoteCurrency": "USDT",
                 //            "settleCurrency": "USDT",
                 //            "maxOrderQty": 1000000,
                 //            "maxPrice": 1000000.0000000000,
                 //            "lotSize": 1,
                 //            "tickSize": 0.05,
                 //            "indexPriceTickSize": 0.01,
                 //            "multiplier": 0.01,
                 //            "initialMargin": 0.01,
                 //            "maintainMargin": 0.005,
                 //            "maxRiskLimit": 1000000,
                 //            "minRiskLimit": 1000000,
                 //            "riskStep": 500000,
                 //            "makerFeeRate": 0.00020,
                 //            "takerFeeRate": 0.00060,
                 //            "takerFixFee": 0.0000000000,
                 //            "makerFixFee": 0.0000000000,
                 //            "settlementFee": null,
                 //            "isDeleverage": true,
                 //            "isQuanto": true,
                 //            "isInverse": false,
                 //            "markMethod": "FairPrice",
                 //            "fairMethod": "FundingRate",
                 //            "fundingBaseSymbol": ".ETHINT8H",
                 //            "fundingQuoteSymbol": ".USDTINT8H",
                 //            "fundingRateSymbol": ".ETHUSDTMFPI8H",
                 //            "indexSymbol": ".KETHUSDT",
                 //            "settlementSymbol": "",
                 //            "status": "Open",
                 //            "fundingFeeRate": 0.000535,
                 //            "predictedFundingFeeRate": 0.002197,
                 //            "openInterest": "8724443",
                 //            "turnoverOf24h": 341156641.03354263,
                 //            "volumeOf24h": 74833.54000000,
                 //            "markPrice": 4534.07,
                 //            "indexPrice":4531.92,
                 //            "lastTradePrice": 4545.4500000000,
                 //            "nextFundingRateTime": 25481884,
                 //            "maxLeverage": 100,
                 //            "sourceExchanges":  [ "huobi", "Okex", "Binance",
                 //            "Kucoin", "Poloniex", "Hitbtc" ],
                 //            "premiumsSymbol1M": ".ETHUSDTMPI",
                 //            "premiumsSymbol8H": ".ETHUSDTMPI8H",
                 //            "fundingBaseSymbol1M": ".ETHINT",
                 //            "fundingQuoteSymbol1M": ".USDTINT",
                 //            "lowPrice": 4456.90,
                 //            "highPrice":  4674.25,
                 //            "priceChgPct": 0.0046,
                 //            "priceChg": 21.15
                 //        }
                 //    }
                 //
                 std::any result = ccxt::list{};
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 for (std::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(data, i);
                   std::any id =
                       this->safeString(market, std::string("symbol"));
                   std::any expiry =
                       this->safeInteger(market, std::string("expireDate"));
                   std::any future =
                       isEqual(this->safeString(
                                   market, std::string("nextFundingRateTime")),
                               std::any{});
                   std::any swap = !isTrue(future);
                   std::any baseId =
                       this->safeString(market, std::string("baseCurrency"));
                   std::any quoteId =
                       this->safeString(market, std::string("quoteCurrency"));
                   std::any settleId =
                       this->safeString(market, std::string("settleCurrency"));
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   std::any settle = this->safeCurrencyCode(settleId);
                   std::any symbol =
                       add(add(add(add(base, std::string("/")), quote),
                               std::string(":")),
                           settle);
                   std::any type = std::string("swap");
                   if (isTrue(future)) {
                     symbol = add(add(symbol, std::string("-")),
                                  this->yymmdd(expiry, std::string("")));
                     type = std::string("future");
                   }
                   std::any inverse =
                       this->safeValue(market, std::string("isInverse"));
                   std::any status =
                       this->safeString(market, std::string("status"));
                   std::any multiplier =
                       this->safeString(market, std::string("multiplier"));
                   std::any tickSize =
                       this->safeNumber(market, std::string("tickSize"));
                   std::any lotSize =
                       this->safeNumber(market, std::string("lotSize"));
                   std::any limitAmountMin = lotSize;
                   if (isTrue(isEqual(limitAmountMin, std::any{}))) {
                     limitAmountMin =
                         this->safeNumber(market, std::string("baseMinSize"));
                   }
                   std::any limitAmountMax =
                       this->safeNumber(market, std::string("maxOrderQty"));
                   if (isTrue(isEqual(limitAmountMax, std::any{}))) {
                     limitAmountMax =
                         this->safeNumber(market, std::string("baseMaxSize"));
                   }
                   std::any limitPriceMax =
                       this->safeNumber(market, std::string("maxPrice"));
                   if (isTrue(isEqual(limitPriceMax, std::any{}))) {
                     std::any baseMinSizeString =
                         this->safeString(market, std::string("baseMinSize"));
                     std::any quoteMaxSizeString =
                         this->safeString(market, std::string("quoteMaxSize"));
                     limitPriceMax = this->parseNumber(ccxt::Precise::stringDiv(
                         quoteMaxSizeString, baseMinSizeString));
                   }
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("symbol"), symbol},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), settle},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), settleId},
                           {std::string("type"), type},
                           {std::string("spot"), false},
                           {std::string("margin"), false},
                           {std::string("swap"), swap},
                           {std::string("future"), future},
                           {std::string("option"), false},
                           {std::string("active"),
                            (isEqual(status, std::string("Open")))},
                           {std::string("contract"), true},
                           {std::string("linear"), (!isEqual(inverse, true))},
                           {std::string("inverse"), inverse},
                           {std::string("taker"),
                            this->safeNumber(market,
                                             std::string("takerFeeRate"))},
                           {std::string("maker"),
                            this->safeNumber(market,
                                             std::string("makerFeeRate"))},
                           {std::string("contractSize"),
                            this->parseNumber(
                                ccxt::Precise::stringAbs(multiplier))},
                           {std::string("expiry"), expiry},
                           {std::string("expiryDatetime"),
                            this->iso8601(expiry)},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"), lotSize},
                                {std::string("price"), tickSize},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->parseNumber(std::string("1"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market, std::string("maxLeverage"))},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"), limitAmountMin},
                                     {std::string("max"), limitAmountMax},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), tickSize},
                                     {std::string("max"), limitPriceMax},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market, std::string("quoteMinSize"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market, std::string("quoteMaxSize"))},
                                 }},
                            }},
                           {std::string("created"),
                            this->safeInteger(market,
                                              std::string("firstOpenDate"))},
                           {std::string("info"), market},
                       });
                 }
                 return result;
               })
        .share();
  }

  virtual std::shared_future<std::any>
  fetchUTAMarkets(std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any promises = ccxt::list{};
                 arrayPush(promises, this->utaGetMarketInstrument(this->extend(
                                         params, ccxt::dict{
                                                     {std::string("tradeType"),
                                                      std::string("SPOT")},
                                                 })));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": {
                 //             "tradeType": "SPOT",
                 //             "list": [
                 //                 {
                 //                     "symbol": "AVA-USDT",
                 //                     "name": "AVA-USDT",
                 //                     "baseCurrency": "AVA",
                 //                     "quoteCurrency": "USDT",
                 //                     "market": "USDS",
                 //                     "minBaseOrderSize": "0.1",
                 //                     "minQuoteOrderSize": "0.1",
                 //                     "maxBaseOrderSize": "10000000000",
                 //                     "maxQuoteOrderSize": "99999999",
                 //                     "baseOrderStep": "0.01",
                 //                     "quoteOrderStep": "0.0001",
                 //                     "tickSize": "0.0001",
                 //                     "feeCurrency": "USDT",
                 //                     "tradingStatus": "1",
                 //                     "marginMode": "2",
                 //                     "priceLimitRatio": "0.05",
                 //                     "feeCategory": 1,
                 //                     "makerFeeCoefficient": "1.00",
                 //                     "takerFeeCoefficient": "1.00",
                 //                     "st": false
                 //                 },
                 //             ]
                 //         }
                 //     }
                 //
                 arrayPush(promises, this->utaGetMarketInstrument(this->extend(
                                         params, ccxt::dict{
                                                     {std::string("tradeType"),
                                                      std::string("FUTURES")},
                                                 })));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": {
                 //             "tradeType": "FUTURES",
                 //             "list": [
                 //                 {
                 //                     "symbol": "XBTUSDTM",
                 //                     "baseCurrency": "XBT",
                 //                     "quoteCurrency": "USDT",
                 //                     "maxBaseOrderSize": "1000000",
                 //                     "tickSize": "0.1",
                 //                     "tradingStatus": "1",
                 //                     "settlementCurrency": "USDT",
                 //                     "contractType": "0",
                 //                     "isInverse": false,
                 //                     "launchTime": 1585555200000,
                 //                     "expiryTime": null,
                 //                     "settlementTime": null,
                 //                     "maxPrice": "1000000.0",
                 //                     "lotSize": "1",
                 //                     "unitSize": "0.001",
                 //                     "makerFeeRate": "0.00020",
                 //                     "takerFeeRate": "0.00060",
                 //                     "settlementFeeRate": null,
                 //                     "maxLeverage": 125,
                 //                     "indexSourceExchanges":
                 //                     ["okex","binance","kucoin","bybit","bitmart","gateio"],
                 //                     "k": "490.0",
                 //                     "m": "300.0",
                 //                     "f": "1.3",
                 //                     "mmrLimit": "0.3",
                 //                     "mmrLevConstant": "125.0"
                 //                 },
                 //             ]
                 //         }
                 //     }
                 //
                 std::any responses = awaitValue(promiseAll(promises));
                 std::any data =
                     this->safeDict(::getValue(responses, 0),
                                    std::string("data"), ccxt::dict{});
                 std::any contractData =
                     this->safeDict(::getValue(responses, 1),
                                    std::string("data"), ccxt::dict{});
                 std::any spotData =
                     this->safeList(data, std::string("list"), ccxt::list{});
                 std::any contractSymbolsData = this->safeList(
                     contractData, std::string("list"), ccxt::list{});
                 std::any symbolsData =
                     this->arrayConcat(spotData, contractSymbolsData);
                 std::any result = ccxt::list{};
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(symbolsData));
                      postFixIncrement(i)) {
                   std::any market = ::getValue(symbolsData, i);
                   std::any id =
                       this->safeString(market, std::string("symbol"));
                   std::any baseId =
                       this->safeString(market, std::string("baseCurrency"));
                   std::any quoteId =
                       this->safeString(market, std::string("quoteCurrency"));
                   std::any settleId = this->safeString(
                       market, std::string("settlementCurrency"));
                   std::any base = this->safeCurrencyCode(baseId);
                   std::any quote = this->safeCurrencyCode(quoteId);
                   std::any settle = this->safeCurrencyCode(settleId);
                   std::any hasMargin =
                       this->safeString(market, std::string("marginMode"));
                   std::any isMarginable =
                       (isTrue((isEqual(hasMargin, std::string("1"))))
                            ? std::any(true)
                            : std::any(false));
                   std::any symbol = add(add(base, std::string("/")), quote);
                   if (isTrue(!isEqual(settle, std::any{}))) {
                     symbol = add(symbol, add(std::string(":"), settle));
                   }
                   std::any contractType =
                       this->safeString(market, std::string("contractType"));
                   std::any expiry =
                       this->safeInteger(market, std::string("expiryTime"));
                   std::any active =
                       this->safeString(market, std::string("tradingStatus"));
                   std::any type = std::any{};
                   std::any spot = false;
                   std::any swap = false;
                   std::any future = false;
                   std::any contract = false;
                   std::any linear = false;
                   std::any inverse = false;
                   if (isTrue(!isEqual(contractType, std::any{}))) {
                     contract = true;
                     if (isTrue(isEqual(quote, settle))) {
                       linear = true;
                     } else {
                       inverse = true;
                     }
                     if (isTrue(isEqual(contractType, std::string("0")))) {
                       type = std::string("swap");
                       swap = true;
                     } else {
                       type = std::string("future");
                       future = true;
                     }
                   } else {
                     type = std::string("spot");
                     spot = true;
                   }
                   arrayPush(
                       result,
                       ccxt::dict{
                           {std::string("id"), id},
                           {std::string("symbol"), symbol},
                           {std::string("base"), base},
                           {std::string("quote"), quote},
                           {std::string("settle"), settle},
                           {std::string("baseId"), baseId},
                           {std::string("quoteId"), quoteId},
                           {std::string("settleId"), settleId},
                           {std::string("type"), type},
                           {std::string("spot"), spot},
                           {std::string("margin"), isMarginable},
                           {std::string("swap"), swap},
                           {std::string("future"), future},
                           {std::string("option"), false},
                           {std::string("active"),
                            (isEqual(active, std::string("1")))},
                           {std::string("contract"), contract},
                           {std::string("linear"), linear},
                           {std::string("inverse"), inverse},
                           {std::string("taker"),
                            this->safeNumber(market,
                                             std::string("makerFeeRate"))},
                           {std::string("maker"),
                            this->safeNumber(market,
                                             std::string("takerFeeRate"))},
                           {std::string("contractSize"),
                            this->safeNumber(market, std::string("unitSize"))},
                           {std::string("expiry"), expiry},
                           {std::string("expiryDatetime"),
                            this->iso8601(expiry)},
                           {std::string("strike"), std::any{}},
                           {std::string("optionType"), std::any{}},
                           {std::string("precision"),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->safeNumber2(
                                     market, std::string("lotSize"),
                                     std::string("baseOrderStep"))},
                                {std::string("price"),
                                 this->safeNumber(market,
                                                  std::string("tickSize"))},
                            }},
                           {std::string("limits"),
                            ccxt::dict{
                                {std::string("leverage"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"),
                                      this->safeInteger(
                                          market, std::string("maxLeverage"))},
                                 }},
                                {std::string("amount"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market,
                                          std::string("minBaseOrderSize"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market,
                                          std::string("maxBaseOrderSize"))},
                                 }},
                                {std::string("price"),
                                 ccxt::dict{
                                     {std::string("min"), std::any{}},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market, std::string("maxPrice"))},
                                 }},
                                {std::string("cost"),
                                 ccxt::dict{
                                     {std::string("min"),
                                      this->safeNumber(
                                          market,
                                          std::string("minQuoteOrderSize"))},
                                     {std::string("max"),
                                      this->safeNumber(
                                          market,
                                          std::string("maxQuoteOrderSize"))},
                                 }},
                            }},
                           {std::string("created"),
                            this->safeInteger(market,
                                              std::string("launchTime"))},
                           {std::string("info"), market},
                       });
                 }
                 if (isTrue(isEqual(
                         ::getValue(this->options,
                                    std::string("adjustForTimeDifference")),
                         true))) {
                   awaitValue(this->loadTimeDifference());
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#loadMigrationStatus
   * @param {boolean} force load account state for non hf
   * @description loads the migration status for the account (hf or not)
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/account-funding/get-account-type-spot
   * @returns {any} ignore
   */
  virtual std::shared_future<std::any>
  loadMigrationStatus(std::any force = false) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(
                         isTrue(!isTrue(
                                    (inOp(this->options, std::string("hf")))) ||
                                isTrue((isEqual(::getValue(this->options,
                                                           std::string("hf")),
                                                std::any{})))) ||
                         isTrue(force))) {
                   std::any result =
                       awaitValue(this->privateGetHfAccountsOpened());
                   ::setValue(this->options, std::string("hf"),
                              this->safeBool(result, std::string("data")));
                 }
                 return true;
               })
        .share();
  }

  virtual std::any handleHfAndParams(std::any params = ccxt::dict{}) {
    std::any migrated = this->safeBool(this->options, std::string("hf"), false);
    std::any loadedHf = std::any{};
    if (isTrue(!isEqual(migrated, std::any{}))) {
      if (isTrue(migrated)) {
        loadedHf = true;
      } else {
        loadedHf = false;
      }
    }
    std::any hf = this->safeBool(params, std::string("hf"), loadedHf);
    params = this->omit(params, std::string("hf"));
    return ccxt::list{hf, params};
  }

  /**
   * @method
   * @name kucoin#fetchCurrencies
   * @description fetches all available currencies on an exchange
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/market-data/get-all-currencies
   * @see https://www.kucoin.com/docs-new/rest/ua/get-currencies
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} an associative dictionary of currencies
   */
  std::shared_future<std::any>
  fetchCurrencies(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any uta = false;
                 if (isTrue(this->checkRequiredCredentials(false))) {
                   uta = awaitValue(this->isUTAEnabled());
                 }
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchCurrencies"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(uta)) {
                   response = awaitValue(this->utaGetAssetCurrencies(params));
                 } else {
                   //
                   //    {
                   //        "code":"200000",
                   //        "data":[
                   //           {
                   //              "currency":"CSP",
                   //              "name":"CSP",
                   //              "fullName":"Caspian",
                   //              "precision":8,
                   //              "confirms":null,
                   //              "contractAddress":null,
                   //              "isMarginEnabled":false,
                   //              "isDebitEnabled":false,
                   //              "chains":[
                   //                 {
                   //                    "chainName":"ERC20",
                   //                    "chainId": "eth"
                   //                    "withdrawalMinSize":"2999",
                   //                    "depositMinSize":null,
                   //                    "withdrawFeeRate":"0",
                   //                    "withdrawalMinFee":"2999",
                   //                    "isWithdrawEnabled":false,
                   //                    "isDepositEnabled":false,
                   //                    "confirms":12,
                   //                    "preConfirms":12,
                   //                    "withdrawPrecision": 8,
                   //                    "maxWithdraw": null,
                   //                    "maxDeposit": null,
                   //                    "needTag": false,
                   //                    "contractAddress":"0xa6446d655a0c34bc4f05042ee88170d056cbaf45",
                   //                    "depositFeeRate": "0.001", // present
                   //                    for some currencies/networks
                   //                 }
                   //              ]
                   //           },
                   //        ]
                   //    }
                   //
                   response = awaitValue(this->publicGetCurrencies(params));
                 }
                 std::any currenciesData = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 std::any brokenCurrencies = this->handleOption(
                     std::string("fetchCurrencies"),
                     std::string("brokenCurrencies"), ccxt::list{});
                 std::any filteredCurrencies = this->filterOutByArray(
                     currenciesData, std::string("currency"),
                     brokenCurrencies); // remove broken entries
                 return this->parseCurrencies(filteredCurrencies);
               })
        .share();
  }

  std::any parseCurrency(std::any currency) override {
    std::any entry = currency;
    std::any id = this->safeString(entry, std::string("currency"));
    std::any code = this->safeCurrencyCode(id);
    std::any networks = ccxt::dict{};
    std::any chains = this->safeList2(entry, std::string("chains"),
                                      std::string("items"), ccxt::list{});
    std::any chainsLength = getArrayLength(chains);
    for (std::any j = 0; isLessThan(j, chainsLength); postFixIncrement(j)) {
      std::any chain = ::getValue(chains, j);
      std::any chainId = this->safeString(chain, std::string("chainId"));
      std::any networkCode = this->networkIdToCode(chainId, code);
      if (isTrue(!isEqual(networkCode, std::any{}))) {
        ::setValue(
            networks, networkCode,
            ccxt::dict{
                {std::string("info"), chain},
                {std::string("id"), chainId},
                {std::string("name"),
                 this->safeString(chain, std::string("chainName"))},
                {std::string("code"), networkCode},
                {std::string("active"), std::any{}},
                {std::string("fee"),
                 this->safeNumber2(chain, std::string("withdrawalMinFee"),
                                   std::string("minWithdrawFee"))},
                {std::string("deposit"),
                 this->safeBool(chain, std::string("isDepositEnabled"))},
                {std::string("withdraw"),
                 this->safeBool(chain, std::string("isWithdrawEnabled"))},
                {std::string("precision"),
                 this->parseNumber(this->parsePrecision(this->safeString(
                     chain, std::string("withdrawPrecision"))))},
                {std::string("limits"),
                 ccxt::dict{
                     {std::string("withdraw"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber2(chain,
                                             std::string("withdrawalMinSize"),
                                             std::string("minWithdrawSize"))},
                          {std::string("max"),
                           this->safeNumber2(chain, std::string("maxWithdraw"),
                                             std::string("maxWithdrawSize"))},
                      }},
                     {std::string("deposit"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber2(chain,
                                             std::string("depositMinSize"),
                                             std::string("minDepositSize"))},
                          {std::string("max"),
                           this->safeNumber2(chain, std::string("maxDeposit"),
                                             std::string("maxDepositSize"))},
                      }},
                 }},
            });
      }
    }
    // kucoin has determined 'fiat' currencies with below logic
    std::any rawPrecision = this->safeString(entry, std::string("precision"));
    std::any precision = this->parseNumber(this->parsePrecision(rawPrecision));
    std::any isFiat = isEqual(chainsLength, 0);
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("name"), this->safeString(entry, std::string("fullName"))},
        {std::string("code"), code},
        {std::string("type"),
         (isTrue(isFiat) ? std::any(std::string("fiat"))
                         : std::any(std::string("crypto")))},
        {std::string("precision"), precision},
        {std::string("info"), entry},
        {std::string("networks"), networks},
        {std::string("deposit"), std::any{}},
        {std::string("withdraw"), std::any{}},
        {std::string("active"), std::any{}},
        {std::string("fee"), std::any{}},
        {std::string("limits"), std::any{}},
    });
  }

  /**
   * @method
   * @name kucoin#fetchAccounts
   * @description fetch all the accounts associated with a profile
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/account-funding/get-account-list-spot
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} a dictionary of [account structures]{@link
   * https://docs.ccxt.com/?id=account-structure} indexed by the account type
   */
  std::shared_future<std::any>
  fetchAccounts(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchAccounts"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 std::any data = ccxt::list{};
                 if (isTrue(uta)) {
                   response =
                       awaitValue(this->utaPrivateGetAccountModeAccountOverview(
                           this->extend(params, ccxt::dict{
                                                    {std::string("accountMode"),
                                                     std::string("unified")},
                                                })));
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": {
                   //             "accountType": "UNIFIED",
                   //             "riskRatio": "0.0000000000",
                   //             "equity": "30.0000000000",
                   //             "liability": "0.0000000000",
                   //             "availableMargin": "30.0000000000",
                   //             "adjustedEquity": "30.0000000000",
                   //             "im": "0.0000000000",
                   //             "mm": "0.0000000000"
                   //         }
                   //     }
                   //
                   std::any dataDict = this->safeDict(
                       response, std::string("data"), ccxt::dict{});
                   data = ccxt::list{dataDict};
                 } else {
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": [
                   //             {
                   //                 "balance": "0.00009788",
                   //                 "available": "0.00009788",
                   //                 "holds": "0",
                   //                 "currency": "BTC",
                   //                 "id": "5c6a4fd399a1d81c4f9cc4d0",
                   //                 "type": "trade"
                   //             },
                   //             {
                   //                 "balance": "0.00000001",
                   //                 "available": "0.00000001",
                   //                 "holds": "0",
                   //                 "currency": "ETH",
                   //                 "id": "5c6a49ec99a1d819392e8e9f",
                   //                 "type": "trade"
                   //             }
                   //         ]
                   //     }
                   //
                   response = awaitValue(this->privateGetAccounts(params));
                   data = this->safeList(response, std::string("data"),
                                         ccxt::list{});
                 }
                 std::any result = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(data));
                      postFixIncrement(i)) {
                   std::any account = ::getValue(data, i);
                   std::any accountId =
                       this->safeString(account, std::string("id"));
                   std::any currencyId =
                       this->safeString(account, std::string("currency"));
                   std::any code = this->safeCurrencyCode(currencyId);
                   std::any type = this->safeStringLower2(
                       account, std::string("type"),
                       std::string("accountType")); // main or trade or unified
                   arrayPush(result, ccxt::dict{
                                         {std::string("id"), accountId},
                                         {std::string("type"), type},
                                         {std::string("currency"), code},
                                         {std::string("code"), code},
                                         {std::string("info"), account},
                                     });
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchTransactionFee
   * @description *DEPRECATED* please use fetchDepositWithdrawFee instead
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/withdrawals/get-withdrawal-quotas
   * @param {string} code unified currency code
   * @param {object} params extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<std::any>
  fetchTransactionFee(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any networkCode = std::any{};
                 std::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 if (isTrue(!isEqual(networkCode, std::any{}))) {
                   std::any _netIdTmp = this->networkCodeToId(
                       networkCode, ::getValue(currency, std::string("code")));
                   if (isTrue(!isEqual(_netIdTmp, std::any{}))) {
                     ::setValue(request, std::string("chain"),
                                toLowerCase(_netIdTmp));
                   }
                 }
                 std::any response =
                     awaitValue(this->privateGetWithdrawalsQuotas(
                         this->extend(request, params)));
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any withdrawFees = ccxt::dict{};
                 ::setValue(
                     withdrawFees, code,
                     this->safeNumber(data, std::string("withdrawMinFee")));
                 return ccxt::dict{
                     {std::string("info"), response},
                     {std::string("withdraw"), withdrawFees},
                     {std::string("deposit"), ccxt::dict{}},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchDepositWithdrawFee
   * @description fetch the fee for deposits and withdrawals
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/withdrawals/get-withdrawal-quotas
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network] The chain of currency. This only apply for
   * multi-chain currency, and there is no need for single chain currency; you
   * can query the chain through the response of the GET
   * /api/v2/currencies/{currency} interface
   * @returns {object} a [fee structure]{@link
   * https://docs.ccxt.com/?id=fee-structure}
   */
  std::shared_future<std::any>
  fetchDepositWithdrawFee(std::any code,
                          std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any networkCode = std::any{};
                 std::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 if (isTrue(!isEqual(networkCode, std::any{}))) {
                   std::any _netIdTmp = this->networkCodeToId(
                       networkCode, ::getValue(currency, std::string("code")));
                   if (isTrue(!isEqual(_netIdTmp, std::any{}))) {
                     ::setValue(request, std::string("chain"),
                                toLowerCase(_netIdTmp));
                   }
                 }
                 std::any response =
                     awaitValue(this->privateGetWithdrawalsQuotas(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "code": "200000",
                 //        "data": {
                 //            "currency": "USDT",
                 //            "limitBTCAmount": "1.00000000",
                 //            "usedBTCAmount": "0.00000000",
                 //            "remainAmount": "16548.072149",
                 //            "availableAmount": "0",
                 //            "withdrawMinFee": "25",
                 //            "innerWithdrawMinFee": "0",
                 //            "withdrawMinSize": "50",
                 //            "isWithdrawEnabled": true,
                 //            "precision": 6,
                 //            "chain": "ERC20"
                 //        }
                 //    }
                 //
                 std::any data = this->safeDict(response, std::string("data"));
                 return this->parseDepositWithdrawFee(data, currency);
               })
        .share();
  }

  std::any parseDepositWithdrawFee(std::any fee,
                                   std::any currency = std::any{}) override {
    //
    //    {
    //        "currency": "USDT",
    //        "limitBTCAmount": "1.00000000",
    //        "usedBTCAmount": "0.00000000",
    //        "remainAmount": "16548.072149",
    //        "availableAmount": "0",
    //        "withdrawMinFee": "25",
    //        "innerWithdrawMinFee": "0",
    //        "withdrawMinSize": "50",
    //        "isWithdrawEnabled": true,
    //        "precision": 6,
    //        "chain": "ERC20"
    //    }
    //
    if (isTrue(inOp(fee, std::string("chains")))) {
      // if data obtained through `currencies` endpoint
      std::any resultNew = ccxt::dict{
          {std::string("info"), fee},
          {std::string("withdraw"),
           ccxt::dict{
               {std::string("fee"), std::any{}},
               {std::string("percentage"), false},
           }},
          {std::string("deposit"),
           ccxt::dict{
               {std::string("fee"), std::any{}},
               {std::string("percentage"), std::any{}},
           }},
          {std::string("networks"), ccxt::dict{}},
      };
      std::any chains =
          this->safeList(fee, std::string("chains"), ccxt::list{});
      for (std::any i = 0; isLessThan(i, getArrayLength(chains));
           postFixIncrement(i)) {
        std::any chain = ::getValue(chains, i);
        std::any chainId = this->safeString(chain, std::string("chainId"));
        std::any networkCodeNew = this->networkIdToCode(
            chainId, this->safeString(currency, std::string("code")));
        if (isTrue(!isEqual(networkCodeNew, std::any{}))) {
          ::setValue(::getValue(resultNew, std::string("networks")),
                     networkCodeNew,
                     ccxt::dict{
                         {std::string("withdraw"),
                          ccxt::dict{
                              {std::string("fee"),
                               this->safeNumber2(
                                   chain, std::string("withdrawalMinFee"),
                                   std::string("withdrawMinFee"))},
                              {std::string("percentage"), false},
                          }},
                         {std::string("deposit"),
                          ccxt::dict{
                              {std::string("fee"), std::any{}},
                              {std::string("percentage"), std::any{}},
                          }},
                     });
        }
      }
      return resultNew;
    }
    std::any minWithdrawFee =
        this->safeNumber(fee, std::string("withdrawMinFee"));
    std::any result = ccxt::dict{
        {std::string("info"), fee},
        {std::string("withdraw"),
         ccxt::dict{
             {std::string("fee"), minWithdrawFee},
             {std::string("percentage"), false},
         }},
        {std::string("deposit"),
         ccxt::dict{
             {std::string("fee"), std::any{}},
             {std::string("percentage"), std::any{}},
         }},
        {std::string("networks"), ccxt::dict{}},
    };
    std::any networkId = this->safeString(fee, std::string("chain"));
    std::any currencyId = this->safeString(fee, std::string("currency"));
    currency = this->safeCurrency(currencyId, currency);
    std::any networkCode = this->networkIdToCode(
        networkId, ::getValue(currency, std::string("code")));
    if (isTrue(!isEqual(networkCode, std::any{}))) {
      ::setValue(::getValue(result, std::string("networks")), networkCode,
                 ccxt::dict{
                     {std::string("withdraw"), minWithdrawFee},
                     {std::string("deposit"),
                      ccxt::dict{
                          {std::string("fee"), std::any{}},
                          {std::string("percentage"), std::any{}},
                      }},
                 });
    }
    return result;
  }

  virtual std::any isFuturesMethod(std::any methodName, std::any params) {
    //
    // Helper
    // @methodName (string): The name of the method
    // @params (dict): The parameters passed into {methodName}
    // @return: true if the method used is meant for futures trading, false
    // otherwise
    //
    std::any defaultType =
        this->safeString2(this->options, methodName, std::string("defaultType"),
                          std::string("trade"));
    std::any requestedType =
        this->safeString(params, std::string("type"), defaultType);
    std::any accountsByType = this->safeDict(
        this->options, std::string("accountsByType"), ccxt::dict{});
    std::any type = this->safeString(accountsByType, requestedType);
    if (isTrue(isEqual(type, std::any{}))) {
      std::any keys = getObjectKeys(accountsByType);
      throw ExchangeError(toString(add(
          add(this->id, std::string(" isFuturesMethod() type must be one of ")),
          join(keys, std::string(", ")))));
    }
    params = this->omit(params, std::string("type"));
    return isTrue(isTrue((isEqual(type, std::string("contract")))) ||
                  isTrue((isEqual(type, std::string("future"))))) ||
           isTrue((isEqual(
               type,
               std::string("futures")))); // * (type === 'futures') deprecated,
                                          // use (type === 'future')
  }

  virtual std::any parseSpotOrUtaTicker(std::any ticker,
                                        std::any market = std::any{}) {
    //
    //     {
    //         "symbol": "BTC-USDT",   // symbol
    //         "symbolName":"BTC-USDT", // Name of trading pairs, it would
    //         change after renaming "buy": "11328.9",   // bestAsk "sell":
    //         "11329",    // bestBid "changeRate": "-0.0055",    // 24h change
    //         rate "changePrice": "-63.6", // 24h change price "high": "11610",
    //         // 24h highest price "low": "11200", // 24h lowest price "vol":
    //         "2282.70993217", // 24h volume，the aggregated trading volume in
    //         BTC "volValue": "25984946.157790431",   // 24h total, the trading
    //         volume in quote currency of last 24 hours "last": "11328.9",  //
    //         last price "averagePrice": "11360.66065903",   // 24h average
    //         transaction price yesterday "takerFeeRate": "0.001",    // Basic
    //         Taker Fee "makerFeeRate": "0.001",    // Basic Maker Fee
    //         "takerCoefficient": "1",    // Taker Fee Coefficient
    //         "makerCoefficient": "1" // Maker Fee Coefficient
    //     }
    //
    //     {
    //         "trading": true,
    //         "symbol": "KCS-BTC",
    //         "buy": 0.00011,
    //         "sell": 0.00012,
    //         "sort": 100,
    //         "volValue": 3.13851792584,   //total
    //         "baseCurrency": "KCS",
    //         "market": "BTC",
    //         "quoteCurrency": "BTC",
    //         "symbolCode": "KCS-BTC",
    //         "datetime": 1548388122031,
    //         "high": 0.00013,
    //         "vol": 27514.34842,
    //         "low": 0.0001,
    //         "changePrice": -1.0e-5,
    //         "changeRate": -0.0769,
    //         "lastTradedPrice": 0.00012,
    //         "board": 0,
    //         "mark": 0
    //     }
    //
    // market/ticker ws subscription
    //
    //     {
    //         "bestAsk": "62258.9",
    //         "bestAskSize": "0.38579986",
    //         "bestBid": "62258.8",
    //         "bestBidSize": "0.0078381",
    //         "price": "62260.7",
    //         "sequence": "1621383297064",
    //         "size": "0.00002841",
    //         "time": 1634641777363
    //     }
    //
    // uta spot
    //     {
    //         "symbol": "ETH-USDT",
    //         "name": "ETH-USDT",
    //         "bestBidSize": "2.8893176",
    //         "bestBidPrice": "1566.24",
    //         "bestAskSize": "2.4373857",
    //         "bestAskPrice": "1566.25",
    //         "lastPrice": "1565.87",
    //         "size": "0.0384399",
    //         "open": "1572.96",
    //         "high": "1637.4",
    //         "low": "1550.41",
    //         "baseVolume": "101560.01156957747448132256",
    //         "quoteVolume": "161467045.65271628672329459176",
    //         "priceChange": "-7.09",
    //         "priceChangePercent": "-0.0045"
    //     }
    //
    // uta swap
    //
    //     {
    //         "symbol": "ETHUSDTM",
    //         "bestBidSize": "4",
    //         "bestBidPrice": "1573.45",
    //         "bestAskSize": "43",
    //         "bestAskPrice": "1573.46",
    //         "lastPrice": "1573.63",
    //         "size": "1",
    //         "open": "1570.09",
    //         "high": "1637.08",
    //         "low": "1549.63",
    //         "baseVolume": "282920.90",
    //         "quoteVolume": "449940743.674",
    //         "priceChange": "3.54",
    //         "priceChangePercent": "0.2255",
    //         "indexPrice": "1572.67",
    //         "markPrice": "1572.68"
    //     }
    //
    std::any percentage = this->safeString(ticker, std::string("changeRate"));
    if (isTrue(!isEqual(percentage, std::any{}))) {
      percentage = ccxt::Precise::stringMul(percentage, std::string("100"));
    } else {
      percentage = this->safeString(ticker, std::string("priceChangePercent"));
    }
    std::any last = this->safeStringN(
        ticker, ccxt::list{std::string("last"), std::string("lastTradedPrice"),
                           std::string("lastPrice")});
    last = this->safeString(ticker, std::string("price"), last);
    std::any marketId = this->safeString(ticker, std::string("symbol"));
    market = this->safeMarket(marketId, market, std::string("-"));
    std::any symbol = ::getValue(market, std::string("symbol"));
    std::any baseVolume = this->safeString2(ticker, std::string("vol"),
                                            std::string("baseVolume"));
    std::any quoteVolume = this->safeString2(ticker, std::string("volValue"),
                                             std::string("quoteVolume"));
    std::any timestamp = this->safeIntegerN(
        ticker, ccxt::list{std::string("time"), std::string("datetime"),
                           std::string("timePoint")});
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("high"),
             this->safeString(ticker, std::string("high"))},
            {std::string("low"), this->safeString(ticker, std::string("low"))},
            {std::string("bid"),
             this->safeStringN(
                 ticker, ccxt::list{std::string("buy"), std::string("bestBid"),
                                    std::string("bestBidPrice")})},
            {std::string("bidVolume"),
             this->safeString(ticker, std::string("bestBidSize"))},
            {std::string("ask"),
             this->safeStringN(
                 ticker, ccxt::list{std::string("sell"), std::string("bestAsk"),
                                    std::string("bestAskPrice")})},
            {std::string("askVolume"),
             this->safeString(ticker, std::string("bestAskSize"))},
            {std::string("vwap"), std::any{}},
            {std::string("open"),
             this->safeString(ticker, std::string("open"))},
            {std::string("close"), last},
            {std::string("last"), last},
            {std::string("previousClose"), std::any{}},
            {std::string("change"),
             this->safeString2(ticker, std::string("changePrice"),
                               std::string("priceChange"))},
            {std::string("percentage"), percentage},
            {std::string("average"),
             this->safeString(ticker, std::string("averagePrice"))},
            {std::string("baseVolume"), baseVolume},
            {std::string("quoteVolume"), quoteVolume},
            {std::string("markPrice"),
             this->safeString2(ticker, std::string("markPrice"),
                               std::string("value"))},
            {std::string("indexPrice"),
             this->safeString(ticker, std::string("indexPrice"))},
            {std::string("info"), ticker},
        },
        market);
  }

  std::any parseTicker(std::any ticker, std::any market = std::any{}) override {
    // wrapper for parseTickers
    // parseTickers used only in methods for contract markets
    return this->parseContractTicker(ticker, market);
  }

