  /**
   * @method
   * @ignore
   * @name kucoin#fetchContractOHLCV
   * @description helper method for fetchOHLCV
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/market-data/get-klines
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<std::any>
  fetchContractOHLCV(std::any symbol, std::any timeframe = std::string("1m"),
                     std::any since = std::any{}, std::any limit = std::any{},
                     std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any maxLimit = 200;
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchContractOHLCV"), symbol, since, limit,
                       timeframe, params, maxLimit));
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any timeframeOptions = this->safeDict(
                     this->options, std::string("timeframes"), ccxt::dict{});
                 std::any swapTimeframes = this->safeDict(
                     timeframeOptions, std::string("swap"), ccxt::dict{});
                 std::any parsedTimeframe =
                     this->safeInteger(swapTimeframes, timeframe);
                 if (isTrue(!isEqual(parsedTimeframe, std::any{}))) {
                   ::setValue(request, std::string("granularity"),
                              parsedTimeframe);
                 } else {
                   ::setValue(request, std::string("granularity"), timeframe);
                 }
                 std::any duration =
                     multiply(this->parseTimeframe(timeframe), 1000);
                 std::any endAt = this->milliseconds(); // required param
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("from"), since);
                   if (isTrue(isEqual(limit, std::any{}))) {
                     // For each query, the system would return at most 200
                     // pieces of data. To obtain more data, please page the
                     // data by time.
                     limit = this->safeInteger(this->options,
                                               std::string("fetchOHLCVLimit"),
                                               maxLimit);
                   }
                   endAt = this->sum(since, multiply(limit, duration));
                 } else if (isTrue(!isEqual(limit, std::any{}))) {
                   since = subtract(endAt, multiply(limit, duration));
                   ::setValue(request, std::string("from"), since);
                 }
                 ::setValue(request, std::string("to"), endAt);
                 std::any response =
                     awaitValue(this->futuresPublicGetKlineQuery(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "code": "200000",
                 //        "data": [
                 //            [1636459200000, 4779.3, 4792.1, 4768.7, 4770.3,
                 //            78051], [1636460100000, 4770.25, 4778.55,
                 //            4757.55, 4777.25, 80164], [1636461000000,
                 //            4777.25, 4791.45, 4774.5, 4791.3, 51555]
                 //        ]
                 //    }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseOHLCVs(data, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#createDepositAddress
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/deposit/add-deposit-address-v3
   * @description create a currency deposit address
   * @param {string} code unified currency code of the currency for the deposit
   * address
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network] the blockchain network name
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  createDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any networkCode = std::any{};
                 std::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 if (isTrue(!isEqual(networkCode, std::any{}))) {
                   ::setValue(
                       request, std::string("chain"),
                       this->networkCodeToId(
                           networkCode,
                           ::getValue(
                               currency,
                               std::string(
                                   "code")))); // docs mention "chain-name", but
                                               // seems "chain-id" is used, like
                                               // in "fetchDepositAddress"
                 }
                 std::any response =
                     awaitValue(this->privatePostDepositAddressCreate(
                         this->extend(request, params)));
                 // {"code":"260000","msg":"Deposit address already exists."}
                 //
                 //   {
                 //     "code": "200000",
                 //     "data": {
                 //       "address":
                 //       "0x2336d1834faab10b2dac44e468f2627138417431", "memo":
                 //       null, "chainId": "bsc", "to": "MAIN",
                 //       "expirationDate": 0,
                 //       "currency": "BNB",
                 //       "chainName": "BEP20"
                 //     }
                 //   }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseDepositAddress(data, currency);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/deposit/get-deposit-address-v3/en
   * @see https://www.kucoin.com/docs-new/rest/ua/get-deposit-address
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.network] the blockchain network name
   * @param {string} [params.accountType] 'main', 'contract' or 'uta' (default
   * is 'main')
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta) endpoint, defaults to false
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  fetchDepositAddress(std::any code, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any accountType = std::string("main");
                 std::any accountTypeparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchDepositAddress"),
                         std::string("accountType"), accountType);
                 accountType = ::getValue(accountTypeparamsVariable, 0);
                 params = ::getValue(accountTypeparamsVariable, 1);
                 std::any accountsByType = this->safeDict(
                     this->options, std::string("accountsByType"),
                     ccxt::dict{});
                 accountType =
                     this->safeString(accountsByType, accountType, accountType);
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchDepositAddress"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(isEqual(accountType, std::string("contract")))) {
                   return awaitValue(
                       this->fetchContractDepositAddress(code, params));
                 } else if (isTrue(
                                isTrue(isTrue(uta) ||
                                       isTrue((isEqual(accountType,
                                                       std::string("uta"))))) ||
                                isTrue((isEqual(accountType,
                                                std::string("unified")))))) {
                   return awaitValue(Exchange::fetchDepositAddress(
                       code,
                       this->extend(params, ccxt::dict{
                                                {std::string("uta"), true},
                                            })));
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any networkCode = std::any{};
                 std::any networkCodeparamsVariable =
                     this->handleNetworkCodeAndParams(params);
                 networkCode = ::getValue(networkCodeparamsVariable, 0);
                 params = ::getValue(networkCodeparamsVariable, 1);
                 if (isTrue(!isEqual(networkCode, std::any{}))) {
                   std::any _netIdTmp = this->networkCodeToId(
                       networkCode, ::getValue(currency, std::string("code")));
                   if (isTrue(!isEqual(_netIdTmp, std::any{}))) {
                     ::setValue(request, std::string("chain"),
                                toLowerCase(_netIdTmp));
                   }
                 }
                 std::any version = ::getValue(
                     ::getValue(::getValue(::getValue(this->options,
                                                      std::string("versions")),
                                           std::string("private")),
                                std::string("GET")),
                     std::string("deposit-addresses"));
                 ::setValue(
                     ::getValue(::getValue(::getValue(this->options,
                                                      std::string("versions")),
                                           std::string("private")),
                                std::string("GET")),
                     std::string("deposit-addresses"), std::string("v1"));
                 std::any response =
                     awaitValue(this->privateGetDepositAddresses(
                         this->extend(request, params)));
                 // BCH
                 // {"code":"200000","data":{"address":"bitcoincash:qza3m4nj9rx7l9r0cdadfqxts6f92shvhvr5ls4q7z","memo":""}}
                 // BTC
                 // {"code":"200000","data":{"address":"36SjucKqQpQSvsak9A7h6qzFjrVXpRNZhE","memo":""}}
                 ::setValue(
                     ::getValue(::getValue(::getValue(this->options,
                                                      std::string("versions")),
                                           std::string("private")),
                                std::string("GET")),
                     std::string("deposit-addresses"), version);
                 std::any data = this->safeValue(response, std::string("data"));
                 if (isTrue(isEqual(data, std::any{}))) {
                   throw ExchangeError(toString(
                       add(this->id,
                           std::string(
                               " fetchDepositAddress() returned an empty "
                               "response, you might try to run "
                               "createDepositAddress() first and try again"))));
                 }
                 return this->parseDepositAddress(data, currency);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchContractDepositAddress
   * @description fetch the deposit address for a currency associated with this
   * account
   * @see https://www.kucoin.com/docs/rest/funding/deposit/get-deposit-address
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [address structure]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  fetchContractDepositAddress(std::any code,
                              std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any currency = this->currency(code);
                        std::any currencyId =
                            ::getValue(currency, std::string("id"));
                        std::any request = ccxt::dict{
                            {std::string("currency"), currencyId},
                        };
                        std::any response =
                            awaitValue(this->futuresPrivateGetDepositAddress(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "code": "200000",
                        //        "data": {
                        //            "address":
                        //            "0x78d3ad1c0aa1bf068e19c94a2d7b16c9c0fcd8b1",//Deposit
                        //            address "memo": null//Address tag. If the
                        //            returned value is null, it means that the
                        //            requested token has no memo. If you are to
                        //            transfer funds from another platform to
                        //            KuCoin Futures and if the token to be
                        //            //transferred has memo(tag), you need to
                        //            fill in the memo to ensure the transferred
                        //            funds will be sent //to the address you
                        //            specified.
                        //        }
                        //    }
                        //
                        std::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        std::any address =
                            this->safeString(data, std::string("address"));
                        if (isTrue(!isEqual(currencyId, std::string("NIM")))) {
                          // contains spaces
                          this->checkAddress(address);
                        }
                        return ccxt::dict{
                            {std::string("info"), response},
                            {std::string("currency"), currencyId},
                            {std::string("network"),
                             this->safeString(data, std::string("chain"))},
                            {std::string("address"), address},
                            {std::string("tag"),
                             this->safeString(data, std::string("memo"))},
                        };
                      })
        .share();
  }

  std::any parseDepositAddress(std::any depositAddress,
                               std::any currency = std::any{}) override {
    std::any address = this->safeString(depositAddress, std::string("address"));
    // BCH/BSV is returned with a "bitcoincash:" prefix, which we cut off here
    // and only keep the address
    if (isTrue(!isEqual(address, std::any{}))) {
      address = replace(address, std::string("bitcoincash:"), std::string(""));
    }
    std::any code = std::any{};
    if (isTrue(!isEqual(currency, std::any{}))) {
      code = this->safeCurrencyCode(::getValue(currency, std::string("id")));
      if (isTrue(!isEqual(code, std::string("NIM")))) {
        // contains spaces
        this->checkAddress(address);
      }
    }
    std::any chainId = this->safeString(depositAddress, std::string("chainId"));
    return ccxt::dict{
        {std::string("info"), depositAddress},
        {std::string("currency"), code},
        {std::string("network"), this->networkIdToCode(chainId, code)},
        {std::string("address"), address},
        {std::string("tag"),
         this->safeString(depositAddress, std::string("memo"))},
    };
  }

  /**
   * @method
   * @name kucoin#fetchDepositAddressesByNetwork
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/deposit/get-deposit-address-v3/en
   * @see https://www.kucoin.com/docs-new/rest/ua/get-deposit-address
   * @description fetch the deposit address for a currency associated with this
   * account
   * @param {string} code unified currency code
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta) endpoint, defaults to false
   * @returns {object} an array of [address structures]{@link
   * https://docs.ccxt.com/?id=address-structure}
   */
  std::shared_future<std::any>
  fetchDepositAddressesByNetwork(std::any code,
                                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any currency = this->currency(code);
                 std::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                 };
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchDepositAddressesByNetwork"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(uta)) {
                   std::any networkCode = std::any{};
                   std::any networkCodeparamsVariable =
                       this->handleNetworkCodeAndParams(params);
                   networkCode = ::getValue(networkCodeparamsVariable, 0);
                   params = ::getValue(networkCodeparamsVariable, 1);
                   if (isTrue(!isEqual(networkCode, std::any{}))) {
                     std::any _netIdTmp =
                         this->networkCodeToId(networkCode, code);
                     if (isTrue(!isEqual(_netIdTmp, std::any{}))) {
                       ::setValue(request, std::string("chain"),
                                  toLowerCase(_netIdTmp));
                     }
                   }
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": [
                   //             {
                   //                 "address":
                   //                 "0xf30a9b6968183668dbce515bd6449438ab3252b3",
                   //                 "memo": "",
                   //                 "remark": "",
                   //                 "chainId": "eth",
                   //                 "to": "FUNDING",
                   //                 "expirationDate": 0,
                   //                 "currency": "USDT",
                   //                 "contractAddress":
                   //                 "0xdac17f958d2ee523a2206206994597c13d831ec7",
                   //                 "chainName": "ERC20"
                   //             }
                   //         ]
                   //     }
                   //
                   response = awaitValue(this->utaPrivateGetAssetDepositAddress(
                       this->extend(request, params)));
                 } else {
                   std::any version = ::getValue(
                       ::getValue(
                           ::getValue(::getValue(this->options,
                                                 std::string("versions")),
                                      std::string("private")),
                           std::string("GET")),
                       std::string("deposit-addresses"));
                   ::setValue(
                       ::getValue(
                           ::getValue(::getValue(this->options,
                                                 std::string("versions")),
                                      std::string("private")),
                           std::string("GET")),
                       std::string("deposit-addresses"), std::string("v2"));
                   response = awaitValue(this->privateGetDepositAddresses(
                       this->extend(request, params)));
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": [
                   //             {
                   //                 "address":
                   //                 "fr1qvus7d4d5fgxj5e7zvqe6yhxd7txm95h2and69r",
                   //                 "memo": "",
                   //                 "chain": "BTC-Segwit",
                   //                 "contractAddress": ""
                   //             },
                   //             {"address":"37icNMEWbiF8ZkwUMxmfzMxi2A1MQ44bMn","memo":"","chain":"BTC","contractAddress":""},
                   //             {"address":"Deposit temporarily
                   //             blocked","memo":"","chain":"TRC20","contractAddress":""}
                   //         ]
                   //     }
                   //
                   ::setValue(::getValue(::getValue(::getValue(this->options,
                                                               std::string(
                                                                   "versions")),
                                                    std::string("private")),
                                         std::string("GET")),
                              std::string("deposit-addresses"), version);
                 }
                 std::any chains = this->safeList(response, std::string("data"),
                                                  ccxt::list{});
                 std::any parsed = this->parseDepositAddresses(
                     chains,
                     ccxt::list{::getValue(currency, std::string("code"))},
                     false,
                     ccxt::dict{
                         {std::string("currency"),
                          ::getValue(currency, std::string("code"))},
                     });
                 return this->indexBy(parsed, std::string("network"));
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/market-data/get-part-orderbook
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/market-data/get-full-orderbook
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/market-data/get-part-orderbook
   * @see https://www.kucoin.com/docs-new/rest/ua/get-orderbook
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<std::any>
  fetchOrderBook(std::any symbol, std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any level =
                     this->safeInteger(params, std::string("level"), 2);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any isAuthenticated =
                     this->checkRequiredCredentials(false);
                 std::any uta = false;
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrderBook"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 std::any type = std::any{};
                 std::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchOrderBook"), market, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 if (isTrue(uta)) {
                   std::any limitString = std::string("20");
                   if (isTrue(isTrue((isEqual(limit, std::any{}))) ||
                              isTrue((isGreaterThanOrEqual(limit, 100))))) {
                     limitString = std::string("FULL");
                   } else if (isTrue(isGreaterThan(limit, 20))) {
                     limitString = std::string("100");
                   }
                   ::setValue(request, std::string("limit"), limitString);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   if (isTrue(isTrue((isEqual(type, std::string("spot")))) ||
                              isTrue((isEqual(type, std::string("margin")))))) {
                     ::setValue(request, std::string("tradeType"),
                                std::string("SPOT"));
                   } else {
                     ::setValue(request, std::string("tradeType"),
                                std::string("FUTURES"));
                   }
                   response = awaitValue(this->utaPrivateGetMarketOrderbook(
                       this->extend(request, params)));
                 } else if (isTrue(
                                isTrue((!isEqual(type, std::string("spot")))) &&
                                isTrue(
                                    (!isEqual(type, std::string("margin")))))) {
                   if (isTrue(isTrue(!isEqual(level, 2)) &&
                              isTrue(!isEqual(level, std::any{})))) {
                     throw BadRequest(toString(add(
                         this->id,
                         std::string(
                             " fetchOrderBook() can only return level 2"))));
                   }
                   if (isTrue(isEqual(limit, std::any{}))) {
                     // full L2 snapshot - required for correct ws diff-sync:
                     // the futures delta stream covers the whole book while
                     // depth20/depth100 truncate the snapshot, see
                     // https://github.com/ccxt/ccxt/issues/22063
                     response = awaitValue(this->futuresPublicGetLevel2Snapshot(
                         this->extend(request, params)));
                   } else if (isTrue(isEqual(limit, 20))) {
                     //
                     //     {
                     //         "code": "200000",
                     //         "data": {
                     //           "symbol": "XBTUSDM",      //Symbol
                     //           "sequence": 100,          //Ticker sequence
                     //           number "asks": [
                     //                 ["5000.0", 1000],   //Price, quantity
                     //                 ["6000.0", 1983]    //Price, quantity
                     //           ],
                     //           "bids": [
                     //                 ["3200.0", 800],    //Price, quantity
                     //                 ["3100.0", 100]     //Price, quantity
                     //           ],
                     //           "ts": 1604643655040584408  // timestamp
                     //         }
                     //     }
                     //
                     response = awaitValue(this->futuresPublicGetLevel2Depth20(
                         this->extend(request, params)));
                   } else if (isTrue(isEqual(limit, 100))) {
                     response = awaitValue(this->futuresPublicGetLevel2Depth100(
                         this->extend(request, params)));
                   } else {
                     throw BadRequest(toString(add(
                         this->id, std::string(" fetchOrderBook() limit "
                                               "argument must be 20 or 100"))));
                   }
                 } else if (isTrue(!isTrue(isAuthenticated) ||
                                   isTrue(!isEqual(limit, std::any{})))) {
                   if (isTrue(isEqual(level, 2))) {
                     ::setValue(request, std::string("level"), level);
                     if (isTrue(!isEqual(limit, std::any{}))) {
                       if (isTrue(isTrue((isEqual(limit, 20))) ||
                                  isTrue((isEqual(limit, 100))))) {
                         ::setValue(request, std::string("limit"), limit);
                       } else {
                         throw ExchangeError(toString(
                             add(this->id,
                                 std::string(" fetchOrderBook() limit argument "
                                             "must be 20 or 100"))));
                       }
                     }
                     ::setValue(request, std::string("limit"),
                                (isTrue((!isEqual(limit, std::any{})))
                                     ? std::any(limit)
                                     : std::any(100)));
                   }
                   response =
                       awaitValue(this->publicGetMarketOrderbookLevelLevelLimit(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privateGetMarketOrderbookLevel2(
                       this->extend(request, params)));
                 }
                 //
                 // public (v1) market/orderbook/level2_20 and
                 // market/orderbook/level2_100
                 //
                 //     {
                 //         "sequence": "3262786978",
                 //         "time": 1550653727731,
                 //         "bids": [
                 //             ["6500.12", "0.45054140"],
                 //             ["6500.11", "0.45054140"],
                 //         ],
                 //         "asks": [
                 //             ["6500.16", "0.57753524"],
                 //             ["6500.15", "0.57753524"],
                 //         ]
                 //     }
                 //
                 // private (v3) market/orderbook/level2
                 //
                 //     {
                 //         "sequence": "3262786978",
                 //         "time": 1550653727731,
                 //         "bids": [
                 //             ["6500.12", "0.45054140"],
                 //             ["6500.11", "0.45054140"],
                 //         ],
                 //         "asks": [
                 //             ["6500.16", "0.57753524"],
                 //             ["6500.15", "0.57753524"],
                 //         ]
                 //     }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any timestamp =
                     this->safeInteger(data, std::string("time"));
                 if (isTrue(isEqual(timestamp, std::any{}))) {
                   std::any nanoseconds =
                       this->safeInteger(data, std::string("ts"));
                   if (isTrue(!isEqual(nanoseconds, std::any{}))) {
                     timestamp = this->parseToInt(divide(nanoseconds, 1000000));
                   }
                 }
                 std::any orderbook = this->parseOrderBook(
                     data, ::getValue(market, std::string("symbol")), timestamp,
                     std::string("bids"), std::string("asks"),
                     subtract(level, 2), subtract(level, 1));
                 ::setValue(orderbook, std::string("nonce"),
                            this->safeInteger(data, std::string("sequence")));
                 return orderbook;
               })
        .share();
  }

  virtual std::any handleTriggerPrices(std::any params) {
    std::any triggerPrice = this->safeValue2(
        params, std::string("triggerPrice"), std::string("stopPrice"));
    std::any stopLossPrice =
        this->safeValue(params, std::string("stopLossPrice"));
    std::any takeProfitPrice =
        this->safeValue(params, std::string("takeProfitPrice"));
    std::any isStopLoss = !isEqual(stopLossPrice, std::any{});
    std::any isTakeProfit = !isEqual(takeProfitPrice, std::any{});
    if (isTrue(
            isTrue(isTrue((isTrue(isStopLoss) && isTrue(isTakeProfit))) ||
                   isTrue((isTrue((!isEqual(triggerPrice, std::any{}))) &&
                           isTrue((!isEqual(stopLossPrice, std::any{})))))) ||
            isTrue((isTrue((!isEqual(triggerPrice, std::any{}))) &&
                    isTrue(isTakeProfit))))) {
      throw ExchangeError(toString(
          add(this->id,
              std::string(" createOrder() - you should use either triggerPrice "
                          "or stopLossPrice or takeProfitPrice"))));
    }
    return ccxt::list{triggerPrice, stopLossPrice, takeProfitPrice};
  }

  /**
   * @method
   * @name kucoin#createOrder
   * @description Create an order on the exchange
   * @see https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order-test
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-stop-order
   * @see https://www.kucoin.com/docs-new/rest/margin-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/add-order-test
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/add-stop-order
   * @see https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order-test
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-take-profit-and-stop-loss-order
   * @see https://www.kucoin.com/docs-new/rest/ua/place-order
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} type 'limit' or 'market'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount the amount of currency to trade
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta) endpoint, defaults to false Check createSpotOrder(),
   * createContractOrder() and createUtaOrder () for more details on the extra
   * parameters that can be used in params
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("createOrder"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(uta)) {
                   return awaitValue(this->createUtaOrder(
                       symbol, type, side, amount, price, params));
                 } else if (isTrue(
                                isEqual(::getValue(market, std::string("spot")),
                                        true))) {
                   return awaitValue(this->createSpotOrder(
                       symbol, type, side, amount, price, params));
                 } else if (isTrue(isEqual(
                                ::getValue(market, std::string("contract")),
                                true))) {
                   return awaitValue(this->createContractOrder(
                       symbol, type, side, amount, price, params));
                 } else {
                   throw NotSupported(toString(
                       add(add(this->id,
                               std::string(
                                   " createOrder() does not support market ")),
                           ::getValue(market, std::string("type")))));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#createSpotOrder
   * @description helper method for creating spot orders
   * @see https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order-test
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-stop-order
   * @see https://www.kucoin.com/docs-new/rest/margin-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/add-order-test
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/add-stop-order
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} type 'limit' or 'market'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount the amount of currency to trade
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] The price at which a trigger order is
   * triggered at
   * @param {string} [params.marginMode] 'cross', // cross (cross mode) and
   * isolated (isolated mode), set to cross by default, the isolated mode will
   * be released soon, stay tuned
   * @param {string} [params.timeInForce] GTC, GTT, IOC, or FOK, default is GTC,
   * limit orders only
   * @param {bool} [params.postOnly] Post only flag, invalid when timeInForce is
   * IOC or FOK
   *
   * EXCHANGE SPECIFIC PARAMETERS
   * @param {string} [params.clientOid] client order id, defaults to uuid if not
   * passed
   * @param {string} [params.remark] remark for the order, length cannot exceed
   * 100 utf8 characters
   * @param {string} [params.tradeType] 'TRADE', // TRADE, MARGIN_TRADE // not
   * used with margin orders limit orders
   * ---------------------------------------------------
   * @param {float} [params.cancelAfter] long, // cancel after n seconds,
   * requires timeInForce to be GTT
   * @param {bool} [params.hidden] false, // Order will not be displayed in the
   * order book
   * @param {bool} [params.iceberg] false, // Only a portion of the order is
   * displayed in the order book
   * @param {string} [params.visibleSize] this.amountToPrecision (symbol,
   * visibleSize), // The maximum visible size of an iceberg order market orders
   * --------------------------------------------------
   * @param {string} [params.funds] // Amount of quote currency to use
   * stop orders ----------------------------------------------------
   * @param {string} [params.stop]  Either loss or entry, the default is loss.
   * Requires triggerPrice to be defined margin orders
   * --------------------------------------------------
   * @param {float} [params.leverage] Leverage size of the order
   * @param {string} [params.stp] '', // self trade prevention, CN, CO, CB or DC
   * @param {bool} [params.autoBorrow] false, // The system will first borrow
   * you funds at the optimal interest rate and then place an order for you
   * @param {bool} [params.hf] false, // true for hf order
   * @param {bool} [params.test] set to true to test an order, no order will be
   * created but the request will be validated
   * @param {bool} [params.sync] set to true to use the hf sync call
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  createSpotOrder(std::any symbol, std::any type, std::any side,
                  std::any amount, std::any price = std::any{},
                  std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any testOrder =
                     this->safeBool(params, std::string("test"), false);
                 params = this->omit(params, std::string("test"));
                 std::any hf = std::any{};
                 std::any hfparamsVariable = this->handleHfAndParams(params);
                 hf = ::getValue(hfparamsVariable, 0);
                 params = ::getValue(hfparamsVariable, 1);
                 std::any useSync = false;
                 std::any useSyncparamsVariable = this->handleOptionAndParams(
                     params, std::string("createOrder"), std::string("sync"),
                     false);
                 useSync = ::getValue(useSyncparamsVariable, 0);
                 params = ::getValue(useSyncparamsVariable, 1);
                 std::any triggerPricestopLossPricetakeProfitPriceVariable =
                     this->handleTriggerPrices(params);
                 std::any triggerPrice = ::getValue(
                     triggerPricestopLossPricetakeProfitPriceVariable, 0);
                 std::any stopLossPrice = ::getValue(
                     triggerPricestopLossPricetakeProfitPriceVariable, 1);
                 std::any takeProfitPrice = ::getValue(
                     triggerPricestopLossPricetakeProfitPriceVariable, 2);
                 std::any tradeType = this->safeString(
                     params,
                     std::string(
                         "tradeType")); // keep it for backward compatibility
                 std::any isTriggerOrder =
                     isTrue(isTrue((!isEqual(triggerPrice, std::any{}))) ||
                            isTrue((!isEqual(stopLossPrice, std::any{})))) ||
                     isTrue((!isEqual(takeProfitPrice, std::any{})));
                 std::any marginResult = this->handleMarginModeAndParams(
                     std::string("createOrder"), params);
                 std::any marginMode = this->safeString(marginResult, 0);
                 std::any isMarginOrder =
                     isTrue(isEqual(tradeType, std::string("MARGIN_TRADE"))) ||
                     isTrue(!isEqual(marginMode, std::any{}));
                 // don't omit anything before calling createOrderRequest
                 std::any orderRequest = this->createSpotOrderRequest(
                     symbol, type, side, amount, price, params);
                 std::any response = std::any{};
                 if (isTrue(isEqual(testOrder, true))) {
                   if (isTrue(isMarginOrder)) {
                     if (isTrue(isEqual(hf, true))) {
                       response = awaitValue(
                           this->privatePostHfMarginOrderTest(orderRequest));
                     } else {
                       response = awaitValue(
                           this->privatePostMarginOrderTest(orderRequest));
                     }
                   } else if (isTrue(isEqual(hf, true))) {
                     response = awaitValue(
                         this->privatePostHfOrdersTest(orderRequest));
                   } else {
                     response =
                         awaitValue(this->privatePostOrdersTest(orderRequest));
                   }
                 } else if (isTrue(isTriggerOrder)) {
                   if (isTrue(isMarginOrder)) {
                     response = awaitValue(
                         this->privatePostHfMarginStopOrder(orderRequest));
                   } else {
                     response =
                         awaitValue(this->privatePostStopOrder(orderRequest));
                   }
                 } else if (isTrue(isMarginOrder)) {
                   if (isTrue(isEqual(hf, true))) {
                     response = awaitValue(
                         this->privatePostHfMarginOrder(orderRequest));
                   } else {
                     response =
                         awaitValue(this->privatePostMarginOrder(orderRequest));
                   }
                 } else if (isTrue(useSync)) {
                   response =
                       awaitValue(this->privatePostHfOrdersSync(orderRequest));
                 } else if (isTrue(isEqual(hf, true))) {
                   response =
                       awaitValue(this->privatePostHfOrders(orderRequest));
                 } else {
                   response = awaitValue(this->privatePostOrders(orderRequest));
                 }
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": {
                 //             "orderId": "5bd6e9286d99522a52e458de"
                 //         }
                 //    }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseOrder(data, market);
               })
        .share();
  }

  virtual std::any createSpotOrderRequest(std::any symbol, std::any type,
                                          std::any side, std::any amount,
                                          std::any price = std::any{},
                                          std::any params = ccxt::dict{}) {
    if (isTrue(isEqual(type, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a type argument"))));
    }
    if (isTrue(isEqual(side, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a side argument"))));
    }
    std::any market = this->market(symbol);
    // required param, cannot be used twice
    std::any clientOrderId =
        this->safeString2(params, std::string("clientOid"),
                          std::string("clientOrderId"), this->uuid());
    params = this->omit(params, ccxt::list{std::string("clientOid"),
                                           std::string("clientOrderId")});
    std::any request = ccxt::dict{
        {std::string("clientOid"), clientOrderId},
        {std::string("side"), side},
        {std::string("symbol"), ::getValue(market, std::string("id"))},
        {std::string("type"), type},
    };
    std::any quoteAmount =
        this->safeNumber2(params, std::string("cost"), std::string("funds"));
    std::any amountString = std::any{};
    std::any costString = std::any{};
    std::any marginMode = std::any{};
    std::any marginModeparamsVariable =
        this->handleMarginModeAndParams(std::string("createOrder"), params);
    marginMode = ::getValue(marginModeparamsVariable, 0);
    params = ::getValue(marginModeparamsVariable, 1);
    if (isTrue(isEqual(type, std::string("market")))) {
      if (isTrue(!isEqual(quoteAmount, std::any{}))) {
        params = this->omit(
            params, ccxt::list{std::string("cost"), std::string("funds")});
        // kucoin uses base precision even for quote values
        costString = this->marketOrderAmountToPrecision(symbol, quoteAmount);
        ::setValue(request, std::string("funds"), costString);
      } else {
        amountString = this->amountToPrecision(symbol, amount);
        ::setValue(request, std::string("size"),
                   this->amountToPrecision(symbol, amount));
      }
    } else {
      amountString = this->amountToPrecision(symbol, amount);
      ::setValue(request, std::string("size"), amountString);
      ::setValue(request, std::string("price"),
                 this->priceToPrecision(symbol, price));
    }
    std::any tradeType = this->safeString(
        params, std::string("tradeType")); // keep it for backward compatibility
    std::any triggerPricestopLossPricetakeProfitPriceVariable =
        this->handleTriggerPrices(params);
    std::any triggerPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 0);
    std::any stopLossPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 1);
    std::any takeProfitPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 2);
    std::any isTriggerOrder =
        isTrue(isTrue((!isEqual(triggerPrice, std::any{}))) ||
               isTrue((!isEqual(stopLossPrice, std::any{})))) ||
        isTrue((!isEqual(takeProfitPrice, std::any{})));
    std::any isMarginOrder =
        isTrue(isEqual(tradeType, std::string("MARGIN_TRADE"))) ||
        isTrue(!isEqual(marginMode, std::any{}));
    params = this->omit(params, ccxt::list{std::string("stopLossPrice"),
                                           std::string("takeProfitPrice"),
                                           std::string("triggerPrice"),
                                           std::string("stopPrice")});
    if (isTrue(isTriggerOrder)) {
      if (isTrue(!isEqual(triggerPrice, std::any{}))) {
        ::setValue(request, std::string("stopPrice"),
                   this->priceToPrecision(symbol, triggerPrice));
      } else if (isTrue(isTrue((!isEqual(stopLossPrice, std::any{}))) ||
                        isTrue((!isEqual(takeProfitPrice, std::any{}))))) {
        if (isTrue(!isEqual(stopLossPrice, std::any{}))) {
          ::setValue(request, std::string("stop"),
                     (isTrue((isEqual(side, std::string("buy"))))
                          ? std::any(std::string("entry"))
                          : std::any(std::string("loss"))));
          ::setValue(request, std::string("stopPrice"),
                     this->priceToPrecision(symbol, stopLossPrice));
        } else {
          ::setValue(request, std::string("stop"),
                     (isTrue((isEqual(side, std::string("buy"))))
                          ? std::any(std::string("loss"))
                          : std::any(std::string("entry"))));
          ::setValue(request, std::string("stopPrice"),
                     this->priceToPrecision(symbol, takeProfitPrice));
        }
      }
      if (isTrue(isEqual(marginMode, std::string("isolated")))) {
        throw BadRequest(toString(
            add(this->id, std::string(" createOrder does not support isolated "
                                      "margin for stop orders"))));
      } else if (isTrue(isEqual(marginMode, std::string("cross")))) {
        ::setValue(
            request, std::string("tradeType"),
            ::getValue(::getValue(this->options, std::string("marginModes")),
                       marginMode));
      }
    } else if (isTrue(isMarginOrder)) {
      if (isTrue(isEqual(marginMode, std::string("isolated")))) {
        ::setValue(request, std::string("marginModel"),
                   std::string("isolated"));
      }
    }
    std::any postOnly = std::any{};
    std::any postOnlyparamsVariable = this->handlePostOnly(
        isEqual(type, std::string("market")), false, params);
    postOnly = ::getValue(postOnlyparamsVariable, 0);
    params = ::getValue(postOnlyparamsVariable, 1);
    if (isTrue(isEqual(postOnly, true))) {
      ::setValue(request, std::string("postOnly"), true);
    }
    return this->extend(request, params);
  }

  virtual std::any marketOrderAmountToPrecision(std::any symbol,
                                                std::any amount) {
    std::any market = this->market(symbol);
    std::any result = this->decimalToPrecision(
        amount, TRUNCATE,
        ::getValue(::getValue(market, std::string("info")),
                   std::string("quoteIncrement")),
        this->precisionMode, this->paddingMode);
    if (isTrue(isEqual(result, std::string("0")))) {
      throw InvalidOrder(toString(
          add(add(add(add(this->id, std::string(" amount of ")),
                      ::getValue(market, std::string("symbol"))),
                  std::string(
                      " must be greater than minimum amount precision of ")),
              this->numberToString(
                  ::getValue(::getValue(market, std::string("precision")),
                             std::string("amount"))))));
    }
    return result;
  }

  /**
   * @method
   * @name kucoin#createContractOrder
   * @description helper method for creating contract orders
   * @see https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order-test
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-take-profit-and-stop-loss-order
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} type 'limit' or 'market'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount the amount of currency to trade
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.takeProfit] *takeProfit object in params*
   * containing the triggerPrice at which the attached take profit order will be
   * triggered and the triggerPriceType
   * @param {object} [params.stopLoss] *stopLoss object in params* containing
   * the triggerPrice at which the attached stop loss order will be triggered
   * and the triggerPriceType
   * @param {float} [params.triggerPrice] The price a trigger order is triggered
   * at
   * @param {float} [params.stopLossPrice] price to trigger stop-loss orders
   * @param {float} [params.takeProfitPrice] price to trigger take-profit orders
   * @param {bool} [params.reduceOnly] A mark to reduce the position size only.
   * Set to false by default. Need to set the position size when reduceOnly is
   * true.
   * @param {string} [params.timeInForce] GTC, GTT, IOC, or FOK, default is GTC,
   * limit orders only
   * @param {bool} [params.postOnly] Post only flag, invalid when timeInForce is
   * IOC or FOK
   * @param {float} [params.cost] the cost of the order in units of USDT
   * @param {string} [params.marginMode] 'cross' or 'isolated', default is
   * 'isolated'
   * @param {bool} [params.hedged] *swap and future only* true for hedged mode,
   * false for one way mode, default is false
   * ----------------- Exchange Specific Parameters -----------------
   * @param {float} [params.leverage] Leverage size of the order (mandatory
   * param in request, default is 1)
   * @param {string} [params.clientOid] client order id, defaults to uuid if not
   * passed
   * @param {string} [params.remark] remark for the order, length cannot exceed
   * 100 utf8 characters
   * @param {string} [params.stop] 'up' or 'down', the direction the
   * triggerPrice is triggered from, requires triggerPrice. down: Triggers when
   * the price reaches or goes below the triggerPrice. up: Triggers when the
   * price reaches or goes above the triggerPrice.
   * @param {string} [params.triggerPriceType] "last", "mark", "index" -
   * defaults to "mark"
   * @param {string} [params.stopPriceType] exchange-specific alternative for
   * triggerPriceType: TP, IP or MP
   * @param {bool} [params.closeOrder] set to true to close position
   * @param {bool} [params.test] set to true to use the test order endpoint
   * (does not submit order, use to validate params)
   * @param {bool} [params.forceHold] A mark to forcely hold the funds for an
   * order, even though it's an order to reduce the position size. This helps
   * the order stay on the order book and not get canceled when the position
   * size changes. Set to false by default.\
   * @param {string} [params.positionSide] *swap and future only* hedged two-way
   * position side, LONG or SHORT
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  createContractOrder(std::any symbol, std::any type, std::any side,
                      std::any amount, std::any price = std::any{},
                      std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any testOrder =
                     this->safeBool(params, std::string("test"), false);
                 params = this->omit(params, std::string("test"));
                 std::any hasTpOrSlOrder =
                     isTrue((!isEqual(
                         this->safeValue(params, std::string("stopLoss")),
                         std::any{}))) ||
                     isTrue((!isEqual(
                         this->safeValue(params, std::string("takeProfit")),
                         std::any{})));
                 std::any orderRequest = this->createContractOrderRequest(
                     symbol, type, side, amount, price, params);
                 std::any response = std::any{};
                 if (isTrue(isEqual(testOrder, true))) {
                   response = awaitValue(
                       this->futuresPrivatePostOrdersTest(orderRequest));
                 } else {
                   if (isTrue(hasTpOrSlOrder)) {
                     response = awaitValue(
                         this->futuresPrivatePostStOrders(orderRequest));
                   } else {
                     response = awaitValue(
                         this->futuresPrivatePostOrders(orderRequest));
                   }
                 }
                 //
                 //    {
                 //        "code": "200000",
                 //        "data": {
                 //            "orderId": "619717484f1d010001510cde",
                 //        },
                 //    }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseOrder(data, market);
               })
        .share();
  }

  virtual std::any createContractOrderRequest(std::any symbol, std::any type,
                                              std::any side, std::any amount,
                                              std::any price = std::any{},
                                              std::any params = ccxt::dict{}) {
    if (isTrue(isEqual(type, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a type argument"))));
    }
    if (isTrue(isEqual(side, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a side argument"))));
    }
    std::any market = this->market(symbol);
    // required param, cannot be used twice
    std::any clientOrderId =
        this->safeString2(params, std::string("clientOid"),
                          std::string("clientOrderId"), this->uuid());
    params = this->omit(params, ccxt::list{std::string("clientOid"),
                                           std::string("clientOrderId")});
    std::any request = ccxt::dict{
        {std::string("clientOid"), clientOrderId},
        {std::string("side"), side},
        {std::string("symbol"), ::getValue(market, std::string("id"))},
        {std::string("type"), type},
        {std::string("leverage"), 1},
    };
    std::any marginModeUpper =
        this->safeStringUpper(params, std::string("marginMode"));
    if (isTrue(!isEqual(marginModeUpper, std::any{}))) {
      params = this->omit(params, std::string("marginMode"));
      ::setValue(request, std::string("marginMode"), marginModeUpper);
    }
    std::any cost = this->safeString(params, std::string("cost"));
    params = this->omit(params, std::string("cost"));
    if (isTrue(!isEqual(cost, std::any{}))) {
      ::setValue(request, std::string("valueQty"),
                 this->costToPrecision(symbol, cost));
    } else {
      if (isTrue(isEqual(amount, std::any{}))) {
        throw ArgumentsRequired(toString(
            add(this->id, std::string(" requires an amount argument"))));
      }
      if (isTrue(isLessThan(amount, 1))) {
        throw InvalidOrder(toString(add(
            this->id,
            std::string(" createOrder() minimum contract order amount is 1"))));
      }
      std::any sizeString = this->amountToPrecision(symbol, amount);
      if (isTrue(!isEqual(sizeString, std::any{}))) {
        ::setValue(request, std::string("size"), parseInt(sizeString));
      }
    }
    std::any triggerPricestopLossPricetakeProfitPriceVariable =
        this->handleTriggerPrices(params);
    std::any triggerPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 0);
    std::any stopLossPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 1);
    std::any takeProfitPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 2);
    std::any stopLoss = this->safeDict(params, std::string("stopLoss"));
    std::any takeProfit = this->safeDict(params, std::string("takeProfit"));
    std::any hasStopLoss = !isEqual(stopLoss, std::any{});
    std::any hasTakeProfit = !isEqual(takeProfit, std::any{});
    // const isTpAndSl = stopLossPrice && takeProfitPrice;
    std::any triggerPriceTypes = ccxt::dict{
        {std::string("mark"), std::string("MP")},
        {std::string("last"), std::string("TP")},
        {std::string("index"), std::string("IP")},
    };
    std::any triggerPriceType = this->safeString(
        params, std::string("triggerPriceType"), std::string("mark"));
    std::any triggerPriceTypeValue =
        this->safeString(triggerPriceTypes, triggerPriceType, triggerPriceType);
    params = this->omit(
        params,
        ccxt::list{std::string("stopLossPrice"), std::string("takeProfitPrice"),
                   std::string("triggerPrice"), std::string("stopPrice"),
                   std::string("takeProfit"), std::string("stopLoss")});
    if (isTrue(!isEqual(triggerPrice, std::any{}))) {
      ::setValue(request, std::string("stop"),
                 (isTrue((isEqual(side, std::string("buy"))))
                      ? std::any(std::string("up"))
                      : std::any(std::string("down"))));
      ::setValue(request, std::string("stopPrice"),
                 this->priceToPrecision(symbol, triggerPrice));
      ::setValue(request, std::string("stopPriceType"), triggerPriceTypeValue);
    } else if (isTrue(isTrue(hasStopLoss) || isTrue(hasTakeProfit))) {
      std::any priceType = triggerPriceTypeValue;
      if (isTrue(hasStopLoss)) {
        std::any slPrice = this->safeString2(
            stopLoss, std::string("triggerPrice"), std::string("stopPrice"));
        ::setValue(request, std::string("triggerStopDownPrice"),
                   this->priceToPrecision(symbol, slPrice));
        priceType = this->safeString(stopLoss, std::string("triggerPriceType"),
                                     std::string("mark"));
        priceType = this->safeString(triggerPriceTypes, priceType, priceType);
      }
      if (isTrue(hasTakeProfit)) {
        std::any tpPrice =
            this->safeString2(takeProfit, std::string("triggerPrice"),
                              std::string("takeProfitPrice"));
        ::setValue(request, std::string("triggerStopUpPrice"),
                   this->priceToPrecision(symbol, tpPrice));
        priceType = this->safeString(
            takeProfit, std::string("triggerPriceType"), std::string("mark"));
        priceType = this->safeString(triggerPriceTypes, priceType, priceType);
      }
      ::setValue(request, std::string("stopPriceType"), priceType);
    } else if (isTrue(isTrue((!isEqual(stopLossPrice, std::any{}))) ||
                      isTrue((!isEqual(takeProfitPrice, std::any{}))))) {
      if (isTrue(!isEqual(stopLossPrice, std::any{}))) {
        ::setValue(request, std::string("stop"),
                   (isTrue((isEqual(side, std::string("buy"))))
                        ? std::any(std::string("up"))
                        : std::any(std::string("down"))));
        ::setValue(request, std::string("stopPrice"),
                   this->priceToPrecision(symbol, stopLossPrice));
      } else {
        ::setValue(request, std::string("stop"),
                   (isTrue((isEqual(side, std::string("buy"))))
                        ? std::any(std::string("down"))
                        : std::any(std::string("up"))));
        ::setValue(request, std::string("stopPrice"),
                   this->priceToPrecision(symbol, takeProfitPrice));
      }
      ::setValue(request, std::string("reduceOnly"), true);
      ::setValue(request, std::string("stopPriceType"), triggerPriceTypeValue);
    }
    std::any uppercaseType = toUpperCase(type);
    std::any timeInForce =
        this->safeStringUpper(params, std::string("timeInForce"));
    if (isTrue(isEqual(uppercaseType, std::string("LIMIT")))) {
      if (isTrue(isEqual(price, std::any{}))) {
        throw ArgumentsRequired(toString(add(
            this->id,
            std::string(
                " createOrder() requires a price argument for limit orders"))));
      } else {
        ::setValue(request, std::string("price"),
                   this->priceToPrecision(symbol, price));
      }
      if (isTrue(!isEqual(timeInForce, std::any{}))) {
        ::setValue(request, std::string("timeInForce"), timeInForce);
      }
    }
    std::any postOnly = std::any{};
    std::any postOnlyparamsVariable = this->handlePostOnly(
        isEqual(type, std::string("market")), false, params);
    postOnly = ::getValue(postOnlyparamsVariable, 0);
    params = ::getValue(postOnlyparamsVariable, 1);
    if (isTrue(isEqual(postOnly, true))) {
      ::setValue(request, std::string("postOnly"), true);
    }
    std::any hidden = this->safeValue(params, std::string("hidden"));
    if (isTrue(isTrue((isEqual(postOnly, true))) &&
               isTrue((!isEqual(hidden, std::any{}))))) {
      throw BadRequest(toString(
          add(this->id,
              std::string(" createOrder() does not support the postOnly "
                          "parameter together with a hidden parameter"))));
    }
    std::any iceberg = this->safeValue(params, std::string("iceberg"));
    if (isTrue(isTrue((!isEqual(iceberg, std::any{}))) &&
               isTrue((!isEqual(iceberg, false))))) {
      std::any visibleSize =
          this->safeValue(params, std::string("visibleSize"));
      if (isTrue(isEqual(visibleSize, std::any{}))) {
        throw ArgumentsRequired(toString(
            add(this->id, std::string(" createOrder() requires a visibleSize "
                                      "parameter for iceberg orders"))));
      }
    }
    std::any reduceOnly =
        this->safeBool(params, std::string("reduceOnly"), false);
    std::any hedged = std::any{};
    std::any hedgedparamsVariable =
        this->handleParamBool(params, std::string("hedged"), false);
    hedged = ::getValue(hedgedparamsVariable, 0);
    params = ::getValue(hedgedparamsVariable, 1);
    if (isTrue(isEqual(reduceOnly, true))) {
      ::setValue(request, std::string("reduceOnly"), reduceOnly);
      if (isTrue(isEqual(hedged, true))) {
        std::any reduceOnlyPosSide =
            (isTrue((isEqual(side, std::string("sell"))))
                 ? std::any(std::string("LONG"))
                 : std::any(std::string("SHORT")));
        ::setValue(request, std::string("positionSide"), reduceOnlyPosSide);
      }
    } else {
      if (isTrue(isEqual(hedged, true))) {
        std::any posSide = (isTrue((isEqual(side, std::string("buy"))))
                                ? std::any(std::string("LONG"))
                                : std::any(std::string("SHORT")));
        ::setValue(request, std::string("positionSide"), posSide);
      }
    }
    params = this->omit(
        params,
        ccxt::list{
            std::string("timeInForce"), std::string("stopPrice"),
            std::string("triggerPrice"), std::string("stopLossPrice"),
            std::string("takeProfitPrice"), std::string("reduceOnly"),
            std::string(
                "hedged")}); // Time in force only valid for limit orders,
                             // exchange error when gtc for market orders
    return this->extend(request, params);
  }

  /**
   * @method
   * @name kucoin#createUtaOrder
   * @description helper method for creating uta orders
   * @see https://www.kucoin.com/docs-new/rest/ua/place-order
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} type 'limit' or 'market'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount the amount of currency to trade
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] client order id, defaults to uuid if
   * not passed
   * @param {float} [params.cost] the cost of the order in units of quote
   * currency
   * @param {string} [params.timeInForce] GTC, GTD, IOC, FOK or PO
   * @param {bool} [params.postOnly] Post only flag, invalid when timeInForce is
   * IOC or FOK (default is false)
   * @param {bool} [params.reduceOnly] *contract markets only* A mark to reduce
   * the position size only. Set to false by default
   * @param {float} [params.triggerPrice] The price a trigger order is triggered
   * at
   * @param {string} [params.triggerDirection] 'ascending' or 'descending', the
   * direction the triggerPrice is triggered from, requires triggerPrice
   * @param {string} [params.triggerPriceType] *contract markets only* "last",
   * "mark", "index" - defaults to "mark"
   * @param {float} [params.stopLossPrice] price to trigger stop-loss orders
   * @param {float} [params.takeProfitPrice] price to trigger take-profit orders
   * @param {string} [params.marginMode] 'cross' or 'isolated', (default is
   * 'cross' for margin orders, default is 'isolated' for contract orders)
   *
   * Exchange-specific parameters
   * -------------------------------------------------
   * @param {string} [params.accountMode] 'unified' or 'classic', default is
   * 'unified'
   * @param {string} [params.stp] '', // self trade prevention, CN, CO, CB or DC
   * @param {int} [params.cancelAfter] - Cancel After N Seconds (Calculated from
   * the time of entering the matching engine), only effective when timeInForce
   * is GTD
   * @param {string} [params.sizeUnit] *contracts only* 'BASECCY' (amount of
   * base currency) or 'UNIT' (number of contracts), default is 'UNIT'
   *
   * Classic account parameters
   * @param {bool} [params.autoBorrow] *classic margin orders only*
   * @param {bool} [params.autoRepay] *classic margin orders only*
   * @param {string} [params.hedged] *classic contract orders only* true for
   * hedged mode, false for one way mode, default is false
   * @param {int} [params.leverage] *classic contract orders with isolated
   * marginMode only* Leverage size of the order
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  createUtaOrder(std::any symbol, std::any type, std::any side, std::any amount,
                 std::any price = std::any{}, std::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = this->createUtaOrderRequest(
                            symbol, type, side, amount, price, params);
                        std::any response = awaitValue(
                            this->utaPrivatePostAccountModeOrderPlace(request));
                        //
                        //     {
                        //         "code": "200000",
                        //         "data": {
                        //             "orderId": "426319129738321920",
                        //             "tradeType": "SPOT",
                        //             "ts": 1774455603216000000,
                        //             "clientOid":
                        //             "b896c118-a674-4863-baf4-a9ea3cd696c5"
                        //         }
                        //     }
                        //
                        std::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseOrder(data, market);
                      })
        .share();
  }

  virtual std::any createUtaOrderRequest(std::any symbol, std::any type,
                                         std::any side, std::any amount,
                                         std::any price = std::any{},
                                         std::any params = ccxt::dict{}) {
    if (isTrue(isEqual(type, std::any{}))) {
      throw ArgumentsRequired(
          toString(add(this->id, std::string(" requires a type argument"))));
    }
    std::any market = this->market(symbol);
    if (isTrue(isEqual(side, std::any{}))) {
      throw ArgumentsRequired(toString(add(
          this->id, std::string(" createOrder() requires a side argument"))));
    }
    std::any isSpot = ::getValue(market, std::string("spot"));
    std::any isContract = ::getValue(market, std::string("contract"));
    std::any accountMode = std::string("unified");
    std::any accountModeparamsVariable =
        this->handleOptionAndParams(params, std::string("createOrder"),
                                    std::string("accountMode"), accountMode);
    accountMode = ::getValue(accountModeparamsVariable, 0);
    params = ::getValue(accountModeparamsVariable, 1);
    std::any isUnified = (isEqual(accountMode, std::string("unified")));
    std::any marginMode = std::any{};
    std::any marginModeparamsVariable =
        this->handleMarginModeAndParams(std::string("createOrder"), params);
    marginMode = ::getValue(marginModeparamsVariable, 0);
    params = ::getValue(marginModeparamsVariable, 1);
    std::any tradeType =
        this->handleTradeType(isContract, marginMode, isUnified, params);
    std::any clientOrderId =
        this->safeString2(params, std::string("clientOid"),
                          std::string("clientOrderId"), this->uuid());
    params = this->omit(params, ccxt::list{std::string("clientOid"),
                                           std::string("clientOrderId")});
    std::any request = ccxt::dict{
        {std::string("accountMode"), accountMode},
        {std::string("tradeType"), tradeType},
        {std::string("clientOid"), clientOrderId},
        {std::string("symbol"), ::getValue(market, std::string("id"))},
        {std::string("side"), toUpperCase(side)},
        {std::string("orderType"), toUpperCase(type)},
    };
    if (isTrue(!isEqual(tradeType, std::any{}))) {
      ::setValue(request, std::string("tradeType"), tradeType);
    }
    ::setValue(request, std::string("clientOid"), clientOrderId);
    std::any isMarketOrder = (isEqual(type, std::string("market")));
    std::any cost = this->safeString(params, std::string("cost"));
    if (isTrue(!isEqual(cost, std::any{}))) {
      params = this->omit(params, std::string("cost"));
      if (isTrue(isTrue((isEqual(isSpot, true))) && isTrue(isMarketOrder))) {
        ::setValue(request, std::string("sizeUnit"), std::string("QUOTECCY"));
        ::setValue(request, std::string("size"),
                   this->marketOrderAmountToPrecision(symbol, cost));
      } else {
        throw NotSupported(toString(
            add(this->id, std::string(" createOrder() with cost is supported "
                                      "for spot market orders only"))));
      }
    } else {
      std::any sizeUnit = std::string("BASECCY");
      if (isTrue(isEqual(isContract, true))) {
        std::any sizeUnitparamsVariable = this->handleOptionAndParams(
            params, std::string("createOrder"), std::string("sizeUnit"),
            std::string("UNIT"));
        sizeUnit = ::getValue(sizeUnitparamsVariable, 0);
        params = ::getValue(sizeUnitparamsVariable, 1);
      }
      ::setValue(request, std::string("sizeUnit"), sizeUnit);
      ::setValue(request, std::string("size"),
                 this->amountToPrecision(symbol, amount));
    }
    if (!isTrue(isMarketOrder)) {
      ::setValue(request, std::string("price"),
                 this->priceToPrecision(symbol, price));
    }
    std::any postOnly = std::any{};
    std::any postOnlyparamsVariable =
        this->handlePostOnly(isMarketOrder, false, params);
    postOnly = ::getValue(postOnlyparamsVariable, 0);
    params = ::getValue(postOnlyparamsVariable, 1);
    std::any timeInForce = this->handleTimeInForce(params);
    if (isTrue((!isEqual(timeInForce, std::any{})))) {
      params = this->omit(params, std::string("timeInForce"));
      ::setValue(request, std::string("timeInForce"), timeInForce);
    }
    if (isTrue(isEqual(postOnly, true))) {
      ::setValue(request, std::string("postOnly"), true);
    }
    if (isTrue(isEqual(isContract, true))) {
      if (!isTrue(isUnified)) {
        if (isTrue(!isEqual(marginMode, std::any{}))) {
          ::setValue(request, std::string("marginMode"),
                     toUpperCase(marginMode));
          if (isTrue(isEqual(marginMode, std::string("isolated")))) {
            std::any leverage =
                this->safeInteger(params, std::string("leverage"));
            if (isTrue(isEqual(leverage, std::any{}))) {
              ::setValue(request, std::string("leverage"), 1);
            }
          }
        }
        std::any reduceOnly =
            this->safeBool(params, std::string("reduceOnly"), false);
        std::any hedged = false;
        std::any hedgedparamsVariable =
            this->handleParamBool(params, std::string("hedged"), hedged);
        hedged = ::getValue(hedgedparamsVariable, 0);
        params = ::getValue(hedgedparamsVariable, 1);
        if (isTrue(isEqual(hedged, true))) {
          std::any positionSide = (isTrue((isEqual(side, std::string("buy"))))
                                       ? std::any(std::string("LONG"))
                                       : std::any(std::string("SHORT")));
          if (isTrue(isEqual(reduceOnly, true))) {
            positionSide = (isTrue((isEqual(positionSide, std::string("LONG"))))
                                ? std::any(std::string("SHORT"))
                                : std::any(std::string("LONG")));
          }
          ::setValue(request, std::string("positionSide"), positionSide);
        }
      }
    }
    // handling with conditional orders
    std::any triggerPricestopLossPricetakeProfitPriceVariable =
        this->handleTriggerPrices(params);
    std::any triggerPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 0);
    std::any stopLossPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 1);
    std::any takeProfitPrice =
        ::getValue(triggerPricestopLossPricetakeProfitPriceVariable, 2);
    std::any stopLoss = this->safeDict(params, std::string("stopLoss"));
    std::any takeProfit = this->safeDict(params, std::string("takeProfit"));
    std::any hasStopLoss = !isEqual(stopLoss, std::any{});
    std::any hasTakeProfit = !isEqual(takeProfit, std::any{});
    std::any triggerPriceTypes = ccxt::dict{
        {std::string("mark"), std::string("MP")},
        {std::string("last"), std::string("TP")},
        {std::string("index"), std::string("IP")},
    };
    if (isTrue(!isEqual(triggerPrice, std::any{}))) {
      std::any triggerDirection =
          this->safeString(params, std::string("triggerDirection"));
      if (isTrue(isEqual(triggerDirection, std::any{}))) {
        throw ArgumentsRequired(toString(add(
            this->id,
            std::string(" createOrder() requires a triggerDirection parameter "
                        "for trigger orders. Provide params.tringgerDirection "
                        "or use params.stopLossPrice or params.takeProfitPrice "
                        "instead of params.triggerPrice"))));
      }
      ::setValue(request, std::string("triggerDirection"),
                 (isTrue((isEqual(triggerDirection, std::string("ascending"))))
                      ? std::any(std::string("UP"))
                      : std::any(std::string("DOWN"))));
      ::setValue(request, std::string("triggerPrice"),
                 this->priceToPrecision(symbol, triggerPrice));
    } else if (isTrue(isTrue(hasStopLoss) || isTrue(hasTakeProfit))) {
      if (isTrue(!isEqual(isContract, true))) {
        throw NotSupported(toString(
            add(this->id,
                std::string(" createOrder() stopLoss and takeProfit parameters "
                            "are only supported for contract orders"))));
      }
      if (isTrue(hasStopLoss)) {
        std::any slTriggerPrice = this->safeString2(
            stopLoss, std::string("triggerPrice"), std::string("stopPrice"));
        std::any slTriggerPriceType = this->safeString(
            stopLoss, std::string("triggerPriceType"), std::string("mark"));
        ::setValue(request, std::string("slTriggerPrice"),
                   this->priceToPrecision(symbol, slTriggerPrice));
        ::setValue(request, std::string("slTriggerPriceType"),
                   this->safeString(triggerPriceTypes, slTriggerPriceType,
                                    slTriggerPriceType));
      }
      if (isTrue(hasTakeProfit)) {
        std::any tpTriggerPrice =
            this->safeString2(takeProfit, std::string("triggerPrice"),
                              std::string("takeProfitPrice"));
        std::any tpTriggerPriceType = this->safeString(
            takeProfit, std::string("triggerPriceType"), std::string("mark"));
        ::setValue(request, std::string("tpTriggerPrice"),
                   this->priceToPrecision(symbol, tpTriggerPrice));
        ::setValue(request, std::string("tpTriggerPriceType"),
                   this->safeString(triggerPriceTypes, tpTriggerPriceType,
                                    tpTriggerPriceType));
      }
    } else if (isTrue(isTrue((!isEqual(stopLossPrice, std::any{}))) ||
                      isTrue((!isEqual(takeProfitPrice, std::any{}))))) {
      if (isTrue(!isEqual(stopLossPrice, std::any{}))) {
        ::setValue(request, std::string("triggerDirection"),
                   (isTrue((isEqual(side, std::string("buy"))))
                        ? std::any(std::string("UP"))
                        : std::any(std::string("DOWN"))));
        ::setValue(request, std::string("triggerPrice"),
                   this->priceToPrecision(symbol, stopLossPrice));
        if (isTrue(isEqual(isContract, true))) {
          std::any stopLossPriceType = this->safeString2(
              params, std::string("stopLossPriceType"),
              std::string("triggerPriceType"), std::string("mark"));
          ::setValue(request, std::string("triggerPriceType"),
                     this->safeString(triggerPriceTypes, stopLossPriceType,
                                      stopLossPriceType));
        }
      } else {
        ::setValue(request, std::string("triggerDirection"),
                   (isTrue((isEqual(side, std::string("buy"))))
                        ? std::any(std::string("DOWN"))
                        : std::any(std::string("UP"))));
        ::setValue(request, std::string("triggerPrice"),
                   this->priceToPrecision(symbol, takeProfitPrice));
        if (isTrue(isEqual(isContract, true))) {
          std::any takeProfitPriceType = this->safeString2(
              params, std::string("takeProfitPriceType"),
              std::string("triggerPriceType"), std::string("mark"));
          ::setValue(request, std::string("triggerPriceType"),
                     this->safeString(triggerPriceTypes, takeProfitPriceType,
                                      takeProfitPriceType));
        }
      }
    }
    params = this->omit(
        params,
        ccxt::list{std::string("triggerPrice"), std::string("stopLossPrice"),
                   std::string("takeProfitPrice"), std::string("stopPriceType"),
                   std::string("stopLossPriceType"),
                   std::string("takeProfitPriceType"),
                   std::string("triggerPriceType"),
                   std::string("triggerDirection"), std::string("stopLoss"),
                   std::string("takeProfit"), std::string("hedged")});
    return this->extend(request, params);
  }

  /**
   * @method
   * @name kucoin#createMarketOrderWithCost
   * @description create a market order by providing the symbol, side and cost
   * @see https://www.kucoin.com/docs-new/rest/spot-trading/orders/add-order
   * @see https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} side 'buy' or 'sell'
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createMarketOrderWithCost(std::any symbol, std::any side, std::any cost,
                            std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any req = ccxt::dict{
                            {std::string("cost"), cost},
                        };
                        return awaitValue(this->createOrder(
                            symbol, std::string("market"), side, cost,
                            std::any{}, this->extend(req, params)));
                      })
        .share();
  }

