  /**
   * @method
   * @name kucoin#createOrders
   * @description create a list of trade orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/batch-add-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/batch-add-orders-sync
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint Check createSpotOrders() and createContractOrders() for more
   * details on the extra parameters that can be used in params
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrders(std::any orders, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any isSpot = false;
                 std::any isContract = false;
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any order = this->safeDict(orders, i);
                   std::any symbol =
                       this->safeString(order, std::string("symbol"));
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id, std::string(" createOrders() requires a "
                                                   "symbol for each order"))));
                   }
                   std::any market = this->market(symbol);
                   if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                      true))) {
                     isSpot = true;
                   } else if (isTrue(isEqual(
                                  ::getValue(market, std::string("contract")),
                                  true))) {
                     isContract = true;
                   }
                 }
                 if (isTrue(isTrue(isSpot) && isTrue(isContract))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" createOrders() requires all orders to "
                                       "be either spot or contract"))));
                 } else if (isTrue(isSpot)) {
                   return awaitValue(this->createSpotOrders(orders, params));
                 } else if (isTrue(isContract)) {
                   return awaitValue(
                       this->createContractOrders(orders, params));
                 } else {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(" createOrders() does not support the "
                                       "markets of the orders provided"))));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#createSpotOrders
   * @description helper method for creating spot orders in batch
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/batch-add-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/batch-add-orders-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/batch-add-orders
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.hf] false, // true for hf orders
   * @param {bool} [params.sync] false, // true to use the hf sync call
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createSpotOrders(std::any orders, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any ordersRequests = ccxt::list{};
                 std::any symbol = std::any{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any rawOrder = ::getValue(orders, i);
                   std::any marketId =
                       this->safeString(rawOrder, std::string("symbol"));
                   if (isTrue(isEqual(marketId, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id, std::string(" createOrders() requires a "
                                                   "symbol for each order"))));
                   }
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     symbol = marketId;
                   } else {
                     if (isTrue(!isEqual(symbol, marketId))) {
                       throw BadRequest(toString(
                           add(this->id,
                               std::string(" createOrders() requires all "
                                           "orders to have the same symbol"))));
                     }
                   }
                   std::any type =
                       this->safeString(rawOrder, std::string("type"));
                   if (isTrue(!isEqual(type, std::string("limit")))) {
                     throw BadRequest(toString(add(
                         this->id,
                         std::string(
                             " createOrders() only supports limit orders"))));
                   }
                   std::any side =
                       this->safeString(rawOrder, std::string("side"));
                   std::any amount =
                       this->safeValue(rawOrder, std::string("amount"));
                   std::any price =
                       this->safeValue(rawOrder, std::string("price"));
                   std::any orderParams = this->safeValue(
                       rawOrder, std::string("params"), ccxt::dict{});
                   std::any orderRequest = this->createSpotOrderRequest(
                       marketId, type, side, amount, price, orderParams);
                   arrayPush(ordersRequests, orderRequest);
                 }
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" createOrders() requires at least one "
                                       "order with a symbol"))));
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("orderList"), ordersRequests},
                 };
                 std::any hf = std::any{};
                 std::any hfparamsVariable = this->handleHfAndParams(params);
                 hf = ::getValue(hfparamsVariable, 0);
                 params = ::getValue(hfparamsVariable, 1);
                 std::any useSync = false;
                 std::any useSyncparamsVariable = this->handleOptionAndParams(
                     params, std::string("createOrders"), std::string("sync"),
                     false);
                 useSync = ::getValue(useSyncparamsVariable, 0);
                 params = ::getValue(useSyncparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(useSync)) {
                   response = awaitValue(this->privatePostHfOrdersMultiSync(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(hf, true))) {
                   response = awaitValue(this->privatePostHfOrdersMulti(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privatePostOrdersMulti(
                       this->extend(request, params)));
                 }
                 //
                 // {
                 //     "code": "200000",
                 //     "data": {
                 //        "data": [
                 //           {
                 //              "symbol": "LTC-USDT",
                 //              "type": "limit",
                 //              "side": "sell",
                 //              "price": "90",
                 //              "size": "0.1",
                 //              "funds": null,
                 //              "stp": "",
                 //              "stop": "",
                 //              "stopPrice": null,
                 //              "timeInForce": "GTC",
                 //              "cancelAfter": 0,
                 //              "postOnly": false,
                 //              "hidden": false,
                 //              "iceberge": false,
                 //              "iceberg": false,
                 //              "visibleSize": null,
                 //              "channel": "API",
                 //              "id": "6539148443fcf500079d15e5",
                 //              "status": "success",
                 //              "failMsg": null,
                 //              "clientOid":
                 //              "5c4c5398-8ab2-4b4e-af8a-e2d90ad2488f"
                 //           },
                 // }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 data = this->safeList(data, std::string("data"), ccxt::list{});
                 return this->parseOrders(data);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#createContractOrders
   * @description helper method for creating contract orders in batch
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/batch-add-orders
   * @param {Array} orders list of orders to create, each object should contain
   * the parameters required by createOrder, namely symbol, type, side, amount,
   * price and params
   * @param {object} [params]  extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createContractOrders(std::any orders,
                       std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any ordersRequests = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(orders));
                      postFixIncrement(i)) {
                   std::any rawOrder = ::getValue(orders, i);
                   std::any symbol =
                       this->safeString(rawOrder, std::string("symbol"));
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id, std::string(" createOrders() requires a "
                                                   "symbol for each order"))));
                   }
                   std::any type = this->safeString(
                       rawOrder, std::string("type"), std::string(""));
                   std::any side =
                       this->safeString(rawOrder, std::string("side"));
                   std::any amount =
                       this->safeValue(rawOrder, std::string("amount"));
                   std::any price =
                       this->safeValue(rawOrder, std::string("price"));
                   std::any orderParams = this->safeValue(
                       rawOrder, std::string("params"), ccxt::dict{});
                   std::any orderRequest = this->createContractOrderRequest(
                       symbol, type, side, amount, price, orderParams);
                   arrayPush(ordersRequests, orderRequest);
                 }
                 std::any response = awaitValue(
                     this->futuresPrivatePostOrdersMulti(ordersRequests));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": [
                 //             {
                 //                 "orderId": "135241412609331200",
                 //                 "clientOid":
                 //                 "3d8fcc13-0b13-447f-ad30-4b3441e05213",
                 //                 "symbol": "LTCUSDTM",
                 //                 "code": "200000",
                 //                 "msg": "success"
                 //             },
                 //             {
                 //                 "orderId": "135241412747743234",
                 //                 "clientOid":
                 //                 "b878c7ee-ae3e-4d63-a20b-038acbb7306f",
                 //                 "symbol": "LTCUSDTM",
                 //                 "code": "200000",
                 //                 "msg": "success"
                 //             }
                 //         ]
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseOrders(data);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#editOrder
   * @description edit an order, kucoin currently only supports the modification
   * of HF orders
   * @see https://www.kucoin.com/docs-new/rest/spot-trading/orders/modify-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type not used
   * @param {string} side not used
   * @param {float} amount how much of the currency you want to trade in units
   * of the base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] client order id, defaults to id if
   * not passed
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  editOrder(std::any id, std::any symbol, std::any type, std::any side,
            std::any amount = std::any{}, std::any price = std::any{},
            std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any clientOrderId =
                     this->safeString2(params, std::string("clientOid"),
                                       std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   ::setValue(request, std::string("clientOid"), clientOrderId);
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                 }
                 if (isTrue(!isEqual(amount, std::any{}))) {
                   ::setValue(request, std::string("newSize"),
                              this->amountToPrecision(symbol, amount));
                 }
                 if (isTrue(!isEqual(price, std::any{}))) {
                   ::setValue(request, std::string("newPrice"),
                              this->priceToPrecision(symbol, price));
                 }
                 std::any response = awaitValue(this->privatePostHfOrdersAlter(
                     this->extend(request, params)));
                 //
                 // {
                 //     "code":"200000",
                 //     "data":{
                 //        "newOrderId":"6478d7a6c883280001e92d8b"
                 //     }
                 // }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseOrder(data, market);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelOrder
   * @description cancels an open order
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-orderld-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-clientoid-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-stop-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-stop-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-stop-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-stop-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-order-by-clientoid
   * @see https://www.kucoin.com/docs-new/rest/ua/cancel-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot' or 'swap', used if symbol is not
   * provided (default is 'spot')
   * @param {string} [params.marginMode] *spot only* 'cross' or 'isolated'
   * @param {boolean} [params.uta] true for cancelling order with unified
   * account endpoint (default is false) Check cancelSpotOrder() and
   * cancelContractOrder() for more details on the extra parameters that can be
   * used in params
   * @returns Response from the exchange
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("cancelOrder"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(uta)) {
                   return awaitValue(this->cancelUtaOrder(id, symbol, params));
                 }
                 std::any marketType = std::any{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("cancelOrder"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(
                         isTrue((isEqual(marketType, std::string("spot")))) ||
                         isTrue(
                             (isEqual(marketType, std::string("margin")))))) {
                   return awaitValue(this->cancelSpotOrder(id, symbol, params));
                 } else {
                   return awaitValue(
                       this->cancelContractOrder(id, symbol, params));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelSpotOrder
   * @description helper method for cancelling spot orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-orderld-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-order-by-clientoid-sync
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-stop-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-stop-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-order-by-clientoid
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-stop-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-stop-order-by-clientoid
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.trigger] True if cancelling a stop order
   * @param {bool} [params.hf] false, // true for hf order
   * @param {bool} [params.sync] false, // true to use the hf sync call
   * @param {string} [params.marginMode] 'cross' or 'isolated'
   * @returns Response from the exchange
   */
  std::shared_future<std::any>
  cancelSpotOrder(std::any id, std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any request = ccxt::dict{};
                std::any clientOrderId =
                    this->safeString2(params, std::string("clientOid"),
                                      std::string("clientOrderId"));
                std::any trigger = this->safeBool2(
                    params, std::string("stop"), std::string("trigger"), false);
                std::any hf = std::any{};
                std::any hfparamsVariable = this->handleHfAndParams(params);
                hf = ::getValue(hfparamsVariable, 0);
                params = ::getValue(hfparamsVariable, 1);
                std::any useSync = false;
                std::any useSyncparamsVariable = this->handleOptionAndParams(
                    params, std::string("cancelOrder"), std::string("sync"),
                    false);
                useSync = ::getValue(useSyncparamsVariable, 0);
                params = ::getValue(useSyncparamsVariable, 1);
                std::any marginMode = std::any{};
                std::any marginModeparamsVariable =
                    this->handleMarginModeAndParams(std::string("cancelOrder"),
                                                    params);
                marginMode = ::getValue(marginModeparamsVariable, 0);
                params = ::getValue(marginModeparamsVariable, 1);
                std::any tradeType = this->safeString(
                    params,
                    std::string(
                        "tradeType")); // keep it for backward compatibility
                std::any isMarginOrder =
                    isTrue(isEqual(tradeType, std::string("MARGIN_TRADE"))) ||
                    isTrue(!isEqual(marginMode, std::any{}));
                if (isTrue(isTrue(isTrue((isEqual(hf, true))) ||
                                  isTrue(useSync)) ||
                           isTrue(isMarginOrder))) {
                  if (isTrue(!isEqual(trigger, true))) {
                    if (isTrue(isEqual(symbol, std::any{}))) {
                      throw ArgumentsRequired(toString(
                          add(this->id,
                              std::string(" cancelOrder() requires a symbol "
                                          "parameter for hf orders"))));
                    }
                    std::any market = this->market(symbol);
                    ::setValue(request, std::string("symbol"),
                               ::getValue(market, std::string("id")));
                  }
                }
                std::any response = std::any{};
                params =
                    this->omit(params, ccxt::list{std::string("clientOid"),
                                                  std::string("clientOrderId"),
                                                  std::string("stop"),
                                                  std::string("trigger"),
                                                  std::string("tradeType")});
                if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                  ::setValue(request, std::string("clientOid"), clientOrderId);
                  if (isTrue(isEqual(trigger, true))) {
                    if (isTrue(isMarginOrder)) {
                      response = awaitValue(
                          this->privateDeleteHfMarginStopOrderCancelByClientOid(
                              this->extend(request, params)));
                      std::any data =
                          this->safeDict(response, std::string("data"));
                      std::any orderIds = this->safeList(
                          data, std::string("cancelledOrderIds"), ccxt::list{});
                      std::any orderId = this->safeString(orderIds, 0);
                      return this->safeOrder(ccxt::dict{
                          {std::string("info"), data},
                          {std::string("id"), orderId},
                      });
                    } else {
                      //
                      //    {
                      //        code: '200000',
                      //        data: {
                      //          cancelledOrderId: 'vs8lgpiuao41iaft003khbbk',
                      //          clientOid: '123456'
                      //        }
                      //    }
                      //
                      response = awaitValue(
                          this->privateDeleteStopOrderCancelOrderByClientOid(
                              this->extend(request, params)));
                    }
                  } else if (isTrue(isMarginOrder)) {
                    response = awaitValue(
                        this->privateDeleteHfMarginOrdersClientOrderClientOid(
                            this->extend(request, params)));
                  } else if (isTrue(useSync)) {
                    response = awaitValue(
                        this->privateDeleteHfOrdersSyncClientOrderClientOid(
                            this->extend(request, params)));
                  } else if (isTrue(isEqual(hf, true))) {
                    response = awaitValue(
                        this->privateDeleteHfOrdersClientOrderClientOid(
                            this->extend(request, params)));
                  } else {
                    response =
                        awaitValue(this->privateDeleteOrderClientOrderClientOid(
                            this->extend(request, params)));
                  }
                  response = this->safeDict(response, std::string("data"));
                  return this->parseOrder(response);
                } else {
                  ::setValue(request, std::string("orderId"), id);
                  if (isTrue(isEqual(trigger, true))) {
                    if (isTrue(isMarginOrder)) {
                      response = awaitValue(
                          this->privateDeleteHfMarginStopOrderCancelById(
                              this->extend(request, params)));
                    } else {
                      //
                      //    {
                      //        code: '200000',
                      //        data: { cancelledOrderIds: [
                      //        'vs8lgpiuaco91qk8003vebu9' ] }
                      //    }
                      //
                      response = awaitValue(this->privateDeleteStopOrderOrderId(
                          this->extend(request, params)));
                    }
                  } else if (isTrue(isMarginOrder)) {
                    response =
                        awaitValue(this->privateDeleteHfMarginOrdersOrderId(
                            this->extend(request, params)));
                  } else if (isTrue(useSync)) {
                    response =
                        awaitValue(this->privateDeleteHfOrdersSyncOrderId(
                            this->extend(request, params)));
                  } else if (isTrue(isEqual(hf, true))) {
                    response = awaitValue(this->privateDeleteHfOrdersOrderId(
                        this->extend(request, params)));
                    //
                    //    {
                    //        "code": "200000",
                    //        "data": {
                    //          "orderId": "630625dbd9180300014c8d52"
                    //        }
                    //    }
                    //
                    response = this->safeDict(response, std::string("data"),
                                              ccxt::dict{});
                    return this->parseOrder(response);
                  } else {
                    response = awaitValue(this->privateDeleteOrdersOrderId(
                        this->extend(request, params)));
                  }
                  std::any data = this->safeDict(response, std::string("data"));
                  std::any orderId =
                      this->safeString(data, std::string("orderId"));
                  std::any orderIds = this->safeList(
                      data, std::string("cancelledOrderIds"), ccxt::list{});
                  orderId = this->safeString(orderIds, 0, orderId);
                  return this->safeOrder(ccxt::dict{
                      {std::string("info"), data},
                      {std::string("id"), orderId},
                  });
                }
                return std::any{};
              })
            .share();
  }

  /**
   * @method
   * @name kucoin#cancelContractOrder
   * @description helper method for cancelling contract orders
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-order-by-orderld
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-order-by-clientoid
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] cancel order by client order id
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelContractOrder(std::any id, std::any symbol = std::any{},
                      std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any clientOrderId =
                     this->safeString2(params, std::string("clientOid"),
                                       std::string("clientOrderId"));
                 params = this->omit(params,
                                     ccxt::list{std::string("clientOrderId")});
                 std::any request = ccxt::dict{};
                 std::any response = std::any{};
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(
                                 " cancelOrder() requires a symbol argument "
                                 "when cancelling by clientOrderId"))));
                   }
                   std::any market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   ::setValue(request, std::string("clientOid"), clientOrderId);
                   response = awaitValue(
                       this->futuresPrivateDeleteOrdersClientOrderClientOid(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("orderId"), id);
                   response =
                       awaitValue(this->futuresPrivateDeleteOrdersOrderId(
                           this->extend(request, params)));
                 }
                 //
                 //   {
                 //       "code": "200000",
                 //       "data": {
                 //           "cancelledOrderIds": [
                 //                "619714b8b6353000014c505a",
                 //           ],
                 //       },
                 //   }
                 //
                 return this->safeOrder(ccxt::dict{
                     {std::string("info"), response},
                 });
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelUtaOrder
   * @description helper method for cancelling uta orders
   * @see https://www.kucoin.com/docs-new/rest/ua/cancel-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.accountMode] 'unified' or 'classic' (default is
   * 'unified')
   * @param {string} [params.clientOrderId] client order id, required if id is
   * not provided
   * @param {string} [params.marginMode] 'cross' or 'isolated', required if
   * fetching a margin order (unified accountMode supports only cross margin)
   * @returns Response from the exchange
   */
  virtual std::shared_future<std::any>
  cancelUtaOrder(std::any id, std::any symbol = std::any{},
                 std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" cancelOrder() requires a symbol "
                                             "argument for uta endpoint"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any clientOrderId =
                     this->safeString2(params, std::string("clientOid"),
                                       std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                   ::setValue(request, std::string("clientOid"), clientOrderId);
                   params = this->omit(
                       params, ccxt::list{std::string("clientOid"),
                                          std::string("clientOrderId")});
                 } else {
                   if (isTrue(isEqual(id, std::any{}))) {
                     throw ArgumentsRequired(toString(add(
                         this->id,
                         std::string(" fetchOrder() requires an id argument or "
                                     "clientOrderId parameter"))));
                   }
                   ::setValue(request, std::string("orderId"), id);
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 ::setValue(request, std::string("symbol"),
                            ::getValue(market, std::string("id")));
                 std::any accountMode = std::string("unified");
                 std::any accountModeparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("cancelOrder"),
                         std::string("accountMode"), accountMode);
                 accountMode = ::getValue(accountModeparamsVariable, 0);
                 params = ::getValue(accountModeparamsVariable, 1);
                 ::setValue(request, std::string("accountMode"), accountMode);
                 std::any marginMode = std::any{};
                 std::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(std::string("cancelOrder"),
                                                     params);
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 std::any isUnified =
                     (isEqual(accountMode, std::string("unified")));
                 std::any tradeType = this->handleTradeType(
                     ::getValue(market, std::string("contract")), marginMode,
                     isUnified, params);
                 ::setValue(request, std::string("tradeType"), tradeType);
                 std::any response =
                     awaitValue(this->utaPrivatePostAccountModeOrderCancel(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": {
                 //             "orderId": "426319129738321920",
                 //             "tradeType": "SPOT",
                 //             "ts": 1774457628105000000,
                 //             "clientOid":
                 //             "b896c118-a674-4863-baf4-a9ea3cd696c5"
                 //         }
                 //     }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 return this->parseOrder(data, market);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelAllOrders
   * @description cancel all open orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-all-orders-by-symbol
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-all-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/batch-cancel-stop-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-all-orders-by-symbol
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/batch-cancel-stop-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-all-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-all-stop-orders
   * @see https://www.kucoin.com/docs-new/rest/ua/batch-cancel-order-by-symbol
   * @param {string} [symbol] unified market symbol, only orders in the market
   * of this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot' or 'swap', used if symbol is not
   * provided (default is 'spot')
   * @param {string} [params.marginMode] *spot only* 'cross' or 'isolated'
   * @param {boolean} [params.uta] true for cancelling orders with unified
   * account endpoint (default is false) Check cancelAllSpotOrders(),
   * cancelAllContractOrders() and cancelAllUtaOrders() for more details on the
   * extra parameters that can be used in params
   * @returns Response from the exchange
   */
  std::shared_future<std::any>
  cancelAllOrders(std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("cancelAllOrders"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(uta)) {
                   return awaitValue(this->cancelAllUtaOrders(symbol, params));
                 }
                 std::any marketType = std::any{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("cancelAllOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(
                         isTrue((isEqual(marketType, std::string("spot")))) ||
                         isTrue(
                             (isEqual(marketType, std::string("margin")))))) {
                   return awaitValue(this->cancelAllSpotOrders(symbol, params));
                 } else {
                   return awaitValue(
                       this->cancelAllContractOrders(symbol, params));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelAllSpotOrders
   * @description helper method for cancelling all spot orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-all-orders-by-symbol
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/cancel-all-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/batch-cancel-stop-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/cancel-all-orders-by-symbol
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/batch-cancel-stop-orders
   * @param {string} symbol unified market symbol, only orders in the market of
   * this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.trigger] *invalid for isolated margin* true if
   * cancelling all stop orders
   * @param {string} [params.marginMode] 'cross' or 'isolated'
   * @param {string} [params.orderIds] *stop orders only* Comma separated order
   * IDs
   * @param {bool} [params.hf] false, // true for hf order
   * @returns Response from the exchange
   */
  std::shared_future<std::any>
  cancelAllSpotOrders(std::any symbol = std::any{},
                      std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any trigger =
                     this->safeBool2(params, std::string("trigger"),
                                     std::string("stop"), false);
                 std::any hf = std::any{};
                 std::any hfparamsVariable = this->handleHfAndParams(params);
                 hf = ::getValue(hfparamsVariable, 0);
                 params = ::getValue(hfparamsVariable, 1);
                 params =
                     this->omit(params, ccxt::list{std::string("stop"),
                                                   std::string("trigger")});
                 std::any marginModequeryVariable =
                     this->handleMarginModeAndParams(
                         std::string("cancelAllOrders"), params);
                 std::any marginMode = ::getValue(marginModequeryVariable, 0);
                 std::any query = ::getValue(marginModequeryVariable, 1);
                 std::any isMarginOrders = !isEqual(marginMode, std::any{});
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   ::setValue(request, std::string("symbol"),
                              this->marketId(symbol));
                 } else if (isTrue(isTrue((!isEqual(trigger, true))) &&
                                   isTrue(isMarginOrders))) {
                   throw ArgumentsRequired(toString(add(
                       this->id,
                       std::string(" cancelAllOrders() requires a symbol "
                                   "argument for margin non-trigger orders"))));
                 }
                 if (isTrue(isMarginOrders)) {
                   ::setValue(request, std::string("tradeType"),
                              ::getValue(::getValue(this->options,
                                                    std::string("marginModes")),
                                         marginMode));
                   if (isTrue(isTrue(isEqual(marginMode,
                                             std::string("isolated"))) &&
                              isTrue((isEqual(trigger, true))))) {
                     throw BadRequest(toString(
                         add(this->id,
                             std::string(" cancelAllOrders does not support "
                                         "isolated margin for stop orders"))));
                   }
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(trigger, true))) {
                   if (isTrue(isMarginOrders)) {
                     response =
                         awaitValue(this->privateDeleteHfMarginStopOrderCancel(
                             this->extend(request, query)));
                   } else {
                     response = awaitValue(this->privateDeleteStopOrderCancel(
                         this->extend(request, query)));
                   }
                 } else if (isTrue(isMarginOrders)) {
                   response = awaitValue(this->privateDeleteHfMarginOrders(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(hf, true))) {
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     response = awaitValue(this->privateDeleteHfOrdersCancelAll(
                         this->extend(request, query)));
                   } else {
                     response = awaitValue(this->privateDeleteHfOrders(
                         this->extend(request, query)));
                   }
                 } else {
                   response = awaitValue(
                       this->privateDeleteOrders(this->extend(request, query)));
                 }
                 return ccxt::list{this->safeOrder(ccxt::dict{
                     {std::string("info"), response},
                 })};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelAllContractOrders
   * @description helper method for cancelling all contract orders
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-all-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/cancel-all-stop-orders
   * @param {string} symbol unified market symbol, only orders in the market of
   * this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {object} [params.trigger] When true, all the trigger orders will be
   * cancelled
   * @returns Response from the exchange
   */
  std::shared_future<std::any>
  cancelAllContractOrders(std::any symbol = std::any{},
                          std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   ::setValue(request, std::string("symbol"),
                              this->marketId(symbol));
                 }
                 std::any trigger = this->safeValue2(
                     params, std::string("stop"), std::string("trigger"));
                 params =
                     this->omit(params, ccxt::list{std::string("stop"),
                                                   std::string("trigger")});
                 std::any response = std::any{};
                 if (isTrue(isTrue((!isEqual(trigger, std::any{}))) &&
                            isTrue((!isEqual(trigger, false))))) {
                   response = awaitValue(this->futuresPrivateDeleteStopOrders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->futuresPrivateDeleteOrders(
                       this->extend(request, params)));
                 }
                 //
                 //   {
                 //       "code": "200000",
                 //       "data": {
                 //           "cancelledOrderIds": [
                 //                "619714b8b6353000014c505a",
                 //           ],
                 //       },
                 //   }
                 //
                 std::any data = this->safeDict(response, std::string("data"));
                 return ccxt::list{this->safeOrder(ccxt::dict{
                     {std::string("info"), data},
                 })};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#cancelAllUtaOrders
   * @description helper method for cancelling all uta orders
   * @see https://www.kucoin.com/docs-new/rest/ua/batch-cancel-order-by-symbol
   * @param {string} symbol unified market symbol, only orders in the market of
   * this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {bool} [params.trigger] true if cancelling all stop orders
   * @param {string} [params.marginMode] 'CROSS' or 'ISOLATED'
   * @returns Response from the exchange
   */
  virtual std::shared_future<std::any>
  cancelAllUtaOrders(std::any symbol = std::any{},
                     std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" cancelAllOrders() requires a symbol "
                                       "argument for uta endpoint"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any isContract =
                     ::getValue(market, std::string("contract"));
                 std::any tradeType = (isTrue((isEqual(isContract, true)))
                                           ? std::any(std::string("FUTURES"))
                                           : std::any(std::string("SPOT")));
                 std::any trigger = false;
                 std::any triggerparamsVariable = this->handleParamBool(
                     params, std::string("trigger"), trigger);
                 trigger = ::getValue(triggerparamsVariable, 0);
                 params = ::getValue(triggerparamsVariable, 1);
                 std::any orderFilter = (isTrue((isEqual(trigger, true)))
                                             ? std::any(std::string("ADVANCED"))
                                             : std::any(std::string("NORMAL")));
                 std::any request = ccxt::dict{
                     {std::string("accountMode"), std::string("unified")},
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("tradeType"), tradeType},
                     {std::string("orderFilter"), orderFilter},
                 };
                 std::any response =
                     awaitValue(this->utaPrivatePostAccountModeOrderCancelAll(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": {
                 //             "tradeType": "SPOT",
                 //             "ts": 1774458644140000000,
                 //             "items": [
                 //                 {
                 //                     "orderId": "426328635071352832"
                 //                 }
                 //             ]
                 //         }
                 //     }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any orders =
                     this->safeList(data, std::string("items"), ccxt::list{});
                 return this->parseOrders(
                     orders, market, std::any{}, std::any{},
                     ccxt::dict{
                         {std::string("status"), std::string("canceled")},
                     });
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchOrdersByStatus
   * @description fetches a list of orders placed on the exchange
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-open-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-closed-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-stop-orders-list
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-open-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-closed-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-stop-order-list
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/get-order-list
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/get-stop-order-list
   * @see https://www.kucoin.com/docs-new/rest/ua/get-open-order-list
   * @see https://www.kucoin.com/docs-new/rest/ua/get-order-history
   * @param {string} status 'active' or 'closed', only 'active' is valid for
   * stop orders
   * @param {string} symbol unified symbol for the market to retrieve orders
   * from
   * @param {int} [since] timestamp in ms of the earliest order to retrieve
   * @param {int} [limit] The maximum number of orders to retrieve
   * @param {object} [params] exchange specific parameters
   * @param {boolean} [params.uta] true for fetch orders with uta endpoint
   * (default is false) Check fetchSpotOrdersByStatus(),
   * fetchContractOrdersByStatus() and fetchUtaOrdersByStatus() for more details
   * on the extra parameters that can be used in params
   * @returns An [array of order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchOrdersByStatus(std::any status, std::any symbol = std::any{},
                      std::any since = std::any{}, std::any limit = std::any{},
                      std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrdersByStatus"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any marketType = std::any{};
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   std::any type = this->safeString(
                       params, std::string("type")); // exchange has specific
                                                     // param for order type
                   // todo check for better way to determine market type without
                   // symbol
                   if (isTrue(
                           isTrue(
                               isTrue(
                                   isTrue(isTrue(isEqual(
                                              type, std::string("spot"))) ||
                                          isTrue(isEqual(
                                              type, std::string("margin")))) ||
                                   isTrue(
                                       isEqual(type, std::string("swap")))) ||
                               isTrue(isEqual(type, std::string("future")))) ||
                           isTrue(isEqual(type, std::string("contract"))))) {
                     marketType = type;
                     params = this->omit(params, std::string("type"));
                   } else {
                     std::any methodOptions = this->safeDict(
                         this->options, std::string("fetchOrdersByStatus"),
                         ccxt::dict{});
                     std::any methodDefaultType = this->safeString2(
                         methodOptions, std::string("defaultType"),
                         std::string("type"));
                     if (isTrue(isEqual(methodDefaultType, std::any{}))) {
                       marketType = this->safeString2(
                           this->options, std::string("defaultType"),
                           std::string("type"), std::string("spot"));
                     } else {
                       marketType = methodDefaultType;
                     }
                   }
                 } else {
                   std::any market = this->market(symbol);
                   marketType = ::getValue(market, std::string("type"));
                 }
                 if (isTrue(uta)) {
                   params = this->omit(params, std::string("uta"));
                   params = this->extend(
                       params, ccxt::dict{
                                   {std::string("marketType"), marketType},
                               });
                   return awaitValue(this->fetchUtaOrdersByStatus(
                       status, symbol, since, limit, params));
                 } else if (isTrue(isTrue((isEqual(marketType,
                                                   std::string("spot")))) ||
                                   isTrue((isEqual(marketType,
                                                   std::string("margin")))))) {
                   return awaitValue(this->fetchSpotOrdersByStatus(
                       status, symbol, since, limit, params));
                 } else {
                   return awaitValue(this->fetchContractOrdersByStatus(
                       status, symbol, since, limit, params));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchSpotOrdersByStatus
   * @description fetch a list of spot orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-open-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-closed-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-stop-orders-list
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-open-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-closed-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-stop-order-list
   * @param {string} status *not used for stop orders* 'open' or 'closed'
   * @param {string} symbol unified market symbol
   * @param {int} [since] timestamp in ms of the earliest order
   * @param {int} [limit] max number of orders to return
   * @param {object} [params] exchange specific params
   * @param {int} [params.until] end time in ms
   * @param {string} [params.side] buy or sell
   * @param {string} [params.type] limit, market, limit_stop or market_stop
   * @param {string} [params.tradeType] TRADE for spot trading, MARGIN_TRADE or
   * MARGIN_ISOLATED_TRADE for Margin Trading
   * @param {int} [params.currentPage] *trigger orders only* current page
   * @param {string} [params.orderIds] *trigger orders only* comma separated
   * order ID list
   * @param {bool} [params.trigger] True if fetching a trigger order
   * @param {bool} [params.hf] false, // true for hf order
   * @param {string} [params.marginMode] 'cross' or 'isolated', only for margin
   * orders
   * @returns An [array of order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchSpotOrdersByStatus(std::any status, std::any symbol = std::any{},
                          std::any since = std::any{},
                          std::any limit = std::any{},
                          std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any lowercaseStatus = toLowerCase(status);
                 std::any until =
                     this->safeInteger(params, std::string("until"));
                 std::any trigger =
                     this->safeBool2(params, std::string("stop"),
                                     std::string("trigger"), false);
                 std::any hf = std::any{};
                 std::any hfparamsVariable = this->handleHfAndParams(params);
                 hf = ::getValue(hfparamsVariable, 0);
                 params = ::getValue(hfparamsVariable, 1);
                 if (isTrue(isTrue((isEqual(hf, true))) &&
                            isTrue((isEqual(symbol, std::any{}))))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" fetchOrdersByStatus() requires a "
                                       "symbol parameter for hf orders"))));
                 }
                 params = this->omit(params, ccxt::list{std::string("stop"),
                                                        std::string("trigger"),
                                                        std::string("till"),
                                                        std::string("until")});
                 std::any marginModequeryVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchOrdersByStatus"), params);
                 std::any marginMode = ::getValue(marginModequeryVariable, 0);
                 std::any query = ::getValue(marginModequeryVariable, 1);
                 std::any isMarginOrder = !isEqual(marginMode, std::any{});
                 if (isTrue(isEqual(lowercaseStatus, std::string("open")))) {
                   lowercaseStatus = std::string("active");
                 } else if (isTrue(isEqual(lowercaseStatus,
                                           std::string("closed")))) {
                   lowercaseStatus = std::string("done");
                 }
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 ::setValue(
                     request, std::string("tradeType"),
                     this->safeString(
                         ::getValue(this->options, std::string("marginModes")),
                         marginMode, std::string("TRADE")));
                 std::any response = std::any{};
                 if (isTrue(isTrue(isTrue(isMarginOrder) &&
                                   isTrue(isEqual(lowercaseStatus,
                                                  std::string("active")))) &&
                            isTrue((!isEqual(trigger, true))))) {
                   // hf margin open non-trigger orders require only symbol and
                   // tradeType params
                   response = awaitValue(this->privateGetHfMarginOrdersActive(
                       this->extend(request, query)));
                 } else {
                   if (!isTrue(isMarginOrder)) {
                     ::setValue(request, std::string("status"),
                                lowercaseStatus);
                   }
                   if (isTrue(!isEqual(since, std::any{}))) {
                     ::setValue(request, std::string("startAt"), since);
                   }
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("pageSize"), limit);
                   }
                   if (isTrue(isTrue((!isEqual(until, std::any{}))) &&
                              isTrue((!isEqual(until, 0))))) {
                     ::setValue(request, std::string("endAt"), until);
                   }
                   if (isTrue(isEqual(trigger, true))) {
                     if (isTrue(isMarginOrder)) {
                       response = awaitValue(this->privateGetHfMarginStopOrders(
                           this->extend(request, query)));
                     } else {
                       response = awaitValue(this->privateGetStopOrder(
                           this->extend(request, query)));
                     }
                   } else if (isTrue(isMarginOrder)) {
                     response = awaitValue(this->privateGetHfMarginOrdersDone(
                         this->extend(request, query)));
                   } else if (isTrue(isEqual(hf, true))) {
                     if (isTrue(
                             isEqual(lowercaseStatus, std::string("active")))) {
                       response = awaitValue(this->privateGetHfOrdersActive(
                           this->extend(request, query)));
                     } else if (isTrue(isEqual(lowercaseStatus,
                                               std::string("done")))) {
                       response = awaitValue(this->privateGetHfOrdersDone(
                           this->extend(request, query)));
                     }
                   } else {
                     response = awaitValue(
                         this->privateGetOrders(this->extend(request, query)));
                   }
                 }
                 std::any listData =
                     this->safeList(response, std::string("data"));
                 if (isTrue(!isEqual(listData, std::any{}))) {
                   return this->parseOrders(listData, market, since, limit);
                 }
                 std::any responseData = this->safeDict(
                     response, std::string("data"), ccxt::dict{});
                 std::any orders = this->safeList(
                     responseData, std::string("items"), ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchContractOrdersByStatus
   * @description fetches a list of contract orders placed on the exchange
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/get-order-list
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/get-stop-order-list
   * @param {string} status 'active' or 'closed', only 'active' is valid for
   * stop orders
   * @param {string} symbol unified symbol for the market to retrieve orders
   * from
   * @param {int} [since] timestamp in ms of the earliest order to retrieve
   * @param {int} [limit] The maximum number of orders to retrieve
   * @param {object} [params] exchange specific parameters
   * @param {bool} [params.trigger] set to true to retrieve untriggered stop
   * orders
   * @param {int} [params.until] End time in ms
   * @param {string} [params.side] buy or sell
   * @param {string} [params.type] limit or market
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns An [array of order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchContractOrdersByStatus(std::any status, std::any symbol = std::any{},
                              std::any since = std::any{},
                              std::any limit = std::any{},
                              std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrdersByStatus"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchOrdersByStatus"), symbol, since, limit,
                       params));
                 }
                 std::any trigger = this->safeBool2(params, std::string("stop"),
                                                    std::string("trigger"));
                 std::any until =
                     this->safeInteger(params, std::string("until"));
                 params =
                     this->omit(params, ccxt::list{std::string("stop"),
                                                   std::string("until"),
                                                   std::string("trigger")});
                 if (isTrue(isEqual(status, std::string("closed")))) {
                   status = std::string("done");
                 } else if (isTrue(isEqual(status, std::string("open")))) {
                   status = std::string("active");
                 }
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(trigger, true))) {
                   ::setValue(request, std::string("status"), status);
                 } else if (isTrue(!isEqual(status, std::string("active")))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchOrdersByStatus() can only fetch "
                                       "untriggered stop orders"))));
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startAt"), since);
                 }
                 if (isTrue(!isEqual(until, std::any{}))) {
                   ::setValue(request, std::string("endAt"), until);
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(trigger, true))) {
                   response = awaitValue(this->futuresPrivateGetStopOrders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->futuresPrivateGetOrders(
                       this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": {
                 //             "currentPage": 1,
                 //             "pageSize": 50,
                 //             "totalNum": 4,
                 //             "totalPage": 1,
                 //             "items": [
                 //                 {
                 //                     "id": "64507d02921f1c0001ff6892",
                 //                     "symbol": "XBTUSDTM",
                 //                     "type": "market",
                 //                     "side": "buy",
                 //                     "price": null,
                 //                     "size": 1,
                 //                     "value": "27.992",
                 //                     "dealValue": "27.992",
                 //                     "dealSize": 1,
                 //                     "stp": "",
                 //                     "stop": "",
                 //                     "stopPriceType": "",
                 //                     "stopTriggered": false,
                 //                     "stopPrice": null,
                 //                     "timeInForce": "GTC",
                 //                     "postOnly": false,
                 //                     "hidden": false,
                 //                     "iceberg": false,
                 //                     "leverage": "17",
                 //                     "forceHold": false,
                 //                     "closeOrder": false,
                 //                     "visibleSize": null,
                 //                     "clientOid": null,
                 //                     "remark": null,
                 //                     "tags": null,
                 //                     "isActive": false,
                 //                     "cancelExist": false,
                 //                     "createdAt": 1682996482000,
                 //                     "updatedAt": 1682996483062,
                 //                     "endAt": 1682996483062,
                 //                     "orderTime": 1682996482953900677,
                 //                     "settleCurrency": "USDT",
                 //                     "status": "done",
                 //                     "filledValue": "27.992",
                 //                     "filledSize": 1,
                 //                     "reduceOnly": false
                 //                 }
                 //             ]
                 //         }
                 //     }
                 //
                 std::any responseData = this->safeDict(
                     response, std::string("data"), ccxt::dict{});
                 std::any orders = this->safeList(
                     responseData, std::string("items"), ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchUtaOrdersByStatus
   * @description helper method for fetching orders by status with uta endpoint
   * @see https://www.kucoin.com/docs-new/rest/ua/get-open-order-list
   * @see https://www.kucoin.com/docs-new/rest/ua/get-order-history
   * @param {string} status 'active' or 'closed', only 'active' is valid for
   * stop orders
   * @param {string} symbol unified symbol for the market to retrieve orders
   * from
   * @param {int} [since] timestamp in ms of the earliest order to retrieve
   * @param {int} [limit] The maximum number of orders to retrieve
   * @param {object} [params] exchange specific parameters
   * @param {int} [params.until] End time in ms
   * @param {string} [params.side] *closed orders only* 'BUY' or 'SELL'
   * @param {string} [params.accountMode] 'unified' or 'classic' (default is
   * unified)
   * @param {string} [params.marginMode] 'cross' or 'isolated', only for margin
   * orders (unified accountMode supports only cross margin)
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns An [array of order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchUtaOrdersByStatus(std::any status, std::any symbol = std::any{},
                         std::any since = std::any{},
                         std::any limit = std::any{},
                         std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any paginate = false;
                 std::any maxLimit = 200;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrdersByStatus"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchOrdersByStatus"), symbol, since, limit,
                       params, maxLimit));
                 }
                 std::any accountMode = std::string("unified");
                 std::any accountModeparamsVariable =
                     this->handleOptionAndParams(
                         params, std::string("fetchUtaOrdersByStatus"),
                         std::string("accountMode"), accountMode);
                 accountMode = ::getValue(accountModeparamsVariable, 0);
                 params = ::getValue(accountModeparamsVariable, 1);
                 std::any request = ccxt::dict{
                     {std::string("accountMode"), accountMode},
                 };
                 std::any marketType = std::any{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   marketType = ::getValue(market, std::string("type"));
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 } else {
                   marketType =
                       this->safeString(params, std::string("marketType"));
                 }
                 params = this->omit(params, std::string("marketType"));
                 std::any isContract =
                     isTrue((!isEqual(marketType, std::string("spot")))) &&
                     isTrue((!isEqual(marketType, std::string("margin"))));
                 if (isTrue(!isTrue(isContract) &&
                            isTrue((isEqual(symbol, std::any{}))))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" fetchOrdersByStatus() requires a "
                                       "symbol argument for spot and margin "
                                       "markets when using uta endpoint"))));
                 }
                 std::any marginMode = std::any{};
                 std::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchOrdersByStatus"), params);
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 std::any isUnified =
                     (isEqual(accountMode, std::string("unified")));
                 std::any tradeType = this->handleTradeType(
                     isContract, marginMode, isUnified, params);
                 ::setValue(params, std::string("tradeType"), tradeType);
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startAt"), since);
                 }
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endAt"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("pageSize"), limit);
                 }
                 std::any lowercaseStatus = toLowerCase(status);
                 if (isTrue(isEqual(lowercaseStatus, std::string("open")))) {
                   lowercaseStatus = std::string("active");
                 } else if (isTrue(isEqual(lowercaseStatus,
                                           std::string("closed")))) {
                   lowercaseStatus = std::string("done");
                 }
                 std::any response = std::any{};
                 if (isTrue(isEqual(lowercaseStatus, std::string("active")))) {
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": {
                   //             "pageNumber": 1,
                   //             "pageSize": 50,
                   //             "totalNum": 1,
                   //             "totalPage": 1,
                   //             "items": [
                   //                 {
                   //                     "orderId": "426328635071352832",
                   //                     "symbol": "ETH-USDT",
                   //                     "orderType": "LIMIT",
                   //                     "side": "BUY",
                   //                     "size": "0.001",
                   //                     "price": "1000",
                   //                     "timeInForce": "GTC",
                   //                     "tags": "partner:ccxt",
                   //                     "orderTime": 1774457869404794617,
                   //                     "stp": "",
                   //                     "cancelAfter": null,
                   //                     "postOnly": false,
                   //                     "reduceOnly": false,
                   //                     "triggerDirection": "",
                   //                     "triggerPrice": "",
                   //                     "triggerPriceType": "",
                   //                     "tpTriggerPrice": "",
                   //                     "tpTriggerPriceType": "",
                   //                     "slTriggerPrice": "",
                   //                     "slTriggerPriceType": "",
                   //                     "filledSize": "0",
                   //                     "avgPrice": "0",
                   //                     "fee": "0",
                   //                     "feeCurrency": "USDT",
                   //                     "tax": "0",
                   //                     "updatedTime": 1774457869469028819,
                   //                     "triggerOrderId": "",
                   //                     "cancelReason": "",
                   //                     "cancelSize": "0",
                   //                     "clientOid":
                   //                     "708987d5-c346-487a-a70c-ea267377b0ca",
                   //                     "sizeUnit": "BASECCY",
                   //                     "status": 2
                   //                 }
                   //             ],
                   //             "tradeType": "SPOT"
                   //         }
                   //     }
                   //
                   response =
                       awaitValue(this->utaPrivateGetAccountModeOrderOpenList(
                           this->extend(request, params)));
                 } else {
                   response =
                       awaitValue(this->utaPrivateGetAccountModeOrderHistory(
                           this->extend(request, params)));
                 }
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any orders =
                     this->safeList(data, std::string("items"), ccxt::list{});
                 return this->parseOrders(orders, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchClosedOrders
   * @description fetches information on multiple closed orders made by the user
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-closed-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/spot-trading/orders/get-stop-orders-list
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/get-order-list
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/get-stop-order-list
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-open-orders
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/orders/get-closed-orders
   * @see https://www.kucoin.com/docs-new/rest/ua/get-order-history
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] end time in ms
   * @param {string} [params.side] buy or sell
   * @param {string} [params.type] limit, market, limit_stop or market_stop
   * @param {string} [params.tradeType] TRADE for spot trading, MARGIN_TRADE for
   * Margin Trading
   * @param {bool} [params.trigger] True if fetching a trigger order
   * @param {bool} [params.hf] false, // true for hf order
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{},
                    std::any limit = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any paginate = false;
                        std::any paginateparamsVariable =
                            this->handleOptionAndParams(
                                params, std::string("fetchClosedOrders"),
                                std::string("paginate"));
                        paginate = ::getValue(paginateparamsVariable, 0);
                        params = ::getValue(paginateparamsVariable, 1);
                        if (isTrue(paginate)) {
                          return awaitValue(this->fetchPaginatedCallDynamic(
                              std::string("fetchClosedOrders"), symbol, since,
                              limit, params));
                        }
                        return awaitValue(this->fetchOrdersByStatus(
                            std::string("done"), symbol, since, limit, params));
                      })
        .share();
  }

