  /**
   * @method
   * @name kucoin#fetchLeverage
   * @description fetch the set leverage for a market
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-cross-margin-leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [leverage structure]{@link
   * https://docs.ccxt.com/?id=leverage-structure}
   */
  std::shared_future<std::any>
  fetchLeverage(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                std::any marginMode = std::any{};
                std::any marginModeparamsVariable =
                    this->handleMarginModeAndParams(symbol, params);
                marginMode = ::getValue(marginModeparamsVariable, 0);
                params = ::getValue(marginModeparamsVariable, 1);
                if (isTrue(!isEqual(marginMode, std::string("cross")))) {
                  throw NotSupported(toString(add(
                      this->id,
                      std::string(" fetchLeverage() currently supports only "
                                  "params[\"marginMode\"] = \"cross\""))));
                }
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                if (isTrue(!isEqual(::getValue(market, std::string("contract")),
                                    true))) {
                  throw NotSupported(toString(add(
                      this->id,
                      std::string(
                          " fetchLeverage() supports contract markets only"))));
                }
                std::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                };
                std::any response =
                    awaitValue(this->futuresPrivateGetGetCrossUserLeverage(
                        this->extend(request, params)));
                //
                //    {
                //        "code": "200000",
                //        "data": {
                //            "symbol": "XBTUSDTM",
                //            "leverage": "3"
                //        }
                //    }
                //
                std::any data =
                    this->safeDict(response, std::string("data"), ccxt::dict{});
                std::any parsed = this->parseLeverage(data, market);
                return this->extend(parsed,
                                    ccxt::dict{
                                        {std::string("marginMode"), marginMode},
                                    });
              })
            .share();
  }

  /**
   * @method
   * @name kucoin#setLeverage
   * @description set the level of leverage for a market
   * @see
   * https://www.kucoin.com/docs-new/rest/margin-trading/debit/modify-leverage
   * // margin
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/modify-cross-margin-leverage
   * // contract
   * @see
   * https://www.kucoin.com/docs-new/rest/ua/modify-cross-margin-leverage-uta //
   * margin uta
   * @see https://www.kucoin.com/docs-new/rest/ua/modify-leverage-uta //
   * contract uta
   * @param {int } [leverage] New leverage multiplier. Must be greater than 1
   * and up to two decimal places, and cannot be less than the user's current
   * debt leverage or greater than the system's maximum leverage
   * @param {string} [symbol] unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta)
   * @param {string} [params.marginMode] *spot non-uta only* 'cross' or
   * 'isolated' default is 'cross'
   * @param {string} [params.code] *uta margin only* the unified currency code
   * for the margin to set the leverage for
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setLeverage(std::any leverage, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = std::any{};
                std::any marketType = std::any{};
                std::any marketTypeparamsVariable =
                    this->handleMarketTypeAndParams(std::string("setLeverage"),
                                                    std::any{}, params);
                marketType = ::getValue(marketTypeparamsVariable, 0);
                params = ::getValue(marketTypeparamsVariable, 1);
                if (isTrue(
                        isTrue((!isEqual(symbol, std::any{}))) ||
                        isTrue((isTrue((!isEqual(marketType,
                                                 std::string("spot")))) &&
                                isTrue((!isEqual(marketType,
                                                 std::string("margin")))))))) {
                  if (isTrue(isEqual(symbol, std::any{}))) {
                    throw ArgumentsRequired(toString(
                        add(this->id,
                            std::string(" setLeverage requires a symbol "
                                        "argument for contract markets"))));
                  }
                  market = this->market(symbol);
                  if (isTrue(isEqual(
                          ::getValue(market, std::string("contract")), true))) {
                    return awaitValue(
                        this->setContractLeverage(leverage, symbol, params));
                  }
                }
                std::any request = ccxt::dict{
                    {std::string("leverage"), this->numberToString(leverage)},
                };
                std::any marginMode = std::any{};
                std::any marginModeparamsVariable =
                    this->handleMarginModeAndParams(std::string("setLeverage"),
                                                    params);
                marginMode = ::getValue(marginModeparamsVariable, 0);
                params = ::getValue(marginModeparamsVariable, 1);
                std::any uta = awaitValue(this->isUTAEnabled());
                std::any utaparamsVariable = this->handleOptionAndParams(
                    params, std::string("setLeverage"), std::string("uta"),
                    uta);
                uta = ::getValue(utaparamsVariable, 0);
                params = ::getValue(utaparamsVariable, 1);
                std::any response = ccxt::dict{};
                if (isTrue(uta)) {
                  if (isTrue(isEqual(marginMode, std::string("isolated")))) {
                    throw NotSupported(toString(add(
                        this->id, std::string(" unified trading account does "
                                              "not support isolated margin"))));
                  }
                  ::setValue(request, std::string("accountMode"),
                             std::string("unified"));
                  std::any code = std::any{};
                  std::any codeparamsVariable = this->handleOptionAndParams2(
                      params, std::string("setLeverage"),
                      std::string("currency"), std::string("code"));
                  code = ::getValue(codeparamsVariable, 0);
                  params = ::getValue(codeparamsVariable, 1);
                  if (isTrue(isEqual(code, std::any{}))) {
                    throw ArgumentsRequired(toString(add(
                        this->id,
                        std::string(
                            " setLeverage requires a currency code in the "
                            "params[\"code\"] for unified trading account"))));
                  }
                  ::setValue(request, std::string("currency"),
                             this->currencyId(code));
                  response = awaitValue(
                      this->utaPrivatePostAccountModeAccountModifyLeverageMarginCross(
                          this->extend(request, params)));
                } else {
                  if (isTrue(isEqual(marginMode, std::any{}))) {
                    throw ArgumentsRequired(toString(add(
                        this->id,
                        std::string(
                            " setLeverage requires a marginMode parameter"))));
                  }
                  if (isTrue(isTrue(isEqual(marginMode,
                                            std::string("isolated"))) &&
                             isTrue(isEqual(symbol, std::any{})))) {
                    throw ArgumentsRequired(toString(
                        add(this->id,
                            std::string(" setLeverage requires a symbol "
                                        "parameter for isolated margin"))));
                  }
                  if (isTrue(!isEqual(symbol, std::any{}))) {
                    ::setValue(request, std::string("symbol"),
                               this->safeString(market, std::string("id")));
                  }
                  ::setValue(request, std::string("isIsolated"),
                             (isEqual(marginMode, std::string("isolated"))));
                  response =
                      awaitValue(this->privatePostPositionUpdateUserLeverage(
                          this->extend(request, params)));
                }
                return response;
              })
            .share();
  }

  /**
   * @method
   * @name kucoin#setContractLeverage
   * @description set the level of leverage for a market
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/modify-cross-margin-leverage
   * @see https://www.kucoin.com/docs-new/rest/ua/modify-leverage-uta
   * @param {float} leverage the rate of leverage
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta)
   * @returns {object} response from the exchange
   */
  virtual std::shared_future<std::any>
  setContractLeverage(std::any leverage, std::any symbol = std::any{},
                      std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " setLeverage() requires a symbol argument"))));
                 }
                 std::any marginMode = std::any{};
                 std::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(symbol, params);
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 if (isTrue(isTrue((!isEqual(marginMode, std::any{}))) &&
                            isTrue((
                                !isEqual(marginMode, std::string("cross")))))) {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(" setLeverage() currently supports only "
                                       "params[\"marginMode\"] = \"cross\" for "
                                       "contracts"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("leverage"), toString(leverage)},
                 };
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("setLeverage"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(uta)) {
                   ::setValue(request, std::string("accountMode"),
                              std::string("unified"));
                   response = awaitValue(
                       this->utaPrivatePostAccountModeAccountModifyLeverage(
                           this->extend(request, params)));
                 } else {
                   //
                   //    {
                   //        "code": "200000",
                   //        "data": true
                   //    }
                   //
                   response = awaitValue(
                       this->futuresPrivatePostChangeCrossUserLeverage(
                           this->extend(request, params)));
                 }
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any leverageNum =
                     this->safeNumber(data, std::string("leverage"));
                 return ccxt::dict{
                     {std::string("info"), response},
                     {std::string("symbol"),
                      ::getValue(market, std::string("symbol"))},
                     {std::string("marginMode"), std::any{}},
                     {std::string("longLeverage"), leverageNum},
                     {std::string("shortLeverage"), leverageNum},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchFundingInterval
   * @description fetch the current funding rate interval
   * @see https://www.kucoin.com/docs-new/rest/ua/get-current-funding-rate
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/funding-fees/get-current-funding-rate
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [funding rate structure]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<std::any>
  fetchFundingInterval(std::any symbol,
                       std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        return awaitValue(
                            this->fetchFundingRate(symbol, params));
                      })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchFundingRate
   * @description fetch the current funding rate
   * @see https://www.kucoin.com/docs-new/rest/ua/get-current-funding-rate
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/funding-fees/get-current-funding-rate
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta)
   * @returns {object} a [funding rate structure]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<std::any>
  fetchFundingRate(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any uta = false;
                        std::any utaparamsVariable =
                            this->handleOptionAndParams(
                                params, std::string("fetchFundingRate"),
                                std::string("uta"), uta);
                        uta = ::getValue(utaparamsVariable, 0);
                        params = ::getValue(utaparamsVariable, 1);
                        std::any response = std::any{};
                        if (isTrue(uta)) {
                          //
                          //     {
                          //         "code": "200000",
                          //         "data": {
                          //             "symbol": ".ETHUSDTMFPI8H",
                          //             "nextFundingRate": -3.4E-5,
                          //             "fundingTime": 1776700800000,
                          //             "fundingRateCap": 0.00375,
                          //             "fundingRateFloor": -0.00375,
                          //             "currentGranularity": 28800000,
                          //             "newGranularity": 28800000,
                          //             "newGranularityStartTime":
                          //             1750147200000
                          //         }
                          //     }
                          //
                          response = awaitValue(this->utaGetMarketFundingRate(
                              this->extend(request, params)));
                        } else {
                          //
                          //     {
                          //         "code": "200000",
                          //         "data": {
                          //             "symbol": ".ETHUSDTMFPI8H",
                          //             "granularity": 28800000,
                          //             "timePoint": 1776672000000,
                          //             "value": -3.2E-5,
                          //             "dailyInterestRate": 3.0E-4,
                          //             "fundingRateCap": 0.00375,
                          //             "fundingRateFloor": -0.00375,
                          //             "period": 1,
                          //             "fundingTime": 1776700800000
                          //         }
                          //     }
                          //
                          response = awaitValue(
                              this->futuresPublicGetFundingRateSymbolCurrent(
                                  this->extend(request, params)));
                        }
                        std::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseFundingRate(data, market);
                      })
        .share();
  }

  std::any parseFundingRate(std::any data,
                            std::any market = std::any{}) override {
    // uta
    //     {
    //         "symbol": ".ETHUSDTMFPI8H",
    //         "nextFundingRate": -3.4E-5,
    //         "fundingTime": 1776700800000,
    //         "fundingRateCap": 0.00375,
    //         "fundingRateFloor": -0.00375,
    //         "currentGranularity": 28800000,
    //         "newGranularity": 28800000,
    //         "newGranularityStartTime": 1750147200000
    //     }
    //
    // futures
    //     {
    //         "symbol": ".ETHUSDTMFPI8H",
    //         "granularity": 28800000,
    //         "timePoint": 1776672000000,
    //         "value": -3.2E-5,
    //         "dailyInterestRate": 3.0E-4,
    //         "fundingRateCap": 0.00375,
    //         "fundingRateFloor": -0.00375,
    //         "period": 1,
    //         "fundingTime": 1776700800000
    //     }
    //
    std::any fundingTimestamp =
        this->safeInteger(data, std::string("fundingTime"));
    std::any previousFundingTimestamp =
        this->safeInteger(data, std::string("timePoint"));
    std::any nextFundingTimestamp =
        this->safeInteger(data, std::string("newGranularityStartTime"));
    std::any marketId = this->safeString(data, std::string("symbol"));
    std::any granularity = this->safeString2(data, std::string("granularity"),
                                             std::string("currentGranularity"));
    return ccxt::dict{
        {std::string("info"), data},
        {std::string("symbol"), this->safeSymbol(marketId, market, std::any{},
                                                 std::string("contract"))},
        {std::string("markPrice"), std::any{}},
        {std::string("indexPrice"), std::any{}},
        {std::string("interestRate"),
         this->safeNumber(data, std::string("dailyInterestRate"))},
        {std::string("estimatedSettlePrice"), std::any{}},
        {std::string("timestamp"), std::any{}},
        {std::string("datetime"), std::any{}},
        {std::string("fundingRate"),
         this->safeNumber2(data, std::string("nextFundingRate"),
                           std::string("value"))},
        {std::string("fundingTimestamp"), fundingTimestamp},
        {std::string("fundingDatetime"), this->iso8601(fundingTimestamp)},
        {std::string("nextFundingRate"), std::any{}},
        {std::string("nextFundingTimestamp"), nextFundingTimestamp},
        {std::string("nextFundingDatetime"),
         this->iso8601(nextFundingTimestamp)},
        {std::string("previousFundingRate"), std::any{}},
        {std::string("previousFundingTimestamp"), previousFundingTimestamp},
        {std::string("previousFundingDatetime"),
         this->iso8601(previousFundingTimestamp)},
        {std::string("interval"), this->parseFundingInterval(granularity)},
    };
  }

  virtual std::any parseFundingInterval(std::any interval) {
    std::any intervals = ccxt::dict{
        {std::string("3600000"), std::string("1h")},
        {std::string("14400000"), std::string("4h")},
        {std::string("28800000"), std::string("8h")},
        {std::string("57600000"), std::string("16h")},
        {std::string("86400000"), std::string("24h")},
    };
    return this->safeString(intervals, interval, interval);
  }

  /**
   * @method
   * @name kucoin#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/funding-fees/get-public-funding-history
   * @see https://www.kucoin.com/docs-new/rest/ua/get-history-funding-rate
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for
   * @param {int} [since] not used by kucuoinfutures
   * @param {int} [limit] the maximum amount of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] end time in ms
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to true
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<std::any> fetchFundingRateHistory(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(symbol, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any until =
                     this->safeInteger(params, std::string("until"));
                 std::any uta = false;
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRateHistory"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 params = this->omit(params, std::string("until"));
                 std::any start = since;
                 std::any end = until;
                 if (isTrue(isEqual(since, std::any{}))) {
                   start = 0;
                 }
                 if (isTrue(isEqual(until, std::any{}))) {
                   end = this->milliseconds();
                 }
                 std::any response = std::any{};
                 std::any resultKey = std::string("data");
                 if (isTrue(uta)) {
                   ::setValue(request, std::string("startAt"), start);
                   ::setValue(request, std::string("endAt"), end);
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": {
                   //             "symbol": "XBTUSDTM",
                   //             "list": [
                   //                 {
                   //                     "fundingRate": 7.6E-5,
                   //                     "ts": 1706097600000
                   //                 },
                   //             ]
                   //         }
                   //     }
                   //
                   std::any utaResponse =
                       awaitValue(this->utaGetMarketFundingRateHistory(
                           this->extend(request, params)));
                   response = this->safeDict(utaResponse, std::string("data"),
                                             ccxt::dict{});
                   resultKey = std::string("list");
                 } else {
                   ::setValue(request, std::string("from"), start);
                   ::setValue(request, std::string("to"), end);
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": [
                   //             {
                   //                 "symbol": "IDUSDTM",
                   //                 "fundingRate": 2.26E-4,
                   //                 "timepoint": 1702296000000
                   //             }
                   //         ]
                   //     }
                   //
                   response =
                       awaitValue(this->futuresPublicGetContractFundingRates(
                           this->extend(request, params)));
                 }
                 std::any result =
                     this->safeList(response, resultKey, ccxt::list{});
                 return this->parseFundingRateHistories(result, market, since,
                                                        limit);
               })
        .share();
  }

  std::any parseFundingRateHistory(std::any info,
                                   std::any market = std::any{}) override {
    //
    // uta
    //     {
    //         "fundingRate": 7.6E-5,
    //         "ts": 1706097600000
    //     }
    //
    // futures
    //     {
    //         "symbol": "IDUSDTM",
    //         "fundingRate": 2.26E-4,
    //         "timepoint": 1702296000000
    //     }
    //
    std::any marketId = this->safeString(info, std::string("symbol"));
    std::any timestamp =
        this->safeInteger2(info, std::string("ts"), std::string("timepoint"));
    return ccxt::dict{
        {std::string("info"), info},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("fundingRate"),
         this->safeNumber(info, std::string("fundingRate"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }

  /**
   * @method
   * @name kucoin#fetchFundingHistory
   * @description fetch the history of funding payments paid and received on
   * this account
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/funding-fees/get-private-funding-history
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch funding history for
   * @param {int} [limit] the maximum number of funding history structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object} a [funding history structure]{@link
   * https://docs.ccxt.com/?id=funding-history-structure}
   */
  std::shared_future<std::any>
  fetchFundingHistory(std::any symbol = std::any{}, std::any since = std::any{},
                      std::any limit = std::any{},
                      std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingHistory"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 } else if (!isTrue(uta)) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingHistory() requires "
                                             "a symbol argument"))));
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startAt"), since);
                 }
                 std::any dataList = ccxt::list{};
                 if (isTrue(uta)) {
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("pageSize"), limit);
                   }
                   std::any requestparamsVariable = this->handleUntilOption(
                       std::string("endAt"), request, params);
                   request = ::getValue(requestparamsVariable, 0);
                   params = ::getValue(requestparamsVariable, 1);
                   std::any response =
                       awaitValue(this->utaPrivateGetPositionFundingHistory(
                           this->extend(request, params)));
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": {
                   //             "lastId": 2125247170385112,
                   //             "items": [
                   //                 {
                   //                     "symbol": "DOGEUSDTM",
                   //                     "marginMode": "CROSS",
                   //                     "fundingRate": "0.000172",
                   //                     "markPrice": "0.09326",
                   //                     "size": "-1",
                   //                     "positionValue": "-9.326",
                   //                     "fundingFee": "0.00160407",
                   //                     "settleCurrency": "USDT",
                   //                     "settlementTime": 1775030400000
                   //                 }
                   //             ]
                   //         }
                   //     }
                   std::any data =
                       this->safeDict(response, std::string("data"));
                   dataList =
                       this->safeList(data, std::string("items"), ccxt::list{});
                 } else {
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     // * Since is ignored if limit is defined
                     ::setValue(request, std::string("maxCount"), limit);
                   }
                   std::any response =
                       awaitValue(this->futuresPrivateGetFundingHistory(
                           this->extend(request, params)));
                   //
                   //    {
                   //        "code": "200000",
                   //        "data": {
                   //            "dataList": [
                   //                {
                   //                    "id": 239471298749817,
                   //                    "symbol": "ETHUSDTM",
                   //                    "timePoint": 1638532800000,
                   //                    "fundingRate": 0.000100,
                   //                    "markPrice": 4612.8300000000,
                   //                    "positionQty": 12,
                   //                    "positionCost": 553.5396000000,
                   //                    "funding": -0.0553539600,
                   //                    "settleCurrency": "USDT"
                   //                },
                   //                ...
                   //            ],
                   //            "hasMore": true
                   //        }
                   //    }
                   //
                   std::any data =
                       this->safeValue(response, std::string("data"));
                   dataList = this->safeList(data, std::string("dataList"),
                                             ccxt::list{});
                 }
                 std::any fees = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(dataList));
                      postFixIncrement(i)) {
                   std::any listItem = ::getValue(dataList, i);
                   std::any timestamp =
                       this->safeInteger2(listItem, std::string("timePoint"),
                                          std::string("settlementTime"));
                   std::any marketId =
                       this->safeString(listItem, std::string("symbol"));
                   arrayPush(
                       fees,
                       ccxt::dict{
                           {std::string("info"), listItem},
                           {std::string("symbol"),
                            this->safeSymbol(marketId, market)},
                           {std::string("code"),
                            this->safeCurrencyCode(this->safeString(
                                listItem, std::string("settleCurrency")))},
                           {std::string("timestamp"), timestamp},
                           {std::string("datetime"), this->iso8601(timestamp)},
                           {std::string("id"),
                            this->safeNumber(listItem, std::string("id"))},
                           {std::string("amount"),
                            this->safeNumber2(listItem, std::string("funding"),
                                              std::string("fundingFee"))},
                           {std::string("fundingRate"),
                            this->safeNumber(listItem,
                                             std::string("fundingRate"))},
                           {std::string("markPrice"),
                            this->safeNumber(listItem,
                                             std::string("markPrice"))},
                           {std::string("positionQty"),
                            this->safeNumber2(listItem,
                                              std::string("positionQty"),
                                              std::string("size"))},
                           {std::string("positionCost"),
                            this->safeNumber2(listItem,
                                              std::string("positionCost"),
                                              std::string("positionValue"))},
                       });
                 }
                 return fees;
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchPosition
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-position-details
   * @see https://www.kucoin.com/docs-new/rest/ua/get-position-list-uta
   * @description fetch data on an open position
   * @param {string} symbol unified market symbol of the market the position is
   * held in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {integer} [params.pageSize] *uta only* page size for the uta
   * endpoint (default 50, max 200)
   * @param {integer} [params.pageNumber] *uta only* page number for the uta
   * endpoint (default 1)
   * @returns {object} a [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<std::any>
  fetchPosition(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any uta = awaitValue(this->isUTAEnabled());
                        std::any utaparamsVariable =
                            this->handleOptionAndParams(
                                params, std::string("fetchPosition"),
                                std::string("uta"), uta);
                        uta = ::getValue(utaparamsVariable, 0);
                        params = ::getValue(utaparamsVariable, 1);
                        std::any response = std::any{};
                        std::any position = std::any{};
                        if (isTrue(uta)) {
                          ::setValue(request, std::string("accountMode"),
                                     std::string("unified"));
                          response = awaitValue(
                              this->utaPrivateGetAccountModePositionOpenList(
                                  this->extend(request, params)));
                          //
                          //     {
                          //         "code": "200000",
                          //         "data": [
                          //             {
                          //                 "symbol": "DOGEUSDTM",
                          //                 "id": "30000000000084351",
                          //                 "marginMode": "CROSS",
                          //                 "size": "2",
                          //                 "entryPrice": "0.093795",
                          //                 "positionValue": "18.298",
                          //                 "markPrice": "0.09149",
                          //                 "leverage": "3",
                          //                 "unrealizedPnL": "-0.461",
                          //                 "realizedPnL": "-0.01122489",
                          //                 "initialMargin": "6.0993333327234",
                          //                 "mmr": "0.007",
                          //                 "maintenanceMargin": "0.128086",
                          //                 "creationTime": 1774469753178000000
                          //                 "updateTime": 1774469753178000000
                          //             }
                          //         ]
                          //     }
                          //
                          std::any data = this->safeList(
                              response, std::string("data"), ccxt::list{});
                          position = this->safeDict(data, 0, ccxt::dict{});
                        } else {
                          response = awaitValue(this->futuresPrivateGetPosition(
                              this->extend(request, params)));
                          //
                          //    {
                          //        "code": "200000",
                          //        "data": {
                          //            "id": "6505ee6eaff4070001f651c4",
                          //            "symbol": "XBTUSDTM",
                          //            "autoDeposit": false,
                          //            "maintMarginReq": 0,
                          //            "riskLimit": 200,
                          //            "realLeverage": 0.0,
                          //            "crossMode": false,
                          //            "delevPercentage": 0.0,
                          //            "currentTimestamp": 1694887534594,
                          //            "currentQty": 0,
                          //            "currentCost": 0.0,
                          //            "currentComm": 0.0,
                          //            "unrealisedCost": 0.0,
                          //            "realisedGrossCost": 0.0,
                          //            "realisedCost": 0.0,
                          //            "isOpen": false,
                          //            "markPrice": 26611.71,
                          //            "markValue": 0.0,
                          //            "posCost": 0.0,
                          //            "posCross": 0,
                          //            "posInit": 0.0,
                          //            "posComm": 0.0,
                          //            "posLoss": 0.0,
                          //            "posMargin": 0.0,
                          //            "posMaint": 0.0,
                          //            "maintMargin": 0.0,
                          //            "realisedGrossPnl": 0.0,
                          //            "realisedPnl": 0.0,
                          //            "unrealisedPnl": 0.0,
                          //            "unrealisedPnlPcnt": 0,
                          //            "unrealisedRoePcnt": 0,
                          //            "avgEntryPrice": 0.0,
                          //            "liquidationPrice": 0.0,
                          //            "bankruptPrice": 0.0,
                          //            "settleCurrency": "USDT",
                          //            "maintainMargin": 0,
                          //            "riskLimitLevel": 1
                          //        }
                          //    }
                          //
                          position = this->safeDict(
                              response, std::string("data"), ccxt::dict{});
                        }
                        return this->parsePosition(position, market);
                      })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchPositions
   * @description fetch all open positions
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-position-list
   * @see https://www.kucoin.com/docs-new/rest/ua/get-position-list-uta
   * @param {string[]|undefined} symbols list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @param {integer} [params.pageSize] *uta only* page size for the uta
   * endpoint (default 50, max 200)
   * @param {integer} [params.pageNumber] *uta only* page number for the uta
   * endpoint (default 1)
   * @returns {object[]} a list of [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<std::any>
  fetchPositions(std::any symbols = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchPositions"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 if (isTrue(uta)) {
                   response = awaitValue(
                       this->utaPrivateGetAccountModePositionOpenList(
                           this->extend(
                               ccxt::dict{
                                   {std::string("accountMode"),
                                    std::string("unified")},
                                   {std::string("limit"), 200},
                               },
                               params)));
                 } else {
                   response =
                       awaitValue(this->futuresPrivateGetPositions(params));
                 }
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parsePositions(data, symbols);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchPositionsHistory
   * @description fetches historical positions
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-positions-history
   * @see https://www.kucoin.com/docs-new/rest/ua/get-position-history-uta
   * @param {string[]} [symbols] list of unified market symbols
   * @param {int} [since] the earliest time in ms to fetch position history for
   * @param {int} [limit] the maximum number of entries to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] closing end time
   * @param {int} [params.pageId] page id
   * @param {boolean} [params.uta] set to true for the unified trading account
   * (uta), defaults to false
   * @returns {object[]} a list of [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<std::any> fetchPositionsHistory(
      std::any symbols = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchPositionsHistory"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any response = std::any{};
                 std::any request = ccxt::dict{};
                 symbols = this->marketSymbols(symbols);
                 if (isTrue(!isEqual(symbols, std::any{}))) {
                   std::any length = getArrayLength(symbols);
                   if (isTrue(isEqual(length, 1))) {
                     std::any market = this->market(::getValue(symbols, 0));
                     ::setValue(request, std::string("symbol"),
                                ::getValue(market, std::string("id")));
                   }
                 }
                 if (isTrue(uta)) {
                   if (isTrue(!isEqual(since, std::any{}))) {
                     ::setValue(request, std::string("startAt"), since);
                   }
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("pageSize"), limit);
                   }
                   std::any requestparamsVariable = this->handleUntilOption(
                       std::string("endAt"), request, params);
                   request = ::getValue(requestparamsVariable, 0);
                   params = ::getValue(requestparamsVariable, 1);
                   //
                   //     {
                   //         "code": "200000",
                   //         "data": {
                   //             "items": [
                   //                 {
                   //                     "symbol": "DOGEUSDTM",
                   //                     "closeId": "30000000000162175",
                   //                     "marginMode": "CROSS",
                   //                     "side": "LONG",
                   //                     "entryPrice": "0.09641",
                   //                     "closePrice": "0.09613",
                   //                     "maxSize": "1",
                   //                     "avgClosePrice": "0.09613",
                   //                     "leverage": "3",
                   //                     "realizedPnL": "-0.0395524",
                   //                     "fee": "0.0115524",
                   //                     "tax": "0",
                   //                     "fundingFee": "0",
                   //                     "closingTime": 1774469647311000000,
                   //                     "creationTime": 1774468501294000000
                   //                 }
                   //             ],
                   //             "lastId": 30000000000162175
                   //         }
                   //     }
                   //
                   response = awaitValue(this->utaPrivateGetPositionHistory(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(isEqual(limit, std::any{}))) {
                     limit = 200;
                   }
                   ::setValue(request, std::string("limit"), limit);
                   if (isTrue(!isEqual(since, std::any{}))) {
                     ::setValue(request, std::string("from"), since);
                   }
                   std::any until =
                       this->safeInteger(params, std::string("until"));
                   if (isTrue(!isEqual(until, std::any{}))) {
                     params = this->omit(params, std::string("until"));
                     ::setValue(request, std::string("to"), until);
                   }
                   //
                   // {
                   //     "success": true,
                   //     "code": "200",
                   //     "msg": "success",
                   //     "retry": false,
                   //     "data": {
                   //         "currentPage": 1,
                   //         "pageSize": 10,
                   //         "totalNum": 25,
                   //         "totalPage": 3,
                   //         "items": [
                   //             {
                   //                 "closeId": "300000000000000030",
                   //                 "positionId": "300000000000000009",
                   //                 "uid": 99996908309485,
                   //                 "userId": "6527d4fc8c7f3d0001f40f5f",
                   //                 "symbol": "XBTUSDM",
                   //                 "settleCurrency": "XBT",
                   //                 "leverage": "0.0",
                   //                 "type": "LIQUID_LONG",
                   //                 "side": null,
                   //                 "closeSize": null,
                   //                 "pnl": "-1.0000003793999999",
                   //                 "realisedGrossCost": "0.9993849748999999",
                   //                 "withdrawPnl": "0.0",
                   //                 "roe": null,
                   //                 "tradeFee": "0.0006154045",
                   //                 "fundingFee": "0.0",
                   //                 "openTime": 1713785751181,
                   //                 "closeTime": 1713785752784,
                   //                 "openPrice": null,
                   //                 "closePrice": null
                   //             }
                   //         ]
                   //     }
                   // }
                   //
                   response =
                       awaitValue(this->futuresPrivateGetHistoryPositions(
                           this->extend(request, params)));
                 }
                 std::any data = this->safeDict(response, std::string("data"));
                 std::any items =
                     this->safeList(data, std::string("items"), ccxt::list{});
                 return this->parsePositions(items, symbols);
               })
        .share();
  }

  std::any parsePosition(std::any position,
                         std::any market = std::any{}) override {
    //
    //    {
    //        "code": "200000",
    //        "data": [
    //            {
    //                "id": "615ba79f83a3410001cde321",         // Position ID
    //                "symbol": "ETHUSDTM",                     // Symbol
    //                "autoDeposit": false,                     // Auto deposit
    //                margin or not "maintMarginReq": 0.005,                  //
    //                Maintenance margin requirement "riskLimit": 1000000, //
    //                Risk limit "realLeverage": 25.92,                    //
    //                Leverage of the order "crossMode": false, // Cross mode or
    //                not "delevPercentage": 0.76,                  // ADL
    //                ranking percentile "openingTimestamp": 1638578546031, //
    //                Open time "currentTimestamp": 1638578563580,        //
    //                Current timestamp "currentQty": 2, // Current postion
    //                quantity "currentCost": 83.787,                    //
    //                Current postion value "currentComm": 0.0167574, // Current
    //                commission "unrealisedCost": 83.787,                 //
    //                Unrealised value "realisedGrossCost": 0.0, // Accumulated
    //                realised gross profit value "realisedCost": 0.0167574, //
    //                Current realised position value "isOpen": true, // Opened
    //                position or not "markPrice": 4183.38, // Mark price
    //                "markValue": 83.6676,                     // Mark value
    //                "posCost": 83.787,                        // Position
    //                value "posCross": 0.0,                          // added
    //                margin "posInit": 3.35148,                       //
    //                Leverage margin "posComm": 0.05228309, // Bankruptcy cost
    //                "posLoss": 0.0,                           // Funding fees
    //                paid out "posMargin": 3.40376309,                  //
    //                Position margin "posMaint": 0.50707892, // Maintenance
    //                margin "maintMargin": 3.28436309,                //
    //                Position margin "realisedGrossPnl": 0.0, // Accumulated
    //                realised gross profit value "realisedPnl": -0.0167574, //
    //                Realised profit and loss "unrealisedPnl": -0.1194, //
    //                Unrealised profit and loss "unrealisedPnlPcnt": -0.0014,
    //                // Profit-loss ratio of the position "unrealisedRoePcnt":
    //                -0.0356,             // Rate of return on investment
    //                "avgEntryPrice": 4189.35,                 // Average entry
    //                price "liquidationPrice": 4044.55,              //
    //                Liquidation price "bankruptPrice": 4021.75, // Bankruptcy
    //                price "settleCurrency": "USDT",                 //
    //                Currency used to clear and settle the trades "isInverse":
    //                false
    //            }
    //        ]
    //    }
    // position history
    //             {
    //                 "closeId": "300000000000000030",
    //                 "positionId": "300000000000000009",
    //                 "uid": 99996908309485,
    //                 "userId": "6527d4fc8c7f3d0001f40f5f",
    //                 "symbol": "XBTUSDM",
    //                 "settleCurrency": "XBT",
    //                 "leverage": "0.0",
    //                 "type": "LIQUID_LONG",
    //                 "side": null,
    //                 "closeSize": null,
    //                 "pnl": "-1.0000003793999999",
    //                 "realisedGrossCost": "0.9993849748999999",
    //                 "withdrawPnl": "0.0",
    //                 "roe": null,
    //                 "tradeFee": "0.0006154045",
    //                 "fundingFee": "0.0",
    //                 "openTime": 1713785751181,
    //                 "closeTime": 1713785752784,
    //                 "openPrice": null,
    //                 "closePrice": null
    //             }
    //
    // uta fetchPositions
    //     {
    //         "symbol": "DOGEUSDTM",
    //         "id": "30000000000084351",
    //         "marginMode": "CROSS",
    //         "size": "2",
    //         "entryPrice": "0.093795",
    //         "positionValue": "18.298",
    //         "markPrice": "0.09149",
    //         "leverage": "3",
    //         "unrealizedPnL": "-0.461",
    //         "realizedPnL": "-0.01122489",
    //         "initialMargin": "6.0993333327234",
    //         "mmr": "0.007",
    //         "maintenanceMargin": "0.128086",
    //         "creationTime": 1774469753178000000
    //         "updateTime": 1774469753178000000
    //     }
    //
    // uta fetchPositionsHistory
    //     {
    //         "symbol": "DOGEUSDTM",
    //         "closeId": "30000000000162175",
    //         "marginMode": "CROSS",
    //         "side": "LONG",
    //         "entryPrice": "0.09641",
    //         "closePrice": "0.09613",
    //         "maxSize": "1",
    //         "avgClosePrice": "0.09613",
    //         "leverage": "3",
    //         "realizedPnL": "-0.0395524",
    //         "fee": "0.0115524",
    //         "tax": "0",
    //         "fundingFee": "0",
    //         "closingTime": 1774469647311000000,
    //         "creationTime": 1774468501294000000
    //     }
    //
    std::any symbol = this->safeString(position, std::string("symbol"));
    market = this->safeMarket(symbol, market);
    std::any timestamp =
        this->safeInteger(position, std::string("currentTimestamp"));
    if (isTrue(isEqual(timestamp, std::any{}))) {
      timestamp = this->safeIntegerProduct(
          position, std::string("creationTime"), 0.000001);
    }
    std::any size = this->safeStringN(
        position, ccxt::list{std::string("currentQty"), std::string("size"),
                             std::string("maxSize"), std::string("closeSize")});
    std::any side = this->safeStringLower(position, std::string("side"));
    std::any type = this->safeStringLower(position, std::string("type"));
    if (isTrue(isEqual(side, std::any{}))) {
      if (isTrue(!isEqual(size, std::any{}))) {
        if (isTrue(ccxt::Precise::stringGt(size, std::string("0")))) {
          side = std::string("long");
        } else if (isTrue(ccxt::Precise::stringLt(size, std::string("0")))) {
          side = std::string("short");
        }
      } else if (isTrue(!isEqual(type, std::any{}))) {
        if (isTrue(isGreaterThan(getIndexOf(type, std::string("long")), -1))) {
          side = std::string("long");
        } else {
          side = std::string("short");
        }
      }
    }
    std::any notional = ccxt::Precise::stringAbs(this->safeString2(
        position, std::string("posCost"), std::string("positionValue")));
    std::any initialMargin = this->safeString2(position, std::string("posInit"),
                                               std::string("initialMargin"));
    std::any initialMarginPercentage =
        ccxt::Precise::stringDiv(initialMargin, notional);
    // const marginRatio = ccxt::Precise::stringDiv(maintenanceRate,
    // collateral);
    std::any unrealisedPnl = this->safeString2(
        position, std::string("unrealisedPnl"), std::string("unrealizedPnL"));
    std::any crossMode = this->safeValue(position, std::string("crossMode"));
    // currently crossMode is always set to false and only isolated positions
    // are supported
    std::any marginMode =
        this->safeStringLower(position, std::string("marginMode"));
    if (isTrue(!isEqual(crossMode, std::any{}))) {
      marginMode = (isTrue((isEqual(crossMode, true)))
                        ? std::any(std::string("cross"))
                        : std::any(std::string("isolated")));
    }
    std::any lastUpdateTimestamp =
        this->safeInteger(position, std::string("closeTime"));
    if (isTrue(isEqual(lastUpdateTimestamp, std::any{}))) {
      if (isTrue(inOp(position, std::string("closingTime")))) {
        lastUpdateTimestamp = this->safeIntegerProduct(
            position, std::string("closingTime"), 0.000001);
      } else if (isTrue(inOp(position, std::string("updateTime")))) {
        lastUpdateTimestamp = this->safeIntegerProduct(
            position, std::string("updateTime"), 0.000001);
      }
    }
    return this->safePosition(ccxt::dict{
        {std::string("info"), position},
        {std::string("id"),
         this->safeStringN(position, ccxt::list{std::string("id"),
                                                std::string("positionId"),
                                                std::string("closeId")})},
        {std::string("symbol"),
         this->safeString(market, std::string("symbol"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("lastUpdateTimestamp"), lastUpdateTimestamp},
        {std::string("initialMargin"), this->parseNumber(initialMargin)},
        {std::string("initialMarginPercentage"),
         this->parseNumber(initialMarginPercentage)},
        {std::string("maintenanceMargin"),
         this->safeNumber2(position, std::string("posMaint"),
                           std::string("maintenanceMargin"))},
        {std::string("maintenanceMarginPercentage"),
         this->safeNumber2(position, std::string("maintMarginReq"),
                           std::string("mmr"))},
        {std::string("entryPrice"),
         this->safeNumberN(position, ccxt::list{std::string("avgEntryPrice"),
                                                std::string("openPrice"),
                                                std::string("entryPrice")})},
        {std::string("notional"), this->parseNumber(notional)},
        {std::string("leverage"),
         this->safeNumber2(position, std::string("realLeverage"),
                           std::string("leverage"))},
        {std::string("unrealizedPnl"), this->parseNumber(unrealisedPnl)},
        {std::string("contracts"),
         this->parseNumber(ccxt::Precise::stringAbs(size))},
        {std::string("contractSize"),
         this->safeValue(market, std::string("contractSize"))},
        {std::string("realizedPnl"),
         this->safeNumberN(position, ccxt::list{std::string("realisedPnl"),
                                                std::string("pnl"),
                                                std::string("realizedPnL")})},
        {std::string("marginRatio"), std::any{}},
        {std::string("liquidationPrice"),
         this->safeNumber(position, std::string("liquidationPrice"))},
        {std::string("markPrice"),
         this->safeNumber(position, std::string("markPrice"))},
        {std::string("lastPrice"),
         this->safeNumber(position, std::string("closePrice"))},
        {std::string("collateral"),
         this->safeNumber(position, std::string("maintMargin"))},
        {std::string("marginMode"), marginMode},
        {std::string("side"), side},
        {std::string("percentage"), std::any{}},
        {std::string("stopLossPrice"), std::any{}},
        {std::string("takeProfitPrice"), std::any{}},
    });
  }

  /**
   * @method
   * @name kucoin#cancelOrders
   * @description cancel multiple orders for contract markets
   * @see https://www.kucoin.com/docs-new/3470241e0
   * @see https://www.kucoin.com/docs-new/rest/ua/batch-cancel-order-by-id
   * @param {string[]} ids order ids
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string[]} [params.clientOrderIds] client order ids
   * @param {boolean} [params.uta] set to true to use the unified trading
   * account (uta) endpoint, defaults to false for the contract orders
   * @param {string} [params.accountMode] *for uta endpoint only* 'unified' or
   * 'classic' (default is 'unified')
   * @param {string} [params.marginMode] *for margin orders only* 'cross' or
   * 'isolated' (unified accountMode supports cross margin only)
   * @returns {object} an list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrders(std::any ids, std::any symbol = std::any{},
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any uta = awaitValue(this->isUTAEnabled());
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("cancelOrders"), std::string("uta"),
                     uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 std::any market = std::any{};
                 std::any isContractMarket =
                     true; // default to contract market orders if symbol is not
                           // provided, uta endpoint requires a symbol to be
                           // provided
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   isContractMarket =
                       ::getValue(market, std::string("contract"));
                   if (isTrue(!isEqual(isContractMarket, true))) {
                     uta = true; // spot market orders can only be cancelled via
                                 // the uta endpoint
                   }
                 } else if (isTrue(uta)) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(" cancelOrders() requires a symbol "
                                       "argument for uta endpoint"))));
                 }
                 std::any ordersRequests = ccxt::list{};
                 std::any clientOrderIds =
                     this->safeList2(params, std::string("clientOrderIds"),
                                     std::string("clientOids"), ccxt::list{});
                 params = this->omit(params,
                                     ccxt::list{std::string("clientOrderIds"),
                                                std::string("clientOids")});
                 std::any useClientorderId = false;
                 for (std::any i = 0;
                      isLessThan(i, getArrayLength(clientOrderIds));
                      postFixIncrement(i)) {
                   useClientorderId = true;
                   if (isTrue(isEqual(symbol, std::any{}))) {
                     throw ArgumentsRequired(toString(
                         add(this->id,
                             std::string(
                                 " cancelOrders() requires a symbol argument "
                                 "when cancelling by clientOrderIds"))));
                   }
                   arrayPush(ordersRequests,
                             ccxt::dict{
                                 {std::string("symbol"),
                                  this->safeString(market, std::string("id"))},
                                 {std::string("clientOid"),
                                  this->safeString(clientOrderIds, i)},
                             });
                 }
                 for (std::any i = 0; isLessThan(i, getArrayLength(ids));
                      postFixIncrement(i)) {
                   std::any orderId = ::getValue(ids, i);
                   if (isTrue(uta)) {
                     arrayPush(
                         ordersRequests,
                         ccxt::dict{
                             {std::string("orderId"), orderId},
                             {std::string("symbol"),
                              this->safeString(market, std::string("id"))},
                         });
                   } else {
                     arrayPush(ordersRequests, ::getValue(ids, i));
                   }
                 }
                 std::any request = ccxt::dict{};
                 std::any response = std::any{};
                 std::any orders = ccxt::list{};
                 if (isTrue(uta)) {
                   std::any accountMode = std::string("unified");
                   std::any accountModeparamsVariable =
                       this->handleOptionAndParams(
                           params, std::string("cancelOrders"),
                           std::string("accountMode"), accountMode);
                   accountMode = ::getValue(accountModeparamsVariable, 0);
                   params = ::getValue(accountModeparamsVariable, 1);
                   ::setValue(request, std::string("accountMode"), accountMode);
                   std::any marginMode = std::any{};
                   std::any marginModeparamsVariable =
                       this->handleMarginModeAndParams(
                           std::string("cancelOrders"), params);
                   marginMode = ::getValue(marginModeparamsVariable, 0);
                   params = ::getValue(marginModeparamsVariable, 1);
                   std::any isUnified =
                       (isEqual(accountMode, std::string("unified")));
                   std::any tradeType = this->handleTradeType(
                       isContractMarket, marginMode, isUnified, params);
                   ::setValue(request, std::string("tradeType"), tradeType);
                   ::setValue(request, std::string("cancelOrderList"),
                              ordersRequests);
                   response = awaitValue(
                       this->utaPrivatePostAccountModeOrderCancelBatch(
                           this->extend(request, params)));
                   std::any data = this->safeDict(response, std::string("data"),
                                                  ccxt::dict{});
                   orders =
                       this->safeList(data, std::string("items"), ccxt::list{});
                 } else {
                   std::any requestKey =
                       (isTrue(useClientorderId)
                            ? std::any(std::string("clientOidsList"))
                            : std::any(std::string("orderIdsList")));
                   ::setValue(request, requestKey, ordersRequests);
                   response =
                       awaitValue(this->futuresPrivateDeleteOrdersMultiCancel(
                           this->extend(request, params)));
                   //
                   //   {
                   //       "code": "200000",
                   //       "data":
                   //       [
                   //           {
                   //               "orderId": "80465574458560512",
                   //               "clientOid": null,
                   //               "code": "200",
                   //               "msg": "success"
                   //           },
                   //           {
                   //               "orderId": "80465575289094144",
                   //               "clientOid": null,
                   //               "code": "200",
                   //               "msg": "success"
                   //           }
                   //       ]
                   //   }
                   //
                   orders = this->safeList(response, std::string("data"),
                                           ccxt::list{});
                 }
                 return this->parseOrders(orders, market);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#addMargin
   * @description add margin
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/add-isolated-margin
   * @param {string} symbol unified market symbol
   * @param {float} amount amount of margin to add
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.positionSide] *required for hedged position*
   * 'BOTH', 'LONG' or 'SHORT' (default is 'BOTH')
   * @returns {object} a [margin structure]{@link
   * https://docs.ccxt.com/?id=margin-structure}
   */
  std::shared_future<std::any>
  addMargin(std::any symbol, std::any amount,
            std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any uuid = this->uuid();
                        std::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                            {std::string("margin"),
                             this->amountToPrecision(symbol, amount)},
                            {std::string("bizNo"), uuid},
                        };
                        std::any response = awaitValue(
                            this->futuresPrivatePostPositionMarginDepositMargin(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "code": "200000",
                        //        "data": {
                        //            "id": "62311d26064e8f00013f2c6d",
                        //            "symbol": "XRPUSDTM",
                        //            "autoDeposit": false,
                        //            "maintMarginReq": 0.01,
                        //            "riskLimit": 200000,
                        //            "realLeverage": 0.88,
                        //            "crossMode": false,
                        //            "delevPercentage": 0.4,
                        //            "openingTimestamp": 1647385894798,
                        //            "currentTimestamp": 1647414510672,
                        //            "currentQty": -1,
                        //            "currentCost": -7.658,
                        //            "currentComm": 0.0053561,
                        //            "unrealisedCost": -7.658,
                        //            "realisedGrossCost": 0,
                        //            "realisedCost": 0.0053561,
                        //            "isOpen": true,
                        //            "markPrice": 0.7635,
                        //            "markValue": -7.635,
                        //            "posCost": -7.658,
                        //            "posCross": 1.00016084,
                        //            "posInit": 7.658,
                        //            "posComm": 0.00979006,
                        //            "posLoss": 0,
                        //            "posMargin": 8.6679509,
                        //            "posMaint": 0.08637006,
                        //            "maintMargin": 8.6909509,
                        //            "realisedGrossPnl": 0,
                        //            "realisedPnl": -0.0038335,
                        //            "unrealisedPnl": 0.023,
                        //            "unrealisedPnlPcnt": 0.003,
                        //            "unrealisedRoePcnt": 0.003,
                        //            "avgEntryPrice": 0.7658,
                        //            "liquidationPrice": 1.6239,
                        //            "bankruptPrice": 1.6317,
                        //            "settleCurrency": "USDT"
                        //        }
                        //    }
                        //
                        //
                        //    {
                        //        "code":"200000",
                        //        "msg":"Position does not exist"
                        //    }
                        //
                        std::any data =
                            this->safeValue(response, std::string("data"));
                        return this->extend(
                            this->parseMarginModification(data, market),
                            ccxt::dict{
                                {std::string("amount"),
                                 this->amountToPrecision(symbol, amount)},
                                {std::string("direction"), std::string("in")},
                            });
                      })
        .share();
  }

  /**
   * @method
   * @name kucoin#reduceMargin
   * @description remove margin from a position
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/remove-isolated-margin
   * @param {string} symbol unified market symbol
   * @param {float} amount the amount of margin to remove
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.positionSide] *required for hedged position*
   * 'BOTH', 'LONG' or 'SHORT' (default is 'BOTH')
   * @returns {object} a [margin structure]{@link
   * https://docs.ccxt.com/?id=margin-structure}
   */
  std::shared_future<std::any>
  reduceMargin(std::any symbol, std::any amount,
               std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any amountString =
                     this->amountToPrecision(symbol, amount);
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("withdrawAmount"), amountString},
                 };
                 std::any response =
                     awaitValue(this->futuresPrivatePostMarginWithdrawMargin(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": "0.1"
                 //     }
                 //
                 std::any currencyId =
                     this->safeString(market, std::string("settle"));
                 std::any responseCode =
                     this->safeString(response, std::string("code"));
                 return ccxt::dict{
                     {std::string("info"), response},
                     {std::string("symbol"),
                      ::getValue(market, std::string("symbol"))},
                     {std::string("type"), std::string("reduce")},
                     {std::string("marginMode"), std::string("isolated")},
                     {std::string("amount"), this->parseNumber(amountString)},
                     {std::string("total"), std::any{}},
                     {std::string("code"), this->safeCurrencyCode(currencyId)},
                     {std::string("status"),
                      (isTrue((isEqual(responseCode, std::string("200000"))))
                           ? std::any(std::string("ok"))
                           : std::any(std::any{}))},
                     {std::string("timestamp"), std::any{}},
                     {std::string("datetime"), std::any{}},
                 };
               })
        .share();
  }

  std::any parseMarginModification(std::any info,
                                   std::any market = std::any{}) override {
    //
    //    {
    //        "id": "62311d26064e8f00013f2c6d",
    //        "symbol": "XRPUSDTM",
    //        "autoDeposit": false,
    //        "maintMarginReq": 0.01,
    //        "riskLimit": 200000,
    //        "realLeverage": 0.88,
    //        "crossMode": false,
    //        "delevPercentage": 0.4,
    //        "openingTimestamp": 1647385894798,
    //        "currentTimestamp": 1647414510672,
    //        "currentQty": -1,
    //        "currentCost": -7.658,
    //        "currentComm": 0.0053561,
    //        "unrealisedCost": -7.658,
    //        "realisedGrossCost": 0,
    //        "realisedCost": 0.0053561,
    //        "isOpen": true,
    //        "markPrice": 0.7635,
    //        "markValue": -7.635,
    //        "posCost": -7.658,
    //        "posCross": 1.00016084,
    //        "posInit": 7.658,
    //        "posComm": 0.00979006,
    //        "posLoss": 0,
    //        "posMargin": 8.6679509,
    //        "posMaint": 0.08637006,
    //        "maintMargin": 8.6909509,
    //        "realisedGrossPnl": 0,
    //        "realisedPnl": -0.0038335,
    //        "unrealisedPnl": 0.023,
    //        "unrealisedPnlPcnt": 0.003,
    //        "unrealisedRoePcnt": 0.003,
    //        "avgEntryPrice": 0.7658,
    //        "liquidationPrice": 1.6239,
    //        "bankruptPrice": 1.6317,
    //        "settleCurrency": "USDT"
    //    }
    //
    //    {
    //        "code":"200000",
    //        "msg":"Position does not exist"
    //    }
    //
    std::any id = this->safeString(info, std::string("id"));
    market = this->safeMarket(id, market);
    std::any currencyId = this->safeString(info, std::string("settleCurrency"));
    std::any crossMode = this->safeValue(info, std::string("crossMode"));
    std::any mode = (isTrue((isEqual(crossMode, true)))
                         ? std::any(std::string("cross"))
                         : std::any(std::string("isolated")));
    std::any marketId = this->safeString(market, std::string("symbol"));
    std::any timestamp =
        this->safeInteger(info, std::string("currentTimestamp"));
    return ccxt::dict{
        {std::string("info"), info},
        {std::string("symbol"), this->safeSymbol(marketId, market)},
        {std::string("type"), std::any{}},
        {std::string("marginMode"), mode},
        {std::string("amount"), std::any{}},
        {std::string("total"), std::any{}},
        {std::string("code"), this->safeCurrencyCode(currencyId)},
        {std::string("status"), std::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }

  /**
   * @method
   * @name kucoin#fetchMarginMode
   * @description fetches the margin mode of a trading pair
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-margin-mode
   * @param {string} symbol unified symbol of the market to fetch the margin
   * mode for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [margin mode structure]{@link
   * https://docs.ccxt.com/?id=margin-mode-structure}
   */
  std::shared_future<std::any>
  fetchMarginMode(std::any symbol, std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any market = this->market(symbol);
                        std::any request = ccxt::dict{
                            {std::string("symbol"),
                             ::getValue(market, std::string("id"))},
                        };
                        std::any response = awaitValue(
                            this->futuresPrivateGetPositionGetMarginMode(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": "200000",
                        //         "data": {
                        //             "symbol": "XBTUSDTM",
                        //             "marginMode": "ISOLATED"
                        //         }
                        //     }
                        //
                        std::any data = this->safeDict(
                            response, std::string("data"), ccxt::dict{});
                        return this->parseMarginMode(data, market);
                      })
        .share();
  }

  std::any parseMarginMode(std::any marginMode,
                           std::any market = std::any{}) override {
    std::any marginType =
        this->safeString(marginMode, std::string("marginMode"));
    marginType = (isTrue((isEqual(marginType, std::string("ISOLATED"))))
                      ? std::any(std::string("isolated"))
                      : std::any(std::string("cross")));
    return ccxt::dict{
        {std::string("info"), marginMode},
        {std::string("symbol"),
         this->safeString(market, std::string("symbol"))},
        {std::string("marginMode"), marginType},
    };
  }

  /**
   * @method
   * @name kucoin#setMarginMode
   * @description set margin mode to 'cross' or 'isolated'
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/switch-margin-mode
   * @param {string} marginMode 'cross' or 'isolated'
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} response from the exchange
   */
  std::shared_future<std::any>
  setMarginMode(std::any marginMode, std::any symbol = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(symbol, std::any{}))) {
                  throw ArgumentsRequired(toString(
                      add(this->id,
                          std::string(
                              " setMarginMode() requires a symbol argument"))));
                }
                this->checkRequiredArgument(
                    std::string("setMarginMode"), marginMode,
                    std::string("marginMode"),
                    ccxt::list{std::string("cross"), std::string("isolated")});
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                if (isTrue(!isEqual(::getValue(market, std::string("contract")),
                                    true))) {
                  throw NotSupported(toString(add(
                      this->id,
                      std::string(
                          " setMarginMode() supports contract markets only"))));
                }
                std::any request = ccxt::dict{
                    {std::string("symbol"),
                     ::getValue(market, std::string("id"))},
                    {std::string("marginMode"), toUpperCase(marginMode)},
                };
                std::any response =
                    awaitValue(this->futuresPrivatePostPositionChangeMarginMode(
                        this->extend(request, params)));
                //
                //    {
                //        "code": "200000",
                //        "data": {
                //            "symbol": "XBTUSDTM",
                //            "marginMode": "ISOLATED"
                //        }
                //    }
                //
                std::any data =
                    this->safeDict(response, std::string("data"), ccxt::dict{});
                return this->parseMarginMode(
                    data,
                    market); // widened to Dict to match the base setMarginMode
                             // return ({}) — narrowing it to MarginMode breaks
                             // the Go IExchange interface
              })
            .share();
  }

  /**
   * @method
   * @name kucoin#setPositionMode
   * @description set hedged to true or false for a market
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/switch-position-mode
   * @param {bool} hedged set to true to use two way position
   * @param {string} [symbol] not used by setPositionMode ()
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a response from the exchange
   */
  std::shared_future<std::any>
  setPositionMode(std::any hedged, std::any symbol = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any posMode =
                            (isTrue(hedged) ? std::any(std::string("1"))
                                            : std::any(std::string("0")));
                        std::any request = ccxt::dict{
                            {std::string("positionMode"), posMode},
                        };
                        std::any response = awaitValue(
                            this->futuresPrivatePostPositionSwitchPositionMode(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": "200000",
                        //         "data": {
                        //             "positionMode": 1
                        //         }
                        //     }
                        //
                        return response;
                      })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchPositionMode
   * @description fetchs the position mode, hedged or one way
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-position-mode
   * @param {string} [symbol] unified symbol of the market to fetch the position
   * mode for (not used in blofin fetchPositionMode)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an object detailing whether the market is in hedged or
   * one-way mode
   */
  std::shared_future<std::any>
  fetchPositionMode(std::any symbol = std::any{},
                    std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any response = awaitValue(
                     this->futuresPrivateGetPositionGetPositionMode(params));
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any positionMode =
                     this->safeInteger(data, std::string("positionMode"));
                 return ccxt::dict{
                     {std::string("info"), data},
                     {std::string("hedged"), isEqual(positionMode, 1)},
                 };
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#closePosition
   * @description closes open positions for a market
   * @see https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/orders/add-order-test
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} side not used by kucoin closePositions
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.clientOrderId] client order id of the order
   * @returns {object[]} [A list of position structures]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<std::any>
  closePosition(std::any symbol, std::any side = std::any{},
                std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any clientOrderId =
                     this->safeString(params, std::string("clientOrderId"));
                 std::any testOrder =
                     this->safeBool(params, std::string("test"), false);
                 params = this->omit(params,
                                     ccxt::list{std::string("test"),
                                                std::string("clientOrderId")});
                 if (isTrue(isEqual(clientOrderId, std::any{}))) {
                   clientOrderId = this->numberToString(this->nonce());
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("closeOrder"), true},
                     {std::string("clientOid"), clientOrderId},
                     {std::string("type"), std::string("market")},
                 };
                 std::any response = std::any{};
                 if (isTrue(isEqual(testOrder, true))) {
                   response = awaitValue(this->futuresPrivatePostOrdersTest(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->futuresPrivatePostOrders(
                       this->extend(request, params)));
                 }
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchMarketLeverageTiers
   * @description retrieve information on the maximum leverage, and maintenance
   * margin for trades of varying trade sizes for a single market
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-isolated-margin-risk-limit
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.uta] set to true to fetch leverage tiers for
   * unified trading account instead of futures account (default is false)
   * @returns {object} a [leverage tiers structure]{@link
   * https://docs.ccxt.com/?id=leverage-tiers-structure}
   */
  std::shared_future<std::any>
  fetchMarketLeverageTiers(std::any symbol,
                           std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 if (isTrue(!isEqual(
                         ::getValue(market, std::string("contract")), true))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(" fetchMarketLeverageTiers() supports "
                                       "contract markets only"))));
                 }
                 std::any uta = false;
                 std::any utaparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMarketLeverageTiers"),
                     std::string("uta"), uta);
                 uta = ::getValue(utaparamsVariable, 0);
                 params = ::getValue(utaparamsVariable, 1);
                 if (isTrue(uta)) {
                   std::any result = awaitValue(
                       this->fetchLeverageTiers(ccxt::list{symbol}, params));
                   return this->safeList(result, symbol, ccxt::list{});
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 std::any response =
                     awaitValue(this->futuresPublicGetContractsRiskLimitSymbol(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "code": "200000",
                 //        "data": [
                 //            {
                 //                "symbol": "ETHUSDTM",
                 //                "level": 1,
                 //                "maxRiskLimit": 300000,
                 //                "minRiskLimit": 0,
                 //                "maxLeverage": 100,
                 //                "initialMargin": 0.0100000000,
                 //                "maintainMargin": 0.0050000000
                 //            },
                 //            ...
                 //        ]
                 //    }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 return this->parseMarketLeverageTiers(data, market);
               })
        .share();
  }

  std::any parseMarketLeverageTiers(std::any info,
                                    std::any market = std::any{}) override {
    /**
     * @ignore
     * @method
     * @name kucoin#parseMarketLeverageTiers
     * @param {object} info Exchange market response for 1 market
     * @param {object} market CCXT market
     */
    //
    // futures
    //    {
    //        "symbol": "ETHUSDTM",
    //        "level": 1,
    //        "maxRiskLimit": 300000,
    //        "minRiskLimit": 0,
    //        "maxLeverage": 100,
    //        "initialMargin": 0.0100000000,
    //        "maintainMargin": 0.0050000000
    //    }
    //
    // uta
    //     {
    //         "symbol": "XBTUSDTM",
    //         "tier": 2,
    //         "maxSize": "600000",
    //         "minSize": "250000",
    //         "maxLeverage": "100",
    //         "initialMarginRate": "0.0100000000",
    //         "maintainMarginRate": "0.0050000000"
    //     }
    //
    std::any tiers = ccxt::list{};
    for (std::any i = 0; isLessThan(i, getArrayLength(info));
         postFixIncrement(i)) {
      std::any tier = this->safeDict(info, i, ccxt::dict{});
      std::any marketId = this->safeString(tier, std::string("symbol"));
      market = this->safeMarket(marketId, market);
      arrayPush(tiers,
                ccxt::dict{
                    {std::string("tier"),
                     this->safeNumber2(tier, std::string("level"),
                                       std::string("tier"))},
                    {std::string("symbol"),
                     ::getValue(market, std::string("symbol"))},
                    {std::string("currency"),
                     ::getValue(market, std::string("base"))},
                    {std::string("minNotional"),
                     this->safeNumber2(tier, std::string("minRiskLimit"),
                                       std::string("minSize"))},
                    {std::string("maxNotional"),
                     this->safeNumber2(tier, std::string("maxRiskLimit"),
                                       std::string("maxSize"))},
                    {std::string("maintenanceMarginRate"),
                     this->safeNumber2(tier, std::string("maintainMargin"),
                                       std::string("maintainMarginRate"))},
                    {std::string("maxLeverage"),
                     this->safeNumber(tier, std::string("maxLeverage"))},
                    {std::string("info"), tier},
                });
    }
    return tiers;
  }

  /**
   * @method
   * @name kucoin#fetchLeverageTiers
   * @description retrieve information on the maximum leverage, and maintenance
   * margin for trades of varying trade sizes
   * @see https://www.kucoin.com/docs-new/rest/ua/get-position-tiers
   * @param {string[]} symbols list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [leverage tiers structures]{@link
   * https://docs.ccxt.com/?id=leverage-tiers-structure}, indexed by market
   * symbols
   */
  std::shared_future<std::any>
  fetchLeverageTiers(std::any symbols = std::any{},
                     std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 if (isTrue(isEqual(symbols, std::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchLeverageTiers() requires a "
                                             "symbols argument"))));
                 }
                 symbols = this->marketSymbols(symbols, std::string("swap"),
                                               false, true);
                 std::any marginMode = std::string("cross");
                 std::any marginModeparamsVariable =
                     this->handleMarginModeAndParams(
                         std::string("fetchLeverageTiers"), params, marginMode);
                 marginMode = ::getValue(marginModeparamsVariable, 0);
                 params = ::getValue(marginModeparamsVariable, 1);
                 marginMode = toUpperCase(marginMode);
                 if (isTrue(!isEqual(marginMode, std::string("CROSS")))) {
                   throw BadRequest(toString(add(
                       this->id, std::string(" fetchLeverageTiers() supports "
                                             "cross margin only"))));
                 }
                 std::any marketIds = this->marketIds(symbols);
                 std::any request = ccxt::dict{
                     {std::string("tradeType"), std::string("FUTURES")},
                     {std::string("marginMode"), marginMode},
                     {std::string("data"), std::string("RISK_LIMIT")},
                     {std::string("accountType"), std::string("UNIFIED")},
                     {std::string("symbol"), join(marketIds, std::string(","))},
                 };
                 std::any response = awaitValue(this->utaGetMarketPositionTiers(
                     this->extend(request, params)));
                 //
                 //     {
                 //         "code": "200000",
                 //         "data": [
                 //             {
                 //                 "symbol": "XBTUSDTM",
                 //                 "tier": 1,
                 //                 "maxSize": "250000",
                 //                 "minSize": "0",
                 //                 "maxLeverage": "125",
                 //                 "initialMarginRate": "0.0080000000",
                 //                 "maintainMarginRate": "0.0040000000"
                 //             },
                 //             {
                 //                 "symbol": "XBTUSDTM",
                 //                 "tier": 2,
                 //                 "maxSize": "600000",
                 //                 "minSize": "250000",
                 //                 "maxLeverage": "100",
                 //                 "initialMarginRate": "0.0100000000",
                 //                 "maintainMarginRate": "0.0050000000"
                 //             }
                 //         ]
                 //     }
                 //
                 std::any data = this->safeList(response, std::string("data"),
                                                ccxt::list{});
                 std::any result = ccxt::dict{};
                 std::any tiers = this->parseMarketLeverageTiers(data);
                 for (std::any i = 0; isLessThan(i, getArrayLength(tiers));
                      postFixIncrement(i)) {
                   std::any tier = this->safeDict(tiers, i);
                   std::any symbol =
                       this->safeString(tier, std::string("symbol"));
                   if (isTrue(!isEqual(symbol, std::any{}))) {
                     if (!isTrue((inOp(result, symbol)))) {
                       ::setValue(result, symbol, ccxt::list{});
                     }
                     arrayPush(::getValue(result, symbol), tier);
                   }
                 }
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchOpenInterests
   * @description Retrieves the open interest for a list of symbols
   * @see https://www.kucoin.com/docs-new/rest/ua/get-futures-open-interset
   * @param {string[]} [symbols] Unified CCXT market symbol
   * @param {object} [params] exchange specific parameters
   * @returns {object} an open interest structure{@link
   * https://docs.ccxt.com/?id=open-interest-structure}
   */
  std::shared_future<std::any>
  fetchOpenInterests(std::any symbols = std::any{},
                     std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        symbols = this->marketSymbols(symbols);
                        std::any request = ccxt::dict{};
                        if (isTrue(!isEqual(symbols, std::any{}))) {
                          std::any length = getArrayLength(symbols);
                          if (isTrue(isLessThan(length, 11))) {
                            // the endpoint does not accept more than 10 symbols
                            // at a time if user provided more than 10 symbols,
                            // we will fetch all symbols
                            std::any marketIds = this->marketIds(symbols);
                            ::setValue(request, std::string("symbol"),
                                       join(marketIds, std::string(",")));
                          }
                        }
                        std::any response =
                            awaitValue(this->utaGetMarketOpenInterest(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "code": "200000",
                        //         "data": [
                        //             {
                        //                 "symbol": "ETHUSDTM",
                        //                 "openInterest": "8053960",
                        //                 "ts": 1774007467050
                        //             }
                        //         ]
                        //     }
                        //
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseOpenInterests(data, symbols);
                      })
        .share();
  }

  std::any parseOpenInterest(std::any interest,
                             std::any market = std::any{}) override {
    //
    //     {
    //         "symbol": "ETHUSDTM",
    //         "openInterest": "8053960",
    //         "ts": 1774007467050
    //     }
    //
    std::any marketId = this->safeString(interest, std::string("symbol"));
    market = this->safeMarket(marketId, market);
    std::any timestamp = this->safeInteger(interest, std::string("ts"));
    return this->safeOpenInterest(
        ccxt::dict{
            {std::string("symbol"), this->safeSymbol(marketId)},
            {std::string("openInterestAmount"),
             this->safeNumber(interest, std::string("openInterest"))},
            {std::string("openInterestValue"), std::any{}},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("info"), interest},
        },
        market);
  }

  /**
   * @method
   * @name kucoin#fetchOpenInterestHistory
   * @description Retrieves the open interest history of a currency
   * @see https://www.kucoin.com/docs-new/rest/ua/get-futures-open-interset
   * @param {string} symbol Unified CCXT market symbol
   * @param {string} timeframe '5m', '15m', '30m', '1h', '4h' or '1d'
   * @param {int} [since] the time(ms) of the earliest record to retrieve as a
   * unix timestamp
   * @param {int} [limit] default 30，max 200
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object} an array of [open interest structures]{@link
   * https://docs.ccxt.com/?id=open-interest-structure}
   */
  std::shared_future<std::any> fetchOpenInterestHistory(
      std::any symbol, std::any timeframe = std::string("5m"),
      std::any since = std::any{}, std::any limit = std::any{},
      std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any timeframes = ccxt::dict{
                     {std::string("5m"), std::string("5min")},
                     {std::string("15m"), std::string("15min")},
                     {std::string("30m"), std::string("30min")},
                     {std::string("1h"), std::string("1hour")},
                     {std::string("4h"), std::string("4hour")},
                     {std::string("1d"), std::string("1day")},
                     {std::string("5min"), std::string("5min")},
                     {std::string("15min"), std::string("15min")},
                     {std::string("30min"), std::string("30min")},
                     {std::string("1hour"), std::string("1hour")},
                     {std::string("4hour"), std::string("4hour")},
                     {std::string("1day"), std::string("1day")},
                 };
                 std::any interval = this->safeString(timeframes, timeframe);
                 if (isTrue(isEqual(interval, std::any{}))) {
                   throw BadRequest(toString(
                       add(this->id,
                           std::string(
                               " fetchOpenInterestHistory() invalid timeframe, "
                               "supported are 5m, 15m, 30m, 1h, 4h, 1d"))));
                 }
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = this->market(symbol);
                 std::any maxLimit = 200;
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOpenInterestHistory"),
                     std::string("paginate"), paginate);
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOpenInterestHistory"), symbol, since,
                       limit, timeframe, params, maxLimit));
                 }
                 std::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("interval"), interval},
                 };
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startAt"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("pageSize"), limit);
                 }
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endAt"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 std::any response = awaitValue(this->utaGetMarketOpenInterest(
                     this->extend(request, params)));
                 std::any data = this->safeList(response, std::string("data"));
                 return this->parseOpenInterestsHistory(data, market, since,
                                                        limit);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#isUTAEnabled
   * @see https://www.kucoin.com/docs-new/rest/ua/get-account-mode
   * @description returns true or false so the user can check if unified account
   * is enabled
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {boolean} true if unified account is enabled, false otherwise
   */
  std::shared_future<std::any>
  isUTAEnabled(std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any uta =
                     this->safeBool(this->options, std::string("uta"));
                 if (isTrue(isEqual(uta, std::any{}))) {
                   std::any response =
                       awaitValue(this->utaPrivateGetAccountMode(params));
                   std::any data = this->safeDict(response, std::string("data"),
                                                  ccxt::dict{});
                   std::any accountMode =
                       this->safeString(data, std::string("selfAccountMode"));
                   uta = (isEqual(accountMode, std::string("UNIFIED")));
                   ::setValue(this->options, std::string("uta"), uta);
                 }
                 return uta;
               })
        .share();
  }

  std::any sign(std::any path, std::any api = std::string("public"),
                std::any method = std::string("GET"),
                std::any params = ccxt::dict{}, std::any headers = std::any{},
                std::any body = std::any{}) override {
    //
    // the v2 URL is https://openapi-v2.kucoin.com/api/v1/endpoint
    //                                ↑                 ↑
    //                                ↑                 ↑
    //
    std::any versions =
        this->safeDict(this->options, std::string("versions"), ccxt::dict{});
    std::any apiVersions = this->safeDict(versions, api, ccxt::dict{});
    std::any methodVersions = this->safeDict(apiVersions, method, ccxt::dict{});
    std::any defaultVersion =
        this->safeString(methodVersions, path,
                         ::getValue(this->options, std::string("version")));
    std::any version =
        this->safeString(params, std::string("version"), defaultVersion);
    params = this->omit(params, std::string("version"));
    std::any endpoint =
        add(add(add(std::string("/api/"), version), std::string("/")),
            this->implodeParams(path, params));
    if (isTrue(isEqual(api, std::string("webExchange")))) {
      endpoint = add(std::string("/"), this->implodeParams(path, params));
    }
    if (isTrue(isEqual(api, std::string("earn")))) {
      endpoint =
          add(std::string("/api/v1/"), this->implodeParams(path, params));
    }
    std::any isUtaPrivate = false;
    if (isTrue(isTrue((isEqual(api, std::string("uta")))) ||
               isTrue((isEqual(api, std::string("utaPrivate")))))) {
      endpoint =
          add(std::string("/api/ua/v1/"), this->implodeParams(path, params));
      if (isTrue(isEqual(api, std::string("utaPrivate")))) {
        isUtaPrivate = true;
      }
    }
    std::any query = this->omit(params, this->extractParams(path));
    std::any endpart = std::string("");
    headers =
        (isTrue((!isEqual(headers, std::any{}))) ? std::any(headers)
                                                 : std::any(ccxt::dict{}));
    std::any url = ::getValue(::getValue(this->urls, std::string("api")), api);
    std::any tradeType = this->safeString(query, std::string("tradeType"));
    if (!isTrue(this->isEmpty(query))) {
      if (isTrue(
              isTrue((isTrue((isEqual(method, std::string("GET")))) ||
                      isTrue((isEqual(method, std::string("DELETE")))))) &&
              isTrue((!isEqual(path, std::string("orders/multi-cancel")))))) {
        endpoint = add(endpoint, add(std::string("?"), this->rawencode(query)));
      } else {
        if (isTrue(
                isTrue(
                    isTrue(
                        isTrue((isEqual(
                            endpoint,
                            std::string("/api/ua/v1/classic/order/place")))) ||
                        isTrue((isEqual(
                            endpoint,
                            std::string(
                                "/api/ua/v1/classic/order/place/batch"))))) ||
                    isTrue((isEqual(
                        endpoint,
                        std::string("/api/ua/v1/classic/order/cancel"))))) ||
                isTrue((isEqual(
                    endpoint,
                    std::string("/api/ua/v1/classic/order/cancel/batch")))))) {
          endpoint = add(endpoint, add(std::string("?tradeType="), tradeType));
        }
        body = this->json(query);
        endpart = body;
        ::setValue(headers, std::string("Content-Type"),
                   std::string("application/json"));
      }
    }
    url = add(url, endpoint);
    std::any isFuturePrivate = (isEqual(api, std::string("futuresPrivate")));
    std::any isPrivate = (isEqual(api, std::string("private")));
    std::any isBroker = (isEqual(api, std::string("broker")));
    std::any isEarn = (isEqual(api, std::string("earn")));
    if (isTrue(isTrue(isTrue(isTrue(isTrue(isPrivate) ||
                                    isTrue(isFuturePrivate)) ||
                             isTrue(isBroker)) ||
                      isTrue(isEarn)) ||
               isTrue(isUtaPrivate))) {
      this->checkRequiredCredentials();
      std::any timestamp = toString(this->nonce());
      headers = this->extend(
          ccxt::dict{
              {std::string("KC-API-KEY-VERSION"), std::string("2")},
              {std::string("KC-API-KEY"), this->apiKey},
              {std::string("KC-API-TIMESTAMP"), timestamp},
          },
          headers);
      headers = (isTrue((isEqual(headers, std::any{}))) ? std::any(ccxt::dict{})
                                                        : std::any(headers));
      std::any apiKeyVersion =
          this->safeString(headers, std::string("KC-API-KEY-VERSION"));
      if (isTrue(isEqual(apiKeyVersion, std::string("2")))) {
        std::any passphrase =
            this->hmac(this->encode(this->password), this->encode(this->secret),
                       sha256, std::string("base64"));
        ::setValue(headers, std::string("KC-API-PASSPHRASE"), passphrase);
      } else {
        ::setValue(headers, std::string("KC-API-PASSPHRASE"), this->password);
      }
      std::any payload = add(add(add(timestamp, method), endpoint), endpart);
      std::any signature =
          this->hmac(this->encode(payload), this->encode(this->secret), sha256,
                     std::string("base64"));
      ::setValue(headers, std::string("KC-API-SIGN"), signature);
      std::any partner =
          this->safeDict(this->options, std::string("partner"), ccxt::dict{});
      std::any isUtaFuturePrivate =
          isTrue(isUtaPrivate) &&
          isTrue((isEqual(tradeType, std::string("FUTURES"))));
      std::any isFuturePartner =
          isTrue(isFuturePrivate) || isTrue(isUtaFuturePrivate);
      partner = (isTrue(isFuturePartner)
                     ? std::any(this->safeValue(partner, std::string("future"),
                                                partner))
                     : std::any(this->safeValue(partner, std::string("spot"),
                                                partner)));
      std::any partnerId = this->safeString(partner, std::string("id"));
      std::any partnerSecret =
          this->safeString2(partner, std::string("secret"), std::string("key"));
      if (isTrue(isTrue((!isEqual(partnerId, std::any{}))) &&
                 isTrue((!isEqual(partnerSecret, std::any{}))))) {
        std::any partnerPayload = add(add(timestamp, partnerId), this->apiKey);
        std::any partnerSignature = this->hmac(this->encode(partnerPayload),
                                               this->encode(partnerSecret),
                                               sha256, std::string("base64"));
        ::setValue(headers, std::string("KC-API-PARTNER-SIGN"),
                   partnerSignature);
        ::setValue(headers, std::string("KC-API-PARTNER"), partnerId);
        ::setValue(headers, std::string("KC-API-PARTNER-VERIFY"),
                   std::string("true"));
      }
      if (isTrue(isBroker)) {
        std::any brokerName = this->safeString(partner, std::string("name"));
        if (isTrue(!isEqual(brokerName, std::any{}))) {
          ::setValue(headers, std::string("KC-BROKER-NAME"), brokerName);
        }
      }
    }
    return ccxt::dict{
        {std::string("url"), url},
        {std::string("method"), method},
        {std::string("body"), body},
        {std::string("headers"), headers},
    };
  }

  std::any handleErrors(std::any code, std::any reason, std::any url,
                        std::any method, std::any headers, std::any body,
                        std::any response, std::any requestHeaders,
                        std::any requestBody) override {
    if (isTrue(isTrue((isEqual(response, std::any{}))) ||
               isTrue((isEqual(response, null))))) {
      this->throwBroadlyMatchedException(
          ::getValue(this->exceptions, std::string("broad")), body, body);
      return std::any{};
    }
    //
    // bad
    //     { "code": "400100", "msg":
    //     "validation.createOrder.clientOidIsRequired" }
    // good
    //     { code: '200000', data: { ... }}
    //
    std::any errorCode = this->safeString(response, std::string("code"));
    std::any message = this->safeString2(response, std::string("msg"),
                                         std::string("data"), std::string(""));
    std::any feedback = add(add(this->id, std::string(" ")), body);
    this->throwExactlyMatchedException(
        ::getValue(this->exceptions, std::string("exact")), message, feedback);
    this->throwExactlyMatchedException(
        ::getValue(this->exceptions, std::string("exact")), errorCode,
        feedback);
    this->throwBroadlyMatchedException(
        ::getValue(this->exceptions, std::string("broad")), body, feedback);
    if (isTrue(isTrue(!isEqual(errorCode, std::string("200000"))) &&
               isTrue(!isEqual(errorCode, std::string("200"))))) {
      throw ExchangeError(toString(feedback));
    }
    return std::any{};
  }

  /**
   * @method
   * @name kucoin#fetchTransfers
   * @description fetch a history of internal transfers made on an account
   * @see
   * https://www.kucoin.com/docs-new/rest/account-info/account-funding/get-account-ledgers-spot-margin
   * @param {string} [code] unified currency code of the currency transferred
   * @param {int} [since] the earliest time in ms to fetch transfers for
   * @param {int} [limit] the maximum number of transfer structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch transfers for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [transfer structures]{@link
   * https://docs.ccxt.com/?id=transfer-structure}
   */
  std::shared_future<std::any>
  fetchTransfers(std::any code = std::any{}, std::any since = std::any{},
                 std::any limit = std::any{},
                 std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any paginate = false;
                 std::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchTransfers"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchTransfers"), code, since, limit,
                       params));
                 }
                 std::any request = ccxt::dict{
                     {std::string("bizType"), std::string("TRANSFER")},
                 };
                 std::any until =
                     this->safeInteger(params, std::string("until"));
                 if (isTrue(!isEqual(until, std::any{}))) {
                   params = this->omit(params, std::string("until"));
                   ::setValue(request, std::string("endAt"), until);
                 }
                 std::any currency = std::any{};
                 if (isTrue(!isEqual(code, std::any{}))) {
                   currency = this->currency(code);
                   ::setValue(request, std::string("currency"),
                              ::getValue(currency, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("startAt"), since);
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("pageSize"), limit);
                 } else {
                   ::setValue(request, std::string("pageSize"), 500);
                 }
                 std::any requestparamsVariable = this->handleUntilOption(
                     std::string("endAt"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 std::any response = awaitValue(this->privateGetAccountsLedgers(
                     this->extend(request, params)));
                 //
                 // {
                 //     "code": "200000",
                 //     "data": {
                 //         "currentPage": 1,
                 //         "pageSize": 50,
                 //         "totalNum": 1,
                 //         "totalPage": 1,
                 //         "items": [
                 //             {
                 //                 "id": "611a1e7c6a053300067a88d9",
                 //                 "currency": "USDT",
                 //                 "amount": "10.00059547",
                 //                 "fee": "0",
                 //                 "balance": "0",
                 //                 "accountType": "MAIN",
                 //                 "bizType": "Transfer",
                 //                 "direction": "in",
                 //                 "createdAt": 1629101692950,
                 //                 "context":
                 //                 "{\"orderId\":\"611a1e7c6a053300067a88d9\"}"
                 //             }
                 //         ]
                 //     }
                 // }
                 //
                 std::any data = this->safeDict(response, std::string("data"),
                                                ccxt::dict{});
                 std::any items =
                     this->safeList(data, std::string("items"), ccxt::list{});
                 return this->parseTransfers(items, currency, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name kucoin#fetchPositionsADLRank
   * @description fetches the auto deleveraging rank and risk percentage for a
   * list of symbols
   * @see
   * https://www.kucoin.com/docs-new/rest/futures-trading/positions/get-position-list
   * @param {string[]} [symbols] list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of [auto de leverage structures]{@link
   * https://docs.ccxt.com/?id=auto-de-leverage-structure}
   */
  std::shared_future<std::any>
  fetchPositionsADLRank(std::any symbols = std::any{},
                        std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        symbols = this->marketSymbols(symbols, std::any{}, true,
                                                      true, true);
                        std::any response = awaitValue(
                            this->futuresPrivateGetPositions(params));
                        //
                        //     {
                        //         "code": "200000",
                        //         "data": [
                        //             {
                        //                 "id": "600000000001260912",
                        //                 "symbol": "XBTUSDTM",
                        //                 "crossMode": true,
                        //                 "maintMarginReq": 0.0040000133,
                        //                 "delevPercentage": 0.0,
                        //                 "openingTimestamp": 1768481882915,
                        //                 "currentTimestamp": 1768481897988,
                        //                 "currentQty": 1,
                        //                 "currentCost": 96.9768,
                        //                 "currentComm": 0.05818608,
                        //                 "unrealisedCost": 96.9768,
                        //                 "realisedGrossCost": 0.0,
                        //                 "realisedCost": 0.05818608,
                        //                 "isOpen": true,
                        //                 "markPrice": 96985.6,
                        //                 "markValue": 96.9856,
                        //                 "posCost": 96.9768,
                        //                 "posInit": 4.84884,
                        //                 "posMargin": 4.84928,
                        //                 "posMaint": 0.38794369,
                        //                 "realisedGrossPnl": 0.0,
                        //                 "realisedPnl": -0.05818608,
                        //                 "unrealisedPnl": 0.0088,
                        //                 "unrealisedPnlPcnt": 1.0E-4,
                        //                 "unrealisedRoePcnt": 0.0018,
                        //                 "avgEntryPrice": 96976.8,
                        //                 "liquidationPrice": 52351.69,
                        //                 "bankruptPrice": 52110.87,
                        //                 "settleCurrency": "USDT",
                        //                 "isInverse": false,
                        //                 "maintainMargin": 0.0040000133,
                        //                 "marginMode": "CROSS",
                        //                 "positionSide": "LONG",
                        //                 "leverage": 20,
                        //                 "dealComm": -0.05818608,
                        //                 "fundingFee": 0,
                        //                 "tax": 0
                        //             }
                        //         ]
                        //     }
                        //
                        std::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseADLRanks(data, symbols);
                      })
        .share();
  }

  std::any parseADLRank(std::any info, std::any market = std::any{}) override {
    //
    // fetchPositionsADLRank
    //
    //     {
    //         "id": "600000000001260912",
    //         "symbol": "XBTUSDTM",
    //         "crossMode": true,
    //         "maintMarginReq": 0.0040000133,
    //         "delevPercentage": 0.0,
    //         "openingTimestamp": 1768481882915,
    //         "currentTimestamp": 1768481897988,
    //         "currentQty": 1,
    //         "currentCost": 96.9768,
    //         "currentComm": 0.05818608,
    //         "unrealisedCost": 96.9768,
    //         "realisedGrossCost": 0.0,
    //         "realisedCost": 0.05818608,
    //         "isOpen": true,
    //         "markPrice": 96985.6,
    //         "markValue": 96.9856,
    //         "posCost": 96.9768,
    //         "posInit": 4.84884,
    //         "posMargin": 4.84928,
    //         "posMaint": 0.38794369,
    //         "realisedGrossPnl": 0.0,
    //         "realisedPnl": -0.05818608,
    //         "unrealisedPnl": 0.0088,
    //         "unrealisedPnlPcnt": 1.0E-4,
    //         "unrealisedRoePcnt": 0.0018,
    //         "avgEntryPrice": 96976.8,
    //         "liquidationPrice": 52351.69,
    //         "bankruptPrice": 52110.87,
    //         "settleCurrency": "USDT",
    //         "isInverse": false,
    //         "maintainMargin": 0.0040000133,
    //         "marginMode": "CROSS",
    //         "positionSide": "LONG",
    //         "leverage": 20,
    //         "dealComm": -0.05818608,
    //         "fundingFee": 0,
    //         "tax": 0
    //     }
    //
    std::any marketId = this->safeString(info, std::string("symbol"));
    std::any timestamp =
        this->safeInteger(info, std::string("openingTimestamp"));
    std::any percentage =
        this->safeString(info, std::string("delevPercentage"));
    return ccxt::dict{
        {std::string("info"), info},
        {std::string("symbol"), this->safeSymbol(marketId, market, std::any{},
                                                 std::string("contract"))},
        {std::string("rank"), std::any{}},
        {std::string("rating"), std::any{}},
        {std::string("percentage"), this->parseNumber(ccxt::Precise::stringMul(
                                        percentage, std::string("100")))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }
